QString edit_state_signature(const EditState& state) {
  return QStringLiteral("sha1:%1").arg(QString::fromLatin1(
      QCryptographicHash::hash(
          serialize_edit_recipe_json(state).toUtf8(),
          QCryptographicHash::Sha1)
          .toHex()));
}

AsyncMaskJob make_async_mask_job(
    const QString& job_kind,
    const QString& stage,
    const QString& asset_id,
    const QString& file_path,
    const EditState& state,
    int generation,
    int state_revision) {
  return AsyncMaskJob{
      .job_id = QStringLiteral("%1-%2-%3")
                    .arg(job_kind, QString::number(generation),
                         QUuid::createUuid().toString(QUuid::WithoutBraces)),
      .job_kind = job_kind,
      .stage = stage,
      .asset_id = asset_id,
      .file_path = file_path,
      .state_signature = edit_state_signature(state),
      .generation = generation,
      .state_revision = state_revision,
  };
}

AsyncMaskJob make_thumbnail_refresh_queue_job(
    const QString& asset_id,
    const QString& file_path,
    const EditState& state,
    int generation,
    int state_revision) {
  return AsyncMaskJob{
      .job_id = QStringLiteral("thumbnail-refresh-queue-%1").arg(generation),
      .job_kind = QStringLiteral("thumbnail_refresh"),
      .stage = QStringLiteral("thumbnail_refresh_queue"),
      .asset_id = asset_id,
      .file_path = file_path,
      .state_signature = edit_state_signature(state),
      .generation = generation,
      .state_revision = state_revision,
  };
}

class ScopedBoolValue final {
 public:
  ScopedBoolValue(bool& target, bool value)
      : target_(target),
        previous_(target) {
    target_ = value;
  }
  ScopedBoolValue(const ScopedBoolValue&) = delete;
  ScopedBoolValue& operator=(const ScopedBoolValue&) = delete;
  ~ScopedBoolValue() { target_ = previous_; }

 private:
  bool& target_;
  bool previous_;
};

AsyncMaskJob make_layer_composite_render_job(
    const QString& asset_id,
    const QString& file_path,
    const EditState& state,
    int generation,
    int state_revision) {
  const auto signature = edit_state_signature(state);
  const auto signature_token =
      signature.mid(signature.indexOf(QLatin1Char(':')) + 1, 12);
  return AsyncMaskJob{
      .job_id = QStringLiteral("layer_composite-%1-%2").arg(generation).arg(signature_token),
      .job_kind = QStringLiteral("layer_composite"),
      .stage = QStringLiteral("render_request"),
      .asset_id = asset_id,
      .file_path = file_path,
      .state_signature = signature,
      .generation = generation,
      .state_revision = state_revision,
  };
}

AsyncMaskJob make_full_resolution_preview_render_job(
    const QString& asset_id,
    const QString& file_path,
    const EditState& state,
    int generation,
    int state_revision) {
  const auto signature = edit_state_signature(state);
  const auto signature_token =
      signature.mid(signature.indexOf(QLatin1Char(':')) + 1, 12);
  return AsyncMaskJob{
      .job_id =
          QStringLiteral("full_resolution_preview-%1-%2").arg(generation).arg(signature_token),
      .job_kind = QStringLiteral("full_resolution_preview"),
      .stage = QStringLiteral("render_request"),
      .asset_id = asset_id,
      .file_path = file_path,
      .state_signature = signature,
      .generation = generation,
      .state_revision = state_revision,
  };
}

AsyncMaskJob make_refine_edge_preview_job(
    const QString& asset_id,
    const QString& file_path,
    const EditState& state,
    const QVariantMap& refinement_context,
    int generation,
    int state_revision) {
  const auto signature = QStringLiteral("sha1:%1").arg(QString::fromLatin1(
      QCryptographicHash::hash(
          serialize_edit_recipe_json(state).toUtf8() +
              QJsonDocument::fromVariant(refinement_context).toJson(QJsonDocument::Compact),
          QCryptographicHash::Sha1)
          .toHex()));
  const auto signature_token =
      signature.mid(signature.indexOf(QLatin1Char(':')) + 1, 12);
  return AsyncMaskJob{
      .job_id =
          QStringLiteral("refine_edge_preview-%1-%2").arg(generation).arg(signature_token),
      .job_kind = QStringLiteral("refine_edge_preview"),
      .stage = QStringLiteral("active_preview_cache"),
      .asset_id = asset_id,
      .file_path = file_path,
      .state_signature = signature,
      .generation = generation,
      .state_revision = state_revision,
  };
}

void insert_async_mask_job_fields(QVariantMap* fields, const AsyncMaskJob& job) {
  if (fields == nullptr || job.job_id.isEmpty()) {
    return;
  }
  fields->insert(QStringLiteral("async_job_id"), job.job_id);
  fields->insert(QStringLiteral("async_job_kind"), job.job_kind);
  fields->insert(QStringLiteral("async_job_stage"), job.stage);
  fields->insert(QStringLiteral("async_job_asset_id"), job.asset_id);
  fields->insert(QStringLiteral("async_job_file_path"), job.file_path);
  fields->insert(QStringLiteral("async_job_state_signature"), job.state_signature);
}

void insert_thumbnail_job_fields(
    QVariantMap* fields,
    const AsyncMaskJob& job,
    qint64 elapsed_ms,
    qint64 budget_ms) {
  insert_async_mask_job_fields(fields, job);
  if (fields == nullptr || job.job_id.isEmpty()) {
    return;
  }
  fields->insert(QStringLiteral("async_job_generation"), job.generation);
  fields->insert(QStringLiteral("async_job_state_revision"), job.state_revision);
  fields->insert(QStringLiteral("thumbnailId"), job.job_id);
  fields->insert(QStringLiteral("thumbnail_id"), job.job_id);
  fields->insert(QStringLiteral("observabilityThumbnailId"), job.job_id);
  fields->insert(QStringLiteral("thumbnailJobId"), job.job_id);
  fields->insert(QStringLiteral("thumbnailJobKind"), job.job_kind);
  fields->insert(QStringLiteral("thumbnailJobStage"), job.stage);
  fields->insert(QStringLiteral("thumbnailJobGeneration"), job.generation);
  fields->insert(QStringLiteral("thumbnailJobStateRevision"), job.state_revision);
  fields->insert(QStringLiteral("thumbnailJobStateSignature"), job.state_signature);
  fields->insert(QStringLiteral("thumbnail_render_budget_ms"), budget_ms);
  fields->insert(QStringLiteral("thumbnail_render_elapsed_ms"), elapsed_ms);
  fields->insert(
      QStringLiteral("thumbnail_render_within_latency_budget"),
      elapsed_ms <= budget_ms);
  fields->insert(
      QStringLiteral("thumbnail_render_stage_contract"),
      QStringLiteral("layer-mask-render-stage-telemetry-v1"));
  fields->insert(QStringLiteral("thumbnail_render_stage"), QStringLiteral("thumbnail_render"));
}

