QString normalized_render_reason(const QString& reason, bool schedule_full_resolution) {
  const auto normalized = reason.trimmed().toLower();
  if (!normalized.isEmpty()) {
    return normalized;
  }
  return schedule_full_resolution ? QStringLiteral("edit_change") : QStringLiteral("interactive_change");
}

bool render_reason_invalidates_preview_overlay(const QString& reason) {
  return reason == QStringLiteral("asset_select") ||
         reason == QStringLiteral("compare_toggle") ||
         reason == QStringLiteral("compare_adjustment_change") ||
         reason == QStringLiteral("reference_change") ||
         reason == QStringLiteral("crop_change") ||
         reason == QStringLiteral("output_profile_change");
}

bool render_result_can_preserve_higher_resolution_native_texture(
    const RenderResult& result) {
  return result.render_reason == QStringLiteral("viewport_change") ||
         result.render_reason == QStringLiteral("compare_toggle") ||
         result.dirty_domain == QStringLiteral("publish_texture");
}

bool force_draft_interactive_for_reason(const QString& reason) {
  return reason == QStringLiteral("mask_preview_change");
}

QString interaction_mode_for_request(bool full_resolution, bool draft_interactive) {
  if (full_resolution) {
    return QStringLiteral("full_resolution");
  }
  return draft_interactive ? QStringLiteral("draft_interactive") : QStringLiteral("interactive");
}

bool should_skip_edited_image_provider_publish(
    bool native_uploaded,
    bool native_partial_upload,
    bool compare_mode,
    const QImage& reference_preview_image) {
  return native_uploaded && native_partial_upload && !compare_mode &&
         reference_preview_image.isNull();
}

QString render_mode_for_request(bool full_resolution, bool draft_interactive) {
  if (full_resolution) {
    return QStringLiteral("max_preview");
  }
  return draft_interactive ? QStringLiteral("live_preview") : QStringLiteral("settled_preview");
}

int render_priority_for_mode(const QString& render_mode) {
  if (render_mode == QStringLiteral("live_preview") ||
      render_mode == QStringLiteral("visible_overlay")) {
    return 0;
  }
  if (render_mode == QStringLiteral("settled_preview")) {
    return 1;
  }
  if (render_mode == QStringLiteral("max_preview_visible_tile")) {
    return 2;
  }
  if (render_mode == QStringLiteral("max_preview")) {
    return 3;
  }
  return 6;
}

qint64 render_latency_budget_for_request(bool full_resolution, bool draft_interactive) {
  if (full_resolution) {
    return kFullResolutionSettledPreviewLatencyBudgetMs;
  }
  return draft_interactive
             ? kDraftInteractivePreviewLatencyBudgetMs
             : kSettledInteractivePreviewLatencyBudgetMs;
}

