bool copy_working_rect_to_linear_patch(
    const LinearPatchCopyJob& job,
    uchar* patch_bits,
    qsizetype patch_bytes_per_line,
    photo_editor::pipeline::CancellationToken cancellation) {
  if (job.working == nullptr || job.working->isNull() || patch_bits == nullptr ||
      patch_bytes_per_line <= 0 || job.source_rect.isEmpty() || job.destination_rect.isEmpty() ||
      job.source_rect.size() != job.destination_rect.size() ||
      !QRect(0, 0, job.working->width, job.working->height).contains(job.source_rect)) {
    return false;
  }

  for (int y = 0; y < job.source_rect.height(); ++y) {
    if (cancellation.cancelled()) {
      return false;
    }
    const auto source_y = job.source_rect.y() + y;
    const auto source_offset = static_cast<std::size_t>(
        source_y * job.working->width + job.source_rect.x());
    auto* dest_scanline = reinterpret_cast<QRgbaFloat16*>(
        patch_bits + static_cast<qsizetype>(job.destination_rect.y() + y) *
                         patch_bytes_per_line);
    dest_scanline += job.destination_rect.x();
    for (int x = 0; x < job.source_rect.width(); ++x) {
      const auto& pixel = job.working->pixels[source_offset + static_cast<std::size_t>(x)];
      dest_scanline[x] = QRgbaFloat16{
          qfloat16(std::max(0.0F, pixel.red)),
          qfloat16(std::max(0.0F, pixel.green)),
          qfloat16(std::max(0.0F, pixel.blue)),
          qfloat16(photo_editor::pipeline::clamp_unit(pixel.alpha)),
      };
    }
  }
  return true;
}

