int clamp_preview_target_edge(int edge) {
  if (edge <= 0) {
    return kDefaultInteractivePreviewEdge;
  }
  return qBound(kMinimumInteractivePreviewEdge, edge, kMaximumInteractivePreviewEdge);
}

QSize scaled_size_for_max_edge(const QSize& source_size, int max_edge) {
  if (!source_size.isValid() || max_edge <= 0) {
    return {};
  }
  if (std::max(source_size.width(), source_size.height()) <= max_edge) {
    return source_size;
  }
  return source_size.scaled(max_edge, max_edge, Qt::KeepAspectRatio);
}

QByteArray union_segmentation_masks(
    const QByteArray& existing_data,
    int existing_width,
    int existing_height,
    const QByteArray& incoming_data,
    int incoming_width,
    int incoming_height) {
  if (!valid_segmentation_payload(incoming_data, incoming_width, incoming_height)) {
    return existing_data;
  }

  if (!valid_segmentation_payload(existing_data, existing_width, existing_height) ||
      existing_width != incoming_width || existing_height != incoming_height) {
    return incoming_data;
  }

  QByteArray merged(existing_data);
  const auto size = std::min(merged.size(), incoming_data.size());
  for (int index = 0; index < size; ++index) {
    merged[index] = static_cast<char>(std::max(
        static_cast<unsigned char>(merged.at(index)),
        static_cast<unsigned char>(incoming_data.at(index))));
  }
  return merged;
}

QByteArray subtract_segmentation_mask(
    const QByteArray& existing_data,
    int existing_width,
    int existing_height,
    const QByteArray& incoming_data,
    int incoming_width,
    int incoming_height) {
  if (!valid_segmentation_payload(existing_data, existing_width, existing_height) ||
      !valid_segmentation_payload(incoming_data, incoming_width, incoming_height) ||
      existing_width != incoming_width || existing_height != incoming_height) {
    return existing_data;
  }

  QByteArray merged(existing_data);
  const auto size = std::min(merged.size(), incoming_data.size());
  for (int index = 0; index < size; ++index) {
    const auto existing = static_cast<int>(static_cast<unsigned char>(merged.at(index)));
    const auto incoming = static_cast<int>(static_cast<unsigned char>(incoming_data.at(index)));
    merged[index] = static_cast<char>(std::max(0, existing - incoming));
  }
  return merged;
}

struct ObjectRemoveExpansionResult final {
  QByteArray data;
  int original_pixels = 0;
  int expanded_pixels = 0;
  int added_pixels = 0;
  int edge_radius_px = 0;
  int shadow_reflection_pixels = 0;
  int shadow_reflection_extent_px = 0;
  bool supported = false;
};

ObjectRemoveExpansionResult expand_object_remove_mask_for_shadow_reflection(
    const QByteArray& source_data,
    int width,
    int height) {
  ObjectRemoveExpansionResult result;
  if (!valid_segmentation_payload(source_data, width, height)) {
    return result;
  }

  auto left = width;
  auto right = -1;
  auto top = height;
  auto bottom = -1;
  for (int y = 0; y < height; ++y) {
    for (int x = 0; x < width; ++x) {
      const auto alpha = static_cast<unsigned char>(source_data.at(y * width + x));
      if (alpha == 0) {
        continue;
      }
      ++result.original_pixels;
      left = std::min(left, x);
      right = std::max(right, x);
      top = std::min(top, y);
      bottom = std::max(bottom, y);
    }
  }
  if (result.original_pixels <= 0 || left > right || top > bottom) {
    return result;
  }

  result.data = source_data;
  result.supported = true;
  const auto object_width = right - left + 1;
  const auto object_height = bottom - top + 1;
  result.edge_radius_px = std::clamp(
      static_cast<int>(std::lround(std::max(object_width, object_height) * 0.045)),
      1,
      std::max(1, std::min(width, height) / 14));
  result.shadow_reflection_extent_px = std::clamp(
      static_cast<int>(std::lround(object_height * 0.22)),
      result.edge_radius_px,
      std::max(result.edge_radius_px, height / 5));

  const auto write_alpha = [&](int x, int y, int alpha, bool shadow_reflection) {
    if (x < 0 || x >= width || y < 0 || y >= height || alpha <= 0) {
      return;
    }
    const auto index = y * width + x;
    const auto current = static_cast<unsigned char>(result.data.at(index));
    const auto next = static_cast<unsigned char>(std::min(255, alpha));
    if (next <= current) {
      return;
    }
    if (current == 0) {
      ++result.added_pixels;
      if (shadow_reflection) {
        ++result.shadow_reflection_pixels;
      }
    }
    result.data[index] = static_cast<char>(next);
  };

  const auto radius = result.edge_radius_px;
  const auto radius_sq = radius * radius;
  for (int y = top; y <= bottom; ++y) {
    for (int x = left; x <= right; ++x) {
      const auto alpha = static_cast<unsigned char>(source_data.at(y * width + x));
      if (alpha == 0) {
        continue;
      }
      for (int dy = -radius; dy <= radius; ++dy) {
        for (int dx = -radius; dx <= radius; ++dx) {
          const auto distance_sq = dx * dx + dy * dy;
          if (distance_sq > radius_sq) {
            continue;
          }
          const auto distance = std::sqrt(static_cast<double>(distance_sq));
          const auto falloff = 1.0 - std::clamp(distance / static_cast<double>(radius + 1), 0.0, 1.0);
          write_alpha(
              x + dx,
              y + dy,
              std::max(24, static_cast<int>(std::lround(static_cast<double>(alpha) * falloff))),
              false);
        }
      }
    }
  }

  const auto shadow_pad = std::max(radius, object_width / 5);
  for (int y = bottom + 1; y <= bottom + result.shadow_reflection_extent_px; ++y) {
    const auto t = result.shadow_reflection_extent_px > 0
                       ? static_cast<double>(y - bottom) /
                             static_cast<double>(result.shadow_reflection_extent_px + 1)
                       : 1.0;
    const auto alpha = static_cast<int>(std::lround(118.0 * (1.0 - t)));
    for (int x = left - shadow_pad; x <= right + shadow_pad; ++x) {
      write_alpha(x, y, alpha, true);
    }
  }

  result.expanded_pixels = selected_pixel_count_for_mask_data(result.data);
  result.added_pixels = std::max(0, result.expanded_pixels - result.original_pixels);
  return result;
}

void apply_object_remove_assisted_expansion(
    QVariantMap* mask,
    const QImage& source_image,
    const QString& runtime_label,
    const QVariantList& prompts) {
  if (mask == nullptr) {
    return;
  }
  const auto width = mask->value(QStringLiteral("segmentationWidth")).toInt();
  const auto height = mask->value(QStringLiteral("segmentationHeight")).toInt();
  const auto source_data = mask->value(QStringLiteral("segmentationData")).toByteArray();
  const auto expansion =
      expand_object_remove_mask_for_shadow_reflection(source_data, width, height);
  if (!expansion.supported || !valid_segmentation_payload(expansion.data, width, height)) {
    return;
  }

  mask->insert(QStringLiteral("segmentationData"), expansion.data);
  mask->insert(QStringLiteral("objectRemoveAssisted"), true);
  mask->insert(QStringLiteral("objectRemoveAssistSchemaVersion"), 1);
  mask->insert(QStringLiteral("objectRemoveAssistMode"), QStringLiteral("object-plus-shadow-reflection"));
  mask->insert(QStringLiteral("objectRemoveRuntime"), runtime_label.trimmed());
  mask->insert(QStringLiteral("objectRemoveOriginalPixelCount"), expansion.original_pixels);
  mask->insert(QStringLiteral("objectRemoveExpandedPixelCount"), expansion.expanded_pixels);
  mask->insert(QStringLiteral("objectRemoveExpansionPixels"), expansion.added_pixels);
  mask->insert(QStringLiteral("objectRemoveExpansionRadiusPx"), expansion.edge_radius_px);
  mask->insert(QStringLiteral("objectRemoveShadowReflectionPixels"), expansion.shadow_reflection_pixels);
  mask->insert(QStringLiteral("objectRemoveShadowReflectionExtentPx"), expansion.shadow_reflection_extent_px);

  auto metadata = mask->value(QStringLiteral("generatedMaskMetadata")).toMap();
  metadata.insert(QStringLiteral("objectRemoveAssisted"), true);
  metadata.insert(QStringLiteral("objectRemoveAssistSchemaVersion"), 1);
  metadata.insert(QStringLiteral("objectRemoveAssistMode"), QStringLiteral("object-plus-shadow-reflection"));
  metadata.insert(QStringLiteral("objectRemoveRuntime"), runtime_label.trimmed());
  metadata.insert(QStringLiteral("objectRemoveSourceResolution"), QStringLiteral("%1x%2").arg(width).arg(height));
  metadata.insert(QStringLiteral("objectRemoveOriginalPixelCount"), expansion.original_pixels);
  metadata.insert(QStringLiteral("objectRemoveExpandedPixelCount"), expansion.expanded_pixels);
  metadata.insert(QStringLiteral("objectRemoveExpansionPixels"), expansion.added_pixels);
  metadata.insert(QStringLiteral("objectRemoveExpansionRadiusPx"), expansion.edge_radius_px);
  metadata.insert(QStringLiteral("objectRemoveShadowReflectionPixels"), expansion.shadow_reflection_pixels);
  metadata.insert(QStringLiteral("objectRemoveShadowReflectionExtentPx"), expansion.shadow_reflection_extent_px);
  metadata.insert(QStringLiteral("objectRemoveSourceImageAvailable"), !source_image.isNull());
  metadata.insert(QStringLiteral("objectRemovePromptCount"), prompts.size());
  mask->insert(QStringLiteral("generatedMaskMetadata"), metadata);
}

struct DustSpotCandidate final {
  int x = 0;
  int y = 0;
  double radius = 0.0;
  double score = 0.0;
};

double dust_luminance_for_pixel(const QColor& color) {
  const auto red = photo_editor::pipeline::srgb_to_linear(color.redF());
  const auto green = photo_editor::pipeline::srgb_to_linear(color.greenF());
  const auto blue = photo_editor::pipeline::srgb_to_linear(color.blueF());
  return red * 0.2126 + green * 0.7152 + blue * 0.0722;
}

std::vector<DustSpotCandidate> detect_dust_spots(
    const QImage& image,
    int maximum_spots) {
  std::vector<DustSpotCandidate> spots;
  if (image.isNull() || image.width() < 16 || image.height() < 16 ||
      maximum_spots <= 0) {
    return spots;
  }

  const auto source = image.convertToFormat(QImage::Format_ARGB32);
  const auto width = source.width();
  const auto height = source.height();
  std::vector<double> luminance(static_cast<std::size_t>(width * height), 0.0);
  for (int y = 0; y < height; ++y) {
    for (int x = 0; x < width; ++x) {
      luminance[static_cast<std::size_t>(y * width + x)] =
          dust_luminance_for_pixel(QColor::fromRgb(source.pixel(x, y)));
    }
  }

  const auto luma_at = [&](int x, int y) {
    return luminance[static_cast<std::size_t>(y * width + x)];
  };

  std::vector<DustSpotCandidate> candidates;
  candidates.reserve(256);
  constexpr auto kMargin = 7;
  for (int y = kMargin; y < height - kMargin; ++y) {
    for (int x = kMargin; x < width - kMargin; ++x) {
      auto center_sum = 0.0;
      auto center_count = 0;
      for (int dy = -1; dy <= 1; ++dy) {
        for (int dx = -1; dx <= 1; ++dx) {
          center_sum += luma_at(x + dx, y + dy);
          ++center_count;
        }
      }
      const auto center_mean = center_sum / static_cast<double>(center_count);

      auto ring_sum = 0.0;
      auto ring_square_sum = 0.0;
      auto ring_count = 0;
      for (int dy = -7; dy <= 7; ++dy) {
        for (int dx = -7; dx <= 7; ++dx) {
          const auto distance = std::hypot(static_cast<double>(dx), static_cast<double>(dy));
          if (distance < 3.5 || distance > 7.5) {
            continue;
          }
          const auto value = luma_at(x + dx, y + dy);
          ring_sum += value;
          ring_square_sum += value * value;
          ++ring_count;
        }
      }
      if (ring_count == 0) {
        continue;
      }

      const auto ring_mean = ring_sum / static_cast<double>(ring_count);
      const auto ring_variance =
          std::max(0.0, ring_square_sum / static_cast<double>(ring_count) - ring_mean * ring_mean);
      const auto ring_texture = std::sqrt(ring_variance);
      const auto contrast = ring_mean - center_mean;
      const auto threshold = std::max(0.035, ring_mean * 0.13);
      if (ring_mean < 0.08 || contrast < threshold || ring_texture > 0.11) {
        continue;
      }

      auto local_minimum = true;
      for (int dy = -2; dy <= 2 && local_minimum; ++dy) {
        for (int dx = -2; dx <= 2; ++dx) {
          if (dx == 0 && dy == 0) {
            continue;
          }
          if (luma_at(x, y) > luma_at(x + dx, y + dy) + 0.003) {
            local_minimum = false;
            break;
          }
        }
      }
      if (!local_minimum) {
        continue;
      }

      candidates.push_back(DustSpotCandidate{
          .x = x,
          .y = y,
          .radius = std::clamp(2.4 + contrast * 18.0, 2.4, 7.5),
          .score = contrast * ring_mean * (1.0 - std::min(1.0, ring_texture / 0.11)),
      });
    }
  }

  std::sort(candidates.begin(), candidates.end(), [](const auto& left, const auto& right) {
    return left.score > right.score;
  });

  const auto cluster_radius =
      std::clamp(static_cast<double>(std::min(width, height)) * 0.035, 10.0, 36.0);
  for (const auto& candidate : candidates) {
    auto clustered_candidate = candidate;
    auto weighted_x = 0.0;
    auto weighted_y = 0.0;
    auto weight_sum = 0.0;
    auto maximum_cluster_distance = 0.0;
    for (const auto& neighbor : candidates) {
      const auto distance =
          std::hypot(static_cast<double>(candidate.x - neighbor.x),
                     static_cast<double>(candidate.y - neighbor.y));
      if (distance > cluster_radius) {
        continue;
      }
      const auto weight = std::max(1e-6, neighbor.score);
      weighted_x += static_cast<double>(neighbor.x) * weight;
      weighted_y += static_cast<double>(neighbor.y) * weight;
      weight_sum += weight;
    }
    if (weight_sum > 0.0) {
      clustered_candidate.x = std::clamp(
          static_cast<int>(std::lround(weighted_x / weight_sum)), 0, width - 1);
      clustered_candidate.y = std::clamp(
          static_cast<int>(std::lround(weighted_y / weight_sum)), 0, height - 1);
      for (const auto& neighbor : candidates) {
        const auto distance_from_cluster =
            std::hypot(static_cast<double>(clustered_candidate.x - neighbor.x),
                       static_cast<double>(clustered_candidate.y - neighbor.y));
        const auto distance_from_seed =
            std::hypot(static_cast<double>(candidate.x - neighbor.x),
                       static_cast<double>(candidate.y - neighbor.y));
        if (distance_from_seed <= cluster_radius) {
          maximum_cluster_distance = std::max(maximum_cluster_distance, distance_from_cluster);
        }
      }
      clustered_candidate.radius = std::clamp(
          std::max(clustered_candidate.radius, maximum_cluster_distance * 0.65 + 4.0),
          2.4,
          24.0);
    }

    auto suppressed = false;
    for (const auto& accepted : spots) {
      const auto distance =
          std::hypot(static_cast<double>(clustered_candidate.x - accepted.x),
                     static_cast<double>(clustered_candidate.y - accepted.y));
      if (distance < std::max(6.0, clustered_candidate.radius + accepted.radius)) {
        suppressed = true;
        break;
      }
    }
    if (suppressed) {
      continue;
    }
    spots.push_back(clustered_candidate);
    if (static_cast<int>(spots.size()) >= maximum_spots) {
      break;
    }
  }
  return spots;
}

QByteArray dust_spot_mask_data(
    int width,
    int height,
    const std::vector<DustSpotCandidate>& spots) {
  QByteArray data(width * height, '\0');
  for (const auto& spot : spots) {
    const auto radius = std::max(1.5, spot.radius);
    const auto min_x = std::max(0, static_cast<int>(std::floor(static_cast<double>(spot.x) - radius * 1.35)));
    const auto max_x = std::min(width - 1, static_cast<int>(std::ceil(static_cast<double>(spot.x) + radius * 1.35)));
    const auto min_y = std::max(0, static_cast<int>(std::floor(static_cast<double>(spot.y) - radius * 1.35)));
    const auto max_y = std::min(height - 1, static_cast<int>(std::ceil(static_cast<double>(spot.y) + radius * 1.35)));
    for (int y = min_y; y <= max_y; ++y) {
      for (int x = min_x; x <= max_x; ++x) {
        const auto distance =
            std::hypot(static_cast<double>(x - spot.x), static_cast<double>(y - spot.y));
        const auto weight = 1.0 - smoothstep(0.42, 1.0, distance / radius);
        if (weight <= 1e-6) {
          continue;
        }
        const auto index = y * width + x;
        data[index] = static_cast<char>(std::max(
            static_cast<int>(static_cast<unsigned char>(data.at(index))),
            static_cast<int>(std::lround(clamp_unit(weight) * 255.0))));
      }
    }
  }
  return data;
}

struct SensorDustMapPayload final {
  QByteArray segmentation_data;
  int width = 0;
  int height = 0;
  double remove_strength = 74.0;
  double feather = 0.72;
  bool valid = false;
};

QString sensor_dust_map_key(const QString& camera_label, const QString& lens_model) {
  const auto identity =
      QStringLiteral("%1|%2")
          .arg(camera_label.simplified().isEmpty() ? QStringLiteral("unknown-camera") : camera_label.simplified(),
               lens_model.simplified().isEmpty() ? QStringLiteral("unknown-lens") : lens_model.simplified());
  return QString::fromLatin1(
      QCryptographicHash::hash(identity.toUtf8(), QCryptographicHash::Sha256).toHex());
}

QString sensor_dust_map_path(const QString& camera_label, const QString& lens_model) {
  const auto root = QDir(AppBootstrap::appDataLocation()).filePath(QStringLiteral("sensor-dust-maps"));
  return QDir(root).filePath(QStringLiteral("%1.json").arg(sensor_dust_map_key(camera_label, lens_model)));
}

bool write_sensor_dust_map(
    const QString& camera_label,
    const QString& lens_model,
    const QByteArray& segmentation_data,
    int width,
    int height,
    double remove_strength,
    double feather) {
  if (!valid_segmentation_payload(segmentation_data, width, height)) {
    return false;
  }

  const auto path = sensor_dust_map_path(camera_label, lens_model);
  if (!QDir().mkpath(QFileInfo(path).absolutePath())) {
    return false;
  }

  QJsonObject object;
  object.insert(QStringLiteral("version"), 1);
  object.insert(QStringLiteral("cameraLabel"), camera_label);
  object.insert(QStringLiteral("lensModel"), lens_model);
  object.insert(QStringLiteral("width"), width);
  object.insert(QStringLiteral("height"), height);
  object.insert(QStringLiteral("removeStrength"), remove_strength);
  object.insert(QStringLiteral("feather"), feather);
  object.insert(QStringLiteral("segmentationData"), QString::fromLatin1(segmentation_data.toBase64()));

  QSaveFile file(path);
  if (!file.open(QIODevice::WriteOnly)) {
    return false;
  }
  file.write(QJsonDocument(object).toJson(QJsonDocument::Compact));
  return file.commit();
}

SensorDustMapPayload read_sensor_dust_map(const QString& camera_label, const QString& lens_model) {
  SensorDustMapPayload payload;
  QFile file(sensor_dust_map_path(camera_label, lens_model));
  if (!file.open(QIODevice::ReadOnly)) {
    return payload;
  }

  const auto document = QJsonDocument::fromJson(file.readAll());
  if (!document.isObject()) {
    return payload;
  }
  const auto object = document.object();
  payload.width = object.value(QStringLiteral("width")).toInt();
  payload.height = object.value(QStringLiteral("height")).toInt();
  payload.remove_strength = object.value(QStringLiteral("removeStrength")).toDouble(74.0);
  payload.feather = object.value(QStringLiteral("feather")).toDouble(0.72);
  payload.segmentation_data =
      QByteArray::fromBase64(object.value(QStringLiteral("segmentationData")).toString().toLatin1());
  payload.valid = valid_segmentation_payload(payload.segmentation_data, payload.width, payload.height);
  return payload;
}

QByteArray resample_segmentation_mask(
    const QByteArray& source_data,
    int source_width,
    int source_height,
    int target_width,
    int target_height) {
  if (!valid_segmentation_payload(source_data, source_width, source_height) ||
      target_width <= 0 || target_height <= 0) {
    return {};
  }
  if (source_width == target_width && source_height == target_height) {
    return source_data;
  }

  QByteArray target_data(target_width * target_height, '\0');
  for (int y = 0; y < target_height; ++y) {
    const auto source_y =
        target_height > 1
            ? static_cast<double>(y) * static_cast<double>(source_height - 1) /
                  static_cast<double>(target_height - 1)
            : 0.0;
    const auto y0 = std::clamp(static_cast<int>(std::floor(source_y)), 0, source_height - 1);
    const auto y1 = std::min(source_height - 1, y0 + 1);
    const auto fy = source_y - static_cast<double>(y0);
    for (int x = 0; x < target_width; ++x) {
      const auto source_x =
          target_width > 1
              ? static_cast<double>(x) * static_cast<double>(source_width - 1) /
                    static_cast<double>(target_width - 1)
              : 0.0;
      const auto x0 = std::clamp(static_cast<int>(std::floor(source_x)), 0, source_width - 1);
      const auto x1 = std::min(source_width - 1, x0 + 1);
      const auto fx = source_x - static_cast<double>(x0);
      const auto sample = [&](int sample_x, int sample_y) {
        return static_cast<double>(
            static_cast<unsigned char>(source_data.at(sample_y * source_width + sample_x)));
      };
      const auto top = std::lerp(sample(x0, y0), sample(x1, y0), fx);
      const auto bottom = std::lerp(sample(x0, y1), sample(x1, y1), fx);
      target_data[y * target_width + x] =
          static_cast<char>(std::lround(std::lerp(top, bottom, fy)));
    }
  }
  return target_data;
}

QRect rasterize_brush_point_into_mask(
    QVariantMap* mask,
    const QImage* source_image,
    double normalized_x,
    double normalized_y,
    double brush_size,
    double brush_flow,
    double brush_opacity,
    double feather,
    bool erase,
    bool auto_mask,
    double auto_mask_tolerance,
    double auto_mask_anchor_x,
    double auto_mask_anchor_y,
    bool protect_edges,
    photo_editor::pipeline::CancellationToken cancellation,
    bool* cancelled,
    qint64* auto_mask_candidate_pixels,
    qint64* auto_mask_edge_evaluation_pixels);

bool append_brush_point_from_variant(
    const QVariant& point_value,
    double fallback_size,
    double fallback_flow,
    QVector<BrushPreviewPoint>* points) {
  if (points == nullptr) {
    return false;
  }

  const auto point = point_value.toMap();
  if (point.isEmpty()) {
    return false;
  }

  points->append(BrushPreviewPoint{
      .x = map_double_value(point, QStringLiteral("x"), 0.5),
      .y = map_double_value(point, QStringLiteral("y"), 0.5),
      .size = map_double_value(point, QStringLiteral("size"), fallback_size),
      .flow = map_double_value(point, QStringLiteral("flow"), fallback_flow),
      .opacity = map_double_value(point, QStringLiteral("opacity"), 1.0),
      .auto_mask_anchor_x = map_double_value(
          point,
          QStringLiteral("autoMaskAnchorX"),
          map_double_value(point, QStringLiteral("x"), 0.5)),
      .auto_mask_anchor_y = map_double_value(
          point,
          QStringLiteral("autoMaskAnchorY"),
          map_double_value(point, QStringLiteral("y"), 0.5)),
      .pressure = map_double_value(point, QStringLiteral("pressure"), 1.0),
      .tilt_x = map_double_value(point, QStringLiteral("tiltX"), 0.0),
      .tilt_y = map_double_value(point, QStringLiteral("tiltY"), 0.0),
      .erase = map_bool_value(point, QStringLiteral("erase"), false),
  });
  return true;
}

QVector<BrushPreviewPoint> brush_points_for_target_raster_replay(const QVariantMap& mask) {
  QVector<BrushPreviewPoint> points;
  const auto fallback_size = map_double_value(mask, QStringLiteral("brushSize"), 0.08);
  const auto fallback_flow = map_double_value(mask, QStringLiteral("brushFlow"), 1.0);
  const auto brush_points = mask.value(QStringLiteral("brushPoints")).toList();
  points.reserve(brush_points.size());
  for (const auto& point_value : brush_points) {
    (void)append_brush_point_from_variant(point_value, fallback_size, fallback_flow, &points);
  }
  if (!points.isEmpty()) {
    return points;
  }

  const auto strokes = mask.value(QStringLiteral("brushStrokes")).toList();
  for (const auto& stroke_value : strokes) {
    const auto stroke = stroke_value.toMap();
    const auto erase_stroke =
        stroke.value(QStringLiteral("operation")).toString().trimmed().toLower() ==
        QStringLiteral("erase");
    const auto samples = stroke.value(QStringLiteral("samples")).toList();
    points.reserve(points.size() + samples.size());
    for (const auto& sample_value : samples) {
      const auto previous_count = points.size();
      if (append_brush_point_from_variant(sample_value, fallback_size, fallback_flow, &points) &&
          erase_stroke && points.size() > previous_count) {
        points.last().erase = true;
      }
    }
  }
  return points;
}

QVariantMap mask_with_rebuilt_brush_matte(
    const QVariantMap& mask,
    const QSize& target_size,
    const QString& purpose) {
  const auto target_width = std::max(1, target_size.width());
  const auto target_height = std::max(1, target_size.height());
  if (normalized_mask_kind(mask.value(QStringLiteral("kind")).toString()) != QStringLiteral("brush") ||
      target_width <= 1 || target_height <= 1) {
    return {};
  }

  const auto points = brush_points_for_target_raster_replay(mask);
  if (points.isEmpty()) {
    return {};
  }

  auto rebuilt_mask = mask;
  rebuilt_mask.insert(QStringLiteral("segmentationData"), QByteArray(target_width * target_height, '\0'));
  rebuilt_mask.insert(QStringLiteral("segmentationWidth"), target_width);
  rebuilt_mask.insert(QStringLiteral("segmentationHeight"), target_height);
  const auto feather = map_double_value(mask, QStringLiteral("feather"), 0.75);
  for (const auto& point : points) {
    (void)rasterize_brush_point_into_mask(
        &rebuilt_mask,
        nullptr,
        point.x,
        point.y,
        point.size,
        point.flow,
        point.opacity,
        feather,
        point.erase,
        false,
        0.18,
        point.auto_mask_anchor_x,
        point.auto_mask_anchor_y,
        false,
        photo_editor::pipeline::CancellationToken{},
        nullptr,
        nullptr,
        nullptr);
  }
  rebuilt_mask.insert(QStringLiteral("scaledMattePurpose"), purpose);
  rebuilt_mask.insert(
      QStringLiteral("scaledMatteSourceWidth"),
      mask.value(QStringLiteral("segmentationWidth"), target_width).toInt());
  rebuilt_mask.insert(
      QStringLiteral("scaledMatteSourceHeight"),
      mask.value(QStringLiteral("segmentationHeight"), target_height).toInt());
  rebuilt_mask.insert(QStringLiteral("scaledMatteWidth"), target_width);
  rebuilt_mask.insert(QStringLiteral("scaledMatteHeight"), target_height);
  rebuilt_mask.insert(QStringLiteral("scaledMatteRebuiltFromBrushStrokes"), true);
  rebuilt_mask.insert(QStringLiteral("scaledMatteBrushReplayPointCount"), points.size());
  return rebuilt_mask;
}

QVariantMap mask_with_scaled_segmentation_matte(
    const QVariantMap& mask,
    const QSize& target_size,
    const QString& purpose) {
  if (!target_size.isValid() || target_size.width() <= 0 || target_size.height() <= 0) {
    return mask;
  }

  const auto rebuilt_brush = mask_with_rebuilt_brush_matte(mask, target_size, purpose);
  if (!rebuilt_brush.isEmpty()) {
    return rebuilt_brush;
  }

  const auto source_data = mask.value(QStringLiteral("segmentationData")).toByteArray();
  const auto source_width = mask.value(QStringLiteral("segmentationWidth")).toInt();
  const auto source_height = mask.value(QStringLiteral("segmentationHeight")).toInt();
  if (!valid_segmentation_payload(source_data, source_width, source_height)) {
    return mask;
  }

  const auto target_width = std::max(1, target_size.width());
  const auto target_height = std::max(1, target_size.height());
  if (source_width == target_width && source_height == target_height) {
    auto scaled_mask = mask;
    scaled_mask.insert(QStringLiteral("scaledMattePurpose"), purpose);
    scaled_mask.insert(
        QStringLiteral("scaledMatteSourceWidth"),
        mask.value(QStringLiteral("scaledMatteSourceWidth"), source_width).toInt());
    scaled_mask.insert(
        QStringLiteral("scaledMatteSourceHeight"),
        mask.value(QStringLiteral("scaledMatteSourceHeight"), source_height).toInt());
    scaled_mask.insert(QStringLiteral("scaledMatteWidth"), target_width);
    scaled_mask.insert(QStringLiteral("scaledMatteHeight"), target_height);
    return scaled_mask;
  }

  const auto cache_key = scaled_mask_matte_cache_key(
      source_data,
      source_width,
      source_height,
      target_width,
      target_height,
      purpose);
  auto scaled = QByteArray();
  if (!cache_key.isEmpty()) {
    auto& cache = scaled_mask_matte_cache();
    QMutexLocker locker(&cache.mutex);
    cache.find(cache_key, &scaled);
  }
  if (scaled.isEmpty()) {
    scaled = resample_segmentation_mask(
        source_data,
        source_width,
        source_height,
        target_width,
        target_height);
    if (!scaled.isEmpty() && !cache_key.isEmpty()) {
      auto& cache = scaled_mask_matte_cache();
      QMutexLocker locker(&cache.mutex);
      cache.insert(
          cache_key,
          scaled,
          QSize(source_width, source_height),
          QSize(target_width, target_height),
          purpose);
    }
  }
  if (scaled.isEmpty()) {
    return mask;
  }

  auto scaled_mask = mask;
  scaled_mask.insert(QStringLiteral("segmentationData"), scaled);
  scaled_mask.insert(QStringLiteral("segmentationWidth"), target_width);
  scaled_mask.insert(QStringLiteral("segmentationHeight"), target_height);
  scaled_mask.insert(QStringLiteral("scaledMattePurpose"), purpose);
  scaled_mask.insert(QStringLiteral("scaledMatteSourceWidth"), source_width);
  scaled_mask.insert(QStringLiteral("scaledMatteSourceHeight"), source_height);
  scaled_mask.insert(QStringLiteral("scaledMatteWidth"), target_width);
  scaled_mask.insert(QStringLiteral("scaledMatteHeight"), target_height);
  return scaled_mask;
}

QVariantMap mask_thumbnail_metadata(const QVariantMap& mask) {
  QVariantMap metadata;
  for (const auto& key : {
           QStringLiteral("scaledMattePurpose"),
           QStringLiteral("scaledMatteSourceWidth"),
           QStringLiteral("scaledMatteSourceHeight"),
           QStringLiteral("scaledMatteWidth"),
           QStringLiteral("scaledMatteHeight"),
           QStringLiteral("scaledMatteRebuiltFromBrushStrokes"),
           QStringLiteral("scaledMatteBrushReplayPointCount"),
       }) {
    if (mask.contains(key)) {
      metadata.insert(key, mask.value(key));
    }
  }
  return metadata;
}

QString mask_thumbnail_cache_key(const QVariantMap& value, const QString& fallback) {
  const auto id = value.value(QStringLiteral("id")).toString();
  if (!id.isEmpty()) {
    return id;
  }
  const auto flat_index = value.contains(QStringLiteral("flatIndex"))
                              ? value.value(QStringLiteral("flatIndex")).toInt()
                              : -1;
  if (flat_index >= 0) {
    return QStringLiteral("flat:%1").arg(flat_index);
  }
  return fallback;
}

