void insert_thumbnail_failure_fields(
    QVariantMap* target,
    const QString& stage,
    const QString& detail,
    const AsyncMaskJob& job,
    qint64 elapsed_ms,
    qint64 budget_ms,
    const QSize& display_size) {
  if (target == nullptr) {
    return;
  }
  const auto existing_source = target->value(QStringLiteral("thumbnailSource")).toString();
  const auto reused_last_good = !existing_source.trimmed().isEmpty();
  const QSize existing_backing_size(
      target->value(QStringLiteral("thumbnailBackingWidth")).toInt(),
      target->value(QStringLiteral("thumbnailBackingHeight")).toInt());
  insert_thumbnail_pixel_metrics(
      target,
      reused_last_good && !existing_backing_size.isEmpty() ? existing_backing_size : QSize{},
      display_size);
  target->insert(QStringLiteral("thumbnailReady"), reused_last_good);
  target->insert(QStringLiteral("thumbnailStale"), reused_last_good);
  target->insert(QStringLiteral("thumbnailFailureContained"), true);
  target->insert(QStringLiteral("thumbnailFailureStage"), stage);
  target->insert(QStringLiteral("thumbnailFailureDetail"), detail);
  target->insert(
      QStringLiteral("thumbnailFailureSignature"),
      QStringLiteral("stage:%1|detail:%2|reused:%3|job:%4")
          .arg(stage, detail, reused_last_good ? QStringLiteral("true") : QStringLiteral("false"),
               job.job_id));
  observability::logWarning(
      photoEditorPreviewLog(),
      QStringLiteral("preview.thumbnail.contained_failure"),
      QVariantMap{
          {QStringLiteral("failure_containment_contract"),
           QStringLiteral("preview-substage-failure-containment-v1")},
          {QStringLiteral("failure_stage"), stage},
          {QStringLiteral("failure_detail"), detail},
          {QStringLiteral("canvas_preview_failed"), false},
          {QStringLiteral("reused_last_good_thumbnail"), reused_last_good},
          {QStringLiteral("thumbnail_job_id"), job.job_id},
          {QStringLiteral("thumbnail_job_kind"), job.job_kind},
          {QStringLiteral("thumbnail_job_stage"), job.stage},
          {QStringLiteral("asset_id"), job.asset_id},
          {QStringLiteral("state_signature"), job.state_signature},
      });
  if (target->value(QStringLiteral("thumbnailKind")).toString().trimmed().isEmpty()) {
    target->insert(QStringLiteral("thumbnailKind"), QStringLiteral("unavailable"));
  }
  const auto existing_signature =
      target->value(QStringLiteral("thumbnailSignature")).toString().trimmed();
  target->insert(
      QStringLiteral("thumbnailSignature"),
      existing_signature.isEmpty()
          ? QStringLiteral("ready:%1|failure:%2").arg(reused_last_good).arg(stage)
          : QStringLiteral("%1|stale:%2|failure:%3")
                .arg(existing_signature, reused_last_good ? QStringLiteral("true")
                                                          : QStringLiteral("false"),
                     stage));
  insert_thumbnail_job_fields(target, job, elapsed_ms, budget_ms);
}

bool photo_layer_thumbnail_cache_matches_identity(
    const QVariantList& current_layers,
    const QVariantList& cached_layers) {
  if (current_layers.size() != cached_layers.size()) {
    return false;
  }
  for (auto index = 0; index < current_layers.size(); ++index) {
    const auto current = current_layers.at(index).toMap();
    const auto cached = cached_layers.at(index).toMap();
    if (current.value(QStringLiteral("id")).toString() !=
            cached.value(QStringLiteral("id")).toString() ||
        current.value(QStringLiteral("kind")).toString() !=
            cached.value(QStringLiteral("kind")).toString() ||
        selection_mask_set_identity_signature(current) !=
            selection_mask_set_identity_signature(cached)) {
      return false;
    }
  }
  return true;
}

bool photo_layer_thumbnail_cache_matches_current_state(
    const QVariantList& current_layers,
    const QVariantList& cached_layers,
    const QString& asset_id,
    int mask_work_state_revision) {
  if (current_layers.size() != cached_layers.size()) {
    return false;
  }
  for (auto index = 0; index < current_layers.size(); ++index) {
    const auto current = current_layers.at(index).toMap();
    const auto cached = cached_layers.at(index).toMap();
    const auto current_kind = current.value(QStringLiteral("kind")).toString();
    const auto normalized_current_kind = current_kind.trimmed().toLower();
    if (current.value(QStringLiteral("id")).toString() !=
            cached.value(QStringLiteral("id")).toString() ||
        current_kind != cached.value(QStringLiteral("kind")).toString()) {
      return false;
    }
    const auto expected_recipe_hash = photo_layer_thumbnail_recipe_hash(current);
    const auto expected_mask_id = selection_mask_set_identity_signature(current);
    const auto expected_blend_mode =
        normalized_mask_blend_mode(current.value(QStringLiteral("blendMode")).toString());
    const auto expected_visible =
        current.value(QStringLiteral("enabled"), true).toBool();
    const auto cached_mask_alpha_hash =
        cached.value(
                  QStringLiteral("thumbnailInvalidationMaskAlphaHash"),
                  normalized_current_kind == QStringLiteral("adjustment")
                      ? cached.value(QStringLiteral("thumbnailAlphaHash"),
                                     cached.value(QStringLiteral("mask_alpha_trace_hash")))
                      : QStringLiteral("sha1:not-applicable"))
            .toString();
    const auto expected_invalidation_key = thumbnail_invalidation_key(
        asset_id,
        current.value(QStringLiteral("id")).toString(),
        expected_mask_id,
        expected_recipe_hash,
        cached_mask_alpha_hash,
        expected_blend_mode,
        current.value(QStringLiteral("opacity"), 1.0).toDouble(),
        expected_visible);
    if (cached.value(QStringLiteral("thumbnailFailureContained")).toBool() &&
        cached.value(QStringLiteral("thumbnailJobStateRevision")).toInt() ==
            mask_work_state_revision) {
      continue;
    }
    if (expected_invalidation_key.trimmed().isEmpty() ||
        cached.value(QStringLiteral("thumbnailInvalidationKey")).toString() !=
            expected_invalidation_key ||
        cached.value(QStringLiteral("thumbnailJobStateRevision")).toInt() !=
            mask_work_state_revision) {
      return false;
    }
  }
  return true;
}

