      return QStringLiteral("overlay");
    case MaskPreviewMode::Outline:
      return QStringLiteral("outline");
    case MaskPreviewMode::MarchingAnts:
      return QStringLiteral("marching-ants");
    case MaskPreviewMode::Grayscale:
      return QStringLiteral("grayscale-alpha");
    case MaskPreviewMode::OnBlack:
    case MaskPreviewMode::OnWhite:
    case MaskPreviewMode::BlackOnWhite:
    case MaskPreviewMode::WhiteOnBlack:
      return QStringLiteral("isolated-mask");
    case MaskPreviewMode::None:
      return QStringLiteral("hidden");
    case MaskPreviewMode::ColorOnBw:
      return QStringLiteral("color-on-bw");
    case MaskPreviewMode::ImageOnBw:
      return QStringLiteral("image-on-bw");
    case MaskPreviewMode::Edge:
      return QStringLiteral("edge");
    case MaskPreviewMode::RefinementEdge:
      return QStringLiteral("refinement-edge");
    case MaskPreviewMode::AffectedPixels:
      return QStringLiteral("affected");
    default:
