QRectF EditorPreviewController::activeInpaintPatchBounds() const {
  const auto mask = activeMaskDefinition();
  if (mask.isEmpty()) {
    return {};
  }

  const auto patch_x = mask.value(QStringLiteral("inpaintPatchX")).toInt();
  const auto patch_y = mask.value(QStringLiteral("inpaintPatchY")).toInt();
  const auto patch_width = mask.value(QStringLiteral("inpaintPatchWidth")).toInt();
  const auto patch_height = mask.value(QStringLiteral("inpaintPatchHeight")).toInt();
  if (patch_width <= 0 || patch_height <= 0) {
    return {};
  }

  auto source_width = mask.value(QStringLiteral("inpaintSourceMaskWidth")).toInt();
  auto source_height = mask.value(QStringLiteral("inpaintSourceMaskHeight")).toInt();
  if (source_width <= 0 || source_height <= 0) {
    const auto source_size = sourceImageSize();
    source_width = source_size.width();
    source_height = source_size.height();
  }
  if (source_width <= 0 || source_height <= 0) {
    return {};
  }

  return QRectF(
             static_cast<double>(patch_x) / static_cast<double>(source_width),
             static_cast<double>(patch_y) / static_cast<double>(source_height),
             static_cast<double>(patch_width) / static_cast<double>(source_width),
             static_cast<double>(patch_height) / static_cast<double>(source_height))
      .intersected(QRectF(0.0, 0.0, 1.0, 1.0));
}
QVariantList EditorPreviewController::activeInpaintCandidates() const {
  const auto mask = activeMaskDefinition();
  if (mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch")) {
    return {};
  }

  QVariantList candidates;
  const auto source_candidates = mask.value(QStringLiteral("inpaintCandidates")).toList();
  for (const auto& candidate_value : source_candidates) {
    const auto candidate = candidate_value.toMap();
    if (candidate.value(QStringLiteral("patchData")).toByteArray().isEmpty() ||
        candidate.value(QStringLiteral("patchWidth")).toInt() <= 0 ||
        candidate.value(QStringLiteral("patchHeight")).toInt() <= 0) {
      continue;
    }
    candidates.append(candidate);
  }
  return candidates;
}
int EditorPreviewController::activeInpaintCandidateCount() const {
  return static_cast<int>(activeInpaintCandidates().size());
}
int EditorPreviewController::activeInpaintCandidateIndex() const {
  const auto count = activeInpaintCandidateCount();
  if (count <= 0) {
    return 0;
  }
  return qBound(
      0,
      activeMaskDefinition().value(QStringLiteral("inpaintCandidateIndex")).toInt(),
      count - 1);
}
bool EditorPreviewController::activeInpaintVariationPickerVisible() const {
  const auto mask = activeMaskDefinition();
  return mask.value(QStringLiteral("toolRole")).toString() == QStringLiteral("retouch") &&
         mask.value(QStringLiteral("committed")).toBool() &&
         !mask.value(QStringLiteral("inpaintPatchData")).toByteArray().isEmpty() &&
         activeInpaintCandidateCount() > 1;
}
bool EditorPreviewController::activeInpaintRegenerationAvailable() const {
  const auto mask = activeMaskDefinition();
  const auto retouch_mode = mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower();
  const auto source_mask_data = mask.value(QStringLiteral("inpaintSourceMaskData")).toByteArray();
  const auto source_mask_width = mask.value(QStringLiteral("inpaintSourceMaskWidth")).toInt();
  const auto source_mask_height = mask.value(QStringLiteral("inpaintSourceMaskHeight")).toInt();
  return mask.value(QStringLiteral("toolRole")).toString() == QStringLiteral("retouch") &&
         mask.value(QStringLiteral("committed")).toBool() &&
         (retouch_mode == QStringLiteral("remove") || retouch_mode == QStringLiteral("heal") ||
          retouch_mode == QStringLiteral("patch")) &&
         valid_segmentation_payload(source_mask_data, source_mask_width, source_mask_height) &&
         selected_pixel_count_for_mask_data(source_mask_data) > 0;
}
bool EditorPreviewController::activeInpaintFinalizationAvailable() const {
  if (!activeInpaintRegenerationAvailable()) {
    return false;
  }
  const auto quality_mode =
      activeMaskDefinition().value(QStringLiteral("inpaintQualityMode")).toString().trimmed().toLower();
  return quality_mode != QStringLiteral("final");
}
