bool EditorPreviewController::retryPreviewRender() {
  if (!hasAsset() || file_path_.isEmpty() || processing_) {
    return false;
  }
  renderPreview(true, QStringLiteral("preview_retry"));
  return true;
}

bool EditorPreviewController::retryThumbnailRender() {
  if (!hasAsset() || file_path_.isEmpty()) {
    return false;
  }
  mask_thumbnail_cache_dirty_ = true;
  photo_layer_thumbnail_cache_dirty_ = true;
  scheduleThumbnailRefreshQueue(QStringLiteral("thumbnail_retry"));
  renderPreview(false, QStringLiteral("preview_retry"));
  emit controlsChanged();
  return true;
}

