QString EditorPreviewController::retouchWorkflowStateSignature() const {
  const QStringList modes{
      QStringLiteral("remove"),
      QStringLiteral("heal"),
      QStringLiteral("clone"),
      QStringLiteral("patch"),
      QStringLiteral("dust"),
      QStringLiteral("red-eye"),
  };
  QMap<QString, QString> mode_states;
  for (const auto& mode : modes) {
    mode_states.insert(mode, QStringLiteral("inactive"));
  }

  for (const auto& value : mask_stack_) {
    const auto mask = value.toMap();
    if (mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch")) {
      continue;
    }
    const auto mode = mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower();
    if (!mode_states.contains(mode)) {
      continue;
    }

    QString state = QStringLiteral("draft");
    if (map_bool_value(mask, QStringLiteral("committed"), false)) {
      state = QStringLiteral("applied");
    } else if (mode == QStringLiteral("clone") &&
               !map_bool_value(mask, QStringLiteral("cloneSourceSet"), false)) {
      state = QStringLiteral("source-required");
    } else if (mode == QStringLiteral("dust") || mode == QStringLiteral("red-eye") ||
               !mask.value(QStringLiteral("inpaintPatchData")).toByteArray().isEmpty()) {
      state = QStringLiteral("review");
    }
    mode_states.insert(mode, state);
  }

  QStringList parts;
  parts.reserve(modes.size());
  for (const auto& mode : modes) {
    parts.push_back(QStringLiteral("%1:%2").arg(mode, mode_states.value(mode)));
  }
  return parts.join(QStringLiteral("|"));
}
