int EditorPreviewController::activeMaskBrushPreviewDiameterPx() const {
  auto size = activeBrushLivePreviewSize();
  if (!size.isValid()) {
    size = displayPreviewNativeSize();
  }
  const auto preview_extent = std::min(size.width(), size.height());
  if (preview_extent <= 0) {
    return 0;
  }
  return std::max(
      1,
      static_cast<int>(std::lround(activeMaskBrushSizeNormalized() * 2.0 *
                                   static_cast<double>(preview_extent))));
}
int EditorPreviewController::activeMaskBrushFinalDiameterXPx() const {
  const auto size = sourceImageSize();
  if (!size.isValid() || size.width() <= 0) {
    return 0;
  }
  return std::max(
      1,
      static_cast<int>(std::lround(activeMaskBrushSizeNormalized() * 2.0 *
                                   static_cast<double>(std::max(1, size.width() - 1)))));
}
int EditorPreviewController::activeMaskBrushFinalDiameterYPx() const {
  const auto size = sourceImageSize();
  if (!size.isValid() || size.height() <= 0) {
    return 0;
  }
  return std::max(
      1,
      static_cast<int>(std::lround(activeMaskBrushSizeNormalized() * 2.0 *
                                   static_cast<double>(std::max(1, size.height() - 1)))));
}
QString EditorPreviewController::activeMaskBrushSizeSummary() const {
  const auto normalized_percent =
      static_cast<int>(std::lround(activeMaskBrushSizeNormalized() * 100.0));
  const auto preview_diameter = activeMaskBrushPreviewDiameterPx();
  const auto final_x = activeMaskBrushFinalDiameterXPx();
  const auto final_y = activeMaskBrushFinalDiameterYPx();
  const auto preview_text = preview_diameter > 0
                                ? QStringLiteral("Preview %1 px").arg(preview_diameter)
                                : QStringLiteral("Preview -- px");
  const auto final_text = final_x > 0 && final_y > 0
                              ? QStringLiteral("Final %1 x %2 px").arg(final_x).arg(final_y)
                              : QStringLiteral("Final -- px");
  return QStringLiteral("%1 | Stored %2% radius | %3")
      .arg(preview_text)
      .arg(normalized_percent)
      .arg(final_text);
}
