QString EditorPreviewController::smartSelectCandidateHudText() const {
  if (smart_select_preview_mask_.isEmpty()) {
    return {};
  }
  const auto count = std::max(1, static_cast<int>(smart_select_preview_candidate_instance_ids_.size()));
  const auto index = smart_select_preview_candidate_instance_ids_.isEmpty()
                         ? 0
                         : smartSelectCandidateIndex();
  return QStringLiteral("Candidate %1 / %2").arg(index + 1).arg(count);
}
bool EditorPreviewController::smartSelectCanCycleCandidates() const {
  return smart_select_preview_candidate_instance_ids_.size() > 1;
}
QString EditorPreviewController::smartSelectPreviewPipelineSignature() const {
  const auto instance_map_loaded = !smart_select_instance_map_data_.isEmpty() &&
                                   smart_select_instance_map_width_ > 0 &&
                                   smart_select_instance_map_height_ > 0;
  return QStringLiteral(
             "smart-selection-hover|precommit:true|preview-edge:%1|debounce-ms:%2|"
             "instance-map:%3|instance-map-size:%4x%5|shared-cache-hit:%6|"
             "outline-only:%7|raster-source:%8|candidate-count:%9|"
             "request-pending:%10|watcher-running:%11|duplicate-skips:%12")
      .arg(kSmartSelectInstanceMapPreviewEdge)
      .arg(kSmartSelectPreviewDebounceMs)
      .arg(instance_map_loaded ? QStringLiteral("loaded") : QStringLiteral("empty"))
      .arg(smart_select_instance_map_width_)
      .arg(smart_select_instance_map_height_)
      .arg(smart_select_instance_map_shared_cache_hit_ ? QStringLiteral("true")
                                                       : QStringLiteral("false"))
      .arg(!smart_select_preview_mask_.isEmpty() &&
                   !mask_preview_mode_uses_raster_matte(
                       mask_preview_mode_from_string(maskPreviewMode()))
               ? QStringLiteral("true")
               : QStringLiteral("false"))
      .arg(smart_select_preview_cache_source_.isEmpty() ? QStringLiteral("false")
                                                        : QStringLiteral("true"))
      .arg(smartSelectCandidateCount())
      .arg(smart_select_preview_request_pending_ ? QStringLiteral("true")
                                                 : QStringLiteral("false"))
      .arg(smart_select_preview_watcher_.isRunning() ? QStringLiteral("true")
                                                     : QStringLiteral("false"))
      .arg(smart_select_preview_duplicate_skip_count_);
}
