void EditorPreviewController::setActiveInpaintCandidateIndex(int index) {
  auto mask = activeMaskDefinition();
  if (mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
      !mask.value(QStringLiteral("committed")).toBool()) {
    return;
  }
  if (inpaint_apply_watcher_.isRunning() || inpaint_regenerate_watcher_.isRunning()) {
    setStatus(QStringLiteral("Wait for the active inpaint job to finish before selecting a variation."));
    return;
  }

  const auto candidates = activeInpaintCandidates();
  if (candidates.size() <= 1) {
    return;
  }

  const auto candidate_index = qBound(0, index, candidates.size() - 1);
  const auto candidate = candidates.at(candidate_index).toMap();
  const auto patch_data = candidate.value(QStringLiteral("patchData")).toByteArray();
  const auto patch_width = candidate.value(QStringLiteral("patchWidth")).toInt();
  const auto patch_height = candidate.value(QStringLiteral("patchHeight")).toInt();
  if (patch_data.isEmpty() || patch_width <= 0 || patch_height <= 0) {
    return;
  }

  if (activeInpaintCandidateIndex() == candidate_index &&
      mask.value(QStringLiteral("inpaintPatchData")).toByteArray() == patch_data) {
    return;
  }

  const auto previous_candidate_index = activeInpaintCandidateIndex();
  const auto state_revision = mask_work_state_revision_;
  const auto state = currentState();
  const auto job_generation = ++inpaint_job_generation_;
  latest_inpaint_job_ = make_async_mask_job(
      QStringLiteral("inpaint_variation"),
      QStringLiteral("select_candidate"),
      asset_id_,
      file_path_,
      state,
      job_generation,
      state_revision);
  const auto variation_job = latest_inpaint_job_;
  const auto source_mask_data = mask.value(QStringLiteral("inpaintSourceMaskData")).toByteArray();
  const auto source_mask_width = mask.value(QStringLiteral("inpaintSourceMaskWidth")).toInt();
  const auto source_mask_height = mask.value(QStringLiteral("inpaintSourceMaskHeight")).toInt();

  mask.insert(QStringLiteral("inpaintPatchData"), patch_data);
  mask.insert(QStringLiteral("inpaintPatchX"), candidate.value(QStringLiteral("patchX")).toInt());
  mask.insert(QStringLiteral("inpaintPatchY"), candidate.value(QStringLiteral("patchY")).toInt());
  mask.insert(QStringLiteral("inpaintPatchWidth"), patch_width);
  mask.insert(QStringLiteral("inpaintPatchHeight"), patch_height);
  mask.insert(
      QStringLiteral("inpaintPatchColorSpace"),
      candidate.value(QStringLiteral("patchColorSpace"), QStringLiteral("sRGB")).toString());
  const auto model_name = candidate.value(QStringLiteral("modelName")).toString();
  if (!model_name.isEmpty()) {
    mask.insert(QStringLiteral("inpaintModelName"), model_name);
  }
  mask.insert(QStringLiteral("inpaintCandidateIndex"), candidate_index);
  mask.insert(
      QStringLiteral("inpaintSeed"),
      std::max(1, candidate.value(QStringLiteral("seed"), inpaint_seed_).toInt()));
  mask.insert(QStringLiteral("inpaintSelectedVariationIndex"), candidate_index);
  mask.insert(
      QStringLiteral("inpaintSelectedVariationSeed"),
      std::max(1, candidate.value(QStringLiteral("seed"), inpaint_seed_).toInt()));
  mask.insert(QStringLiteral("inpaintSelectedVariationModelName"), model_name);
  if (updateActiveMaskDefinition(mask, true, false, QStringLiteral("inpaint_variation_select"))) {
    const auto status = QStringLiteral("Inpaint variation %1 selected.").arg(candidate_index + 1);
    post_render_status_override_ = status;
    auto telemetry = QVariantMap{
        {QStringLiteral("operation"), QStringLiteral("inpaint_variation_select")},
        {QStringLiteral("success"), true},
        {QStringLiteral("cancelled"), false},
        {QStringLiteral("job_generation"), job_generation},
        {QStringLiteral("state_revision"), state_revision},
        {QStringLiteral("previous_candidate_index"), previous_candidate_index},
        {QStringLiteral("candidate_index"), candidate_index},
        {QStringLiteral("candidate_count"), candidates.size()},
        {QStringLiteral("retouch_mode"), mask.value(QStringLiteral("retouchMode")).toString()},
        {QStringLiteral("quality_mode"), mask.value(QStringLiteral("inpaintQualityMode")).toString()},
        {QStringLiteral("seed"), mask.value(QStringLiteral("inpaintSeed")).toInt()},
        {QStringLiteral("model_name"), model_name},
        {QStringLiteral("inpaint_patch_payload_bytes"), patch_data.size()},
        {QStringLiteral("inpaint_candidate_payload_bytes"),
         mask.value(QStringLiteral("inpaintCandidatePayloadBytes")).toLongLong()},
        {QStringLiteral("inpaint_candidate_evicted_count"),
         mask.value(QStringLiteral("inpaintCandidateEvictedCount")).toInt()},
        {QStringLiteral("source_mask_width"), source_mask_width},
        {QStringLiteral("source_mask_height"), source_mask_height},
        {QStringLiteral("source_mask_pixels"),
         selected_pixel_count_for_mask_data(source_mask_data)},
        {QStringLiteral("memory_policy_signature"), maskMemoryPolicySignature()},
    };
    insert_async_mask_job_fields(&telemetry, variation_job);
    recordMaskWorkTelemetry(telemetry);
    setStatus(status);
  }
}

void EditorPreviewController::setActiveMaskOperation(const QString& operation) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty()) {
    return;
  }
  const ScopedBoolValue defer_thumbnail_refresh(mask_thumbnail_refresh_suppressed_, true);
  mask.insert(QStringLiteral("operation"), normalized_mask_operation(operation));
  updateActiveMaskDefinition(mask);
}

