bool EditorPreviewController::applyActiveMaskBrushPreset(const QString& name) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("brush")) {
    return false;
  }

  if (const auto* preset = brush_preset_by_name(name); preset != nullptr) {
    apply_brush_preset_to_mask(&mask, *preset);
    updateActiveMaskDefinition(mask);
    setStatus(QStringLiteral("Applied brush preset '%1'.").arg(preset->name));
    return true;
  }

  const auto normalized_name = normalized_brush_preset_name(name);
  for (const auto& preset_value : custom_brush_presets_) {
    const auto preset = preset_value.toMap();
    if (preset.value(QStringLiteral("name")).toString().compare(normalized_name, Qt::CaseInsensitive) == 0) {
      apply_custom_brush_preset_to_mask(&mask, preset);
      updateActiveMaskDefinition(mask);
      setStatus(QStringLiteral("Applied custom brush preset '%1'.").arg(normalized_name));
      return true;
    }
  }
  return false;
}

bool EditorPreviewController::saveActiveMaskBrushPreset(const QString& name, bool overwrite) {
  auto mask = activeMaskDefinition();
  const auto normalized_name = normalized_brush_preset_name(name);
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("brush") || normalized_name.isEmpty() ||
      brush_preset_by_name(normalized_name) != nullptr) {
    return false;
  }

  const auto preset = brush_preset_snapshot_from_mask(normalized_name, mask);
  for (auto index = 0; index < custom_brush_presets_.size(); ++index) {
    const auto existing = custom_brush_presets_.at(index).toMap();
    if (existing.value(QStringLiteral("name")).toString().compare(normalized_name, Qt::CaseInsensitive) == 0) {
      if (!overwrite) {
        return false;
      }
      custom_brush_presets_[index] = preset;
      mask.insert(QStringLiteral("brushPreset"), normalized_name);
      updateActiveMaskDefinition(mask);
      emit controlsChanged();
      setStatus(QStringLiteral("Updated custom brush preset '%1'.").arg(normalized_name));
      return true;
    }
  }

  custom_brush_presets_.append(preset);
  mask.insert(QStringLiteral("brushPreset"), normalized_name);
  updateActiveMaskDefinition(mask);
  emit controlsChanged();
  setStatus(QStringLiteral("Saved custom brush preset '%1'.").arg(normalized_name));
  return true;
}

bool EditorPreviewController::deleteCustomBrushPreset(const QString& name) {
  const auto normalized_name = normalized_brush_preset_name(name);
  if (normalized_name.isEmpty()) {
    return false;
  }
  for (auto index = 0; index < custom_brush_presets_.size(); ++index) {
    const auto preset = custom_brush_presets_.at(index).toMap();
    if (preset.value(QStringLiteral("name")).toString().compare(normalized_name, Qt::CaseInsensitive) == 0) {
      custom_brush_presets_.removeAt(index);
      if (activeMaskKind() == QStringLiteral("brush") &&
          activeMaskBrushPreset().compare(normalized_name, Qt::CaseInsensitive) == 0) {
        auto mask = activeMaskDefinition();
        mask.insert(QStringLiteral("brushPreset"), QStringLiteral("Custom"));
        updateActiveMaskDefinition(mask);
      }
      emit controlsChanged();
      setStatus(QStringLiteral("Deleted custom brush preset '%1'.").arg(normalized_name));
      return true;
    }
  }
  return false;
}

bool EditorPreviewController::resetCustomBrushPresets() {
  if (custom_brush_presets_.isEmpty()) {
    return false;
  }
  custom_brush_presets_.clear();
  if (activeMaskKind() == QStringLiteral("brush") &&
      brush_preset_by_name(activeMaskBrushPreset()) == nullptr) {
    auto mask = activeMaskDefinition();
    mask.insert(QStringLiteral("brushPreset"), QStringLiteral("Custom"));
    updateActiveMaskDefinition(mask);
  }
  emit controlsChanged();
  setStatus(QStringLiteral("Reset custom brush presets."));
  return true;
}

bool EditorPreviewController::isCustomBrushPreset(const QString& name) const {
  const auto normalized_name = normalized_brush_preset_name(name);
  if (normalized_name.isEmpty()) {
    return false;
  }
  for (const auto& preset_value : custom_brush_presets_) {
    const auto preset = preset_value.toMap();
    if (preset.value(QStringLiteral("name")).toString().compare(normalized_name, Qt::CaseInsensitive) == 0) {
      return true;
    }
  }
  return false;
}

