bool EditorPreviewController::saveActiveCloneSource() {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("brush") ||
      activeMaskRetouchMode() != QStringLiteral("clone") ||
      !map_bool_value(mask, QStringLiteral("cloneSourceSet"), false)) {
    return false;
  }

  auto sources = mask.value(QStringLiteral("cloneSources")).toList();
  QVariantMap source;
  const auto source_number = sources.size() + 1;
  source.insert(QStringLiteral("name"), QStringLiteral("Source %1").arg(source_number));
  source.insert(QStringLiteral("x"), map_double_value(mask, QStringLiteral("cloneSourceX"), 0.5));
  source.insert(QStringLiteral("y"), map_double_value(mask, QStringLiteral("cloneSourceY"), 0.5));
  source.insert(QStringLiteral("scale"), map_double_value(mask, QStringLiteral("cloneScale"), 1.0));
  source.insert(QStringLiteral("rotation"), map_double_value(mask, QStringLiteral("cloneRotation"), 0.0));
  source.insert(QStringLiteral("aligned"), map_bool_value(mask, QStringLiteral("cloneAligned"), true));
  sources.append(source);
  mask.insert(QStringLiteral("cloneSources"), sources);
  mask.insert(QStringLiteral("cloneSourceIndex"), sources.size() - 1);
  updateActiveMaskDefinition(mask);
  setStatus(QStringLiteral("Saved Clone Stamp source %1.").arg(source_number));
  return true;
}

bool EditorPreviewController::selectActiveCloneSource(int index) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("brush") ||
      activeMaskRetouchMode() != QStringLiteral("clone")) {
    return false;
  }
  const auto sources = mask.value(QStringLiteral("cloneSources")).toList();
  if (index < 0 || index >= sources.size()) {
    return false;
  }

  const auto source = sources.at(index).toMap();
  mask.insert(QStringLiteral("cloneSourceSet"), true);
  mask.insert(QStringLiteral("cloneSourceX"), qBound(0.0, source.value(QStringLiteral("x"), 0.5).toDouble(), 1.0));
  mask.insert(QStringLiteral("cloneSourceY"), qBound(0.0, source.value(QStringLiteral("y"), 0.5).toDouble(), 1.0));
  mask.insert(QStringLiteral("cloneScale"), qBound(0.25, source.value(QStringLiteral("scale"), 1.0).toDouble(), 4.0));
  mask.insert(QStringLiteral("cloneRotation"), qBound(-180.0, source.value(QStringLiteral("rotation")).toDouble(), 180.0));
  mask.insert(QStringLiteral("cloneAligned"), source.value(QStringLiteral("aligned"), true).toBool());
  mask.insert(QStringLiteral("cloneOffsetX"), 0.0);
  mask.insert(QStringLiteral("cloneOffsetY"), 0.0);
  mask.insert(QStringLiteral("cloneSourceIndex"), index);
  pending_brush_commit_preview_points_.clear();
  pending_brush_commit_preview_mask_id_.clear();
  cached_mask_sets_with_thumbnails_.clear();
  cached_mask_sets_deferred_thumbnail_key_.clear();
  invalidateMaskDerivedCaches();
  active_brush_live_points_.clear();
  active_brush_auto_mask_anchor_valid_ = false;
  clearActiveBrushLivePreview();
  mask.insert(QStringLiteral("brushPoints"), QVariantList{});
  mask.insert(QStringLiteral("brushStrokes"), QVariantList{});
  updateActiveMaskDefinition(mask, false);
  emit activeBrushStrokeChanged();
  const auto source_name = source.value(QStringLiteral("name")).toString().isEmpty()
                               ? QStringLiteral("source")
                               : source.value(QStringLiteral("name")).toString();
  setStatus(QStringLiteral("Selected Clone Stamp %1.").arg(source_name));
  return true;
}

bool EditorPreviewController::deleteActiveCloneSource(int index) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("brush") ||
      activeMaskRetouchMode() != QStringLiteral("clone")) {
    return false;
  }
  auto sources = mask.value(QStringLiteral("cloneSources")).toList();
  if (index < 0 || index >= sources.size()) {
    return false;
  }

  sources.removeAt(index);
  auto selected_index = mask.value(QStringLiteral("cloneSourceIndex"), -1).toInt();
  if (selected_index == index) {
    selected_index = -1;
  } else if (selected_index > index) {
    --selected_index;
  }
  mask.insert(QStringLiteral("cloneSources"), sources);
  mask.insert(QStringLiteral("cloneSourceIndex"), selected_index);
  updateActiveMaskDefinition(mask);
  setStatus(QStringLiteral("Deleted saved Clone Stamp source."));
  return true;
}

bool EditorPreviewController::setActiveMaskPatchSourceRegion(
    double normalized_x,
    double normalized_y,
    double normalized_width,
    double normalized_height) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("brush") ||
      activeMaskRetouchMode() != QStringLiteral("patch")) {
    return false;
  }

  const auto width = qBound(0.02, normalized_width, 1.0);
  const auto height = qBound(0.02, normalized_height, 1.0);
  const auto x = qBound(0.0, normalized_x, 1.0 - width);
  const auto y = qBound(0.0, normalized_y, 1.0 - height);
  mask.insert(QStringLiteral("patchSourceSet"), true);
  mask.insert(QStringLiteral("patchSourceX"), x);
  mask.insert(QStringLiteral("patchSourceY"), y);
  mask.insert(QStringLiteral("patchSourceWidth"), width);
  mask.insert(QStringLiteral("patchSourceHeight"), height);
  updateActiveMaskDefinition(mask);
  setStatus(QStringLiteral("Patch source region moved. Paint or apply when the source matches."));
  return true;
}

