bool EditorPreviewController::updateActiveLuminanceRangeSample(double normalized_x, double normalized_y) {
  if (activeMaskKind() != QStringLiteral("luminance") ||
      !active_luminance_sample_preview_.value(QStringLiteral("active")).toBool()) {
    return false;
  }
  active_luminance_sample_preview_ = luminance_sample_preview_map(
      active_luminance_sample_preview_.value(QStringLiteral("startX")).toDouble(),
      active_luminance_sample_preview_.value(QStringLiteral("startY")).toDouble(),
      normalized_x,
      normalized_y);
  emit controlsChanged();
  return true;
}

bool EditorPreviewController::commitActiveLuminanceRangeSample(double normalized_x, double normalized_y) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("luminance") ||
      !active_luminance_sample_preview_.value(QStringLiteral("active")).toBool()) {
    return false;
  }
  updateActiveLuminanceRangeSample(normalized_x, normalized_y);
  const auto preview = active_luminance_sample_preview_;

  QImage image;
  if (!decodeSourceImage(&image, 0)) {
    setStatus(QStringLiteral("Unable to decode source for luminance range sampling."));
    cancelActiveLuminanceRangeSample();
    return false;
  }
  image = applyCrop(image);
  if (image.isNull() || image.width() <= 0 || image.height() <= 0) {
    setStatus(QStringLiteral("Unable to sample luminance range from the active image."));
    cancelActiveLuminanceRangeSample();
    return false;
  }

  auto min_x = preview.value(QStringLiteral("x")).toDouble();
  auto min_y = preview.value(QStringLiteral("y")).toDouble();
  auto max_x = min_x + preview.value(QStringLiteral("width")).toDouble();
  auto max_y = min_y + preview.value(QStringLiteral("height")).toDouble();
  if (std::abs(max_x - min_x) < 0.01 && std::abs(max_y - min_y) < 0.01) {
    const auto radius = 0.015;
    const auto center_x = qBound(0.0, min_x, 1.0);
    const auto center_y = qBound(0.0, min_y, 1.0);
    min_x = qBound(0.0, center_x - radius, 1.0);
    max_x = qBound(0.0, center_x + radius, 1.0);
    min_y = qBound(0.0, center_y - radius, 1.0);
    max_y = qBound(0.0, center_y + radius, 1.0);
  }

  const auto left = qBound(
      0,
      static_cast<int>(std::floor(min_x * static_cast<double>(std::max(image.width() - 1, 0)))),
      image.width() - 1);
  const auto right = qBound(
      0,
      static_cast<int>(std::ceil(max_x * static_cast<double>(std::max(image.width() - 1, 0)))),
      image.width() - 1);
  const auto top = qBound(
      0,
      static_cast<int>(std::floor(min_y * static_cast<double>(std::max(image.height() - 1, 0)))),
      image.height() - 1);
  const auto bottom = qBound(
      0,
      static_cast<int>(std::ceil(max_y * static_cast<double>(std::max(image.height() - 1, 0)))),
      image.height() - 1);

  auto sample_min = 1.0;
  auto sample_max = 0.0;
  auto sample_sum = 0.0;
  auto sample_count = 0;
  for (auto y = top; y <= bottom; ++y) {
    for (auto x = left; x <= right; ++x) {
      const auto luminance = display_luminance_for_color(image.pixelColor(x, y));
      sample_min = std::min(sample_min, luminance);
      sample_max = std::max(sample_max, luminance);
      sample_sum += luminance;
      ++sample_count;
    }
  }

  if (sample_count <= 0) {
    setStatus(QStringLiteral("Unable to measure luminance in the selected patch."));
    cancelActiveLuminanceRangeSample();
    return false;
  }

  QVariantMap sample;
  sample.insert(QStringLiteral("x"), qBound(0.0, min_x, 1.0));
  sample.insert(QStringLiteral("y"), qBound(0.0, min_y, 1.0));
  sample.insert(QStringLiteral("width"), qBound(0.0, max_x - min_x, 1.0));
  sample.insert(QStringLiteral("height"), qBound(0.0, max_y - min_y, 1.0));
  sample.insert(QStringLiteral("luminanceMin"), clamp_unit(sample_min));
  sample.insert(QStringLiteral("luminanceMax"), clamp_unit(sample_max));
  sample.insert(QStringLiteral("luminanceMean"), clamp_unit(sample_sum / static_cast<double>(sample_count)));
  sample.insert(QStringLiteral("pixelCount"), sample_count);

  auto samples = mask.value(QStringLiteral("luminanceSamples")).toList();
  samples.append(sample);
  mask.insert(QStringLiteral("luminanceSamples"), normalized_luminance_range_samples(samples));
  update_luminance_range_constraints_from_samples(&mask);
  beginEditTransaction();
  updateActiveMaskDefinition(mask);
  endEditTransaction();
  active_luminance_sample_preview_.clear();
  emit controlsChanged();
  setStatus(QStringLiteral("Luminance range patch sampled."));
  return true;
}

bool EditorPreviewController::cancelActiveLuminanceRangeSample() {
  if (active_luminance_sample_preview_.isEmpty()) {
    return false;
  }
  active_luminance_sample_preview_.clear();
  emit controlsChanged();
  return true;
}

