void EditorPreviewController::setActiveGeneratedMaskHoleFillThreshold(double threshold) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() ||
      !is_ai_segmentation_mask_kind(normalized_mask_kind(mask.value(QStringLiteral("kind")).toString()))) {
    return;
  }
  const auto bounded = qBound(0.0, threshold, kMaxGeneratedMaskCleanupThreshold);
  if (qFuzzyCompare(
          map_double_value(
              mask,
              QStringLiteral("generatedMaskHoleFillThreshold"),
              kDefaultGeneratedMaskHoleFillThreshold) +
              1.0,
          bounded + 1.0)) {
    return;
  }
  mask.insert(QStringLiteral("generatedMaskHoleFillThreshold"), bounded);
  applyGeneratedMaskCleanup(&mask);
  updateActiveMaskDefinition(mask);
}

void EditorPreviewController::setActiveGeneratedMaskIslandRemovalThreshold(double threshold) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() ||
      !is_ai_segmentation_mask_kind(normalized_mask_kind(mask.value(QStringLiteral("kind")).toString()))) {
    return;
  }
  const auto bounded = qBound(0.0, threshold, kMaxGeneratedMaskCleanupThreshold);
  if (qFuzzyCompare(
          map_double_value(
              mask,
              QStringLiteral("generatedMaskIslandRemovalThreshold"),
              kDefaultGeneratedMaskIslandRemovalThreshold) +
              1.0,
          bounded + 1.0)) {
    return;
  }
  mask.insert(QStringLiteral("generatedMaskIslandRemovalThreshold"), bounded);
  applyGeneratedMaskCleanup(&mask);
  updateActiveMaskDefinition(mask);
}

