void EditorPreviewController::cancelPendingAssetScopedWork() {
  interactive_render_timer_.stop();
  full_render_timer_.stop();
  photo_layer_adjustment_render_timer_.stop();
  interactive_request_pending_ = false;
  full_request_pending_ = false;
  overlay_request_pending_ = false;

  pending_brush_commits_.clear();
  pending_brush_commit_scheduled_ = false;
  pending_brush_commit_preview_points_.clear();
  pending_brush_commit_preview_mask_id_.clear();
  active_brush_live_points_.clear();
  clearActiveBrushLivePreview();
  brush_raster_commit_active_ = false;
  active_brush_raster_commit_request_ = {};
  active_brush_raster_commit_request_valid_ = false;
  active_brush_raster_commit_requeued_ = false;
  latest_brush_raster_job_ = {};

  if (thumbnail_refresh_queue_cancellation_ != nullptr) {
    thumbnail_refresh_queue_cancellation_->store(true, std::memory_order_relaxed);
  }
  thumbnail_refresh_queue_timer_.stop();
  thumbnail_refresh_queue_pending_ = false;
  thumbnail_refresh_queue_reason_.clear();
  thumbnail_refresh_queue_signature_.clear();
  thumbnail_refresh_queue_pending_generation_ = 0;
  thumbnail_refresh_queue_active_job_id_.clear();
  thumbnail_refresh_queue_active_signature_.clear();
  thumbnail_refresh_queue_completion_ = {};
  thumbnail_refresh_queue_cancellation_.reset();
  thumbnail_stale_warning_signatures_.clear();
}

void EditorPreviewController::loadAsset(
    const QString& asset_id,
    const QString& file_path,
    const QString& thumbnail_source,
    const QString& camera_label,
    const QString& capture_date,
    const QString& lens_model,
    const QString& recipe_json) {
  persistCurrentState();
  clearMaskActionRetry();
  cancelPendingAssetScopedWork();
  ++mask_work_state_revision_;
  latest_brush_raster_generation_->store(
      ++brush_raster_job_generation_,
      std::memory_order_relaxed);
  ++smart_selection_job_generation_;
  ++inpaint_job_generation_;
  asset_id_ = asset_id;
  file_path_ = file_path;
  fallback_thumbnail_source_ = thumbnail_source;
  camera_label_ = camera_label;
  capture_date_ = capture_date;
  lens_model_ = lens_model;
  brush_stroke_active_ = false;
  brush_stroke_suspends_side_effects_ = false;
  brush_stroke_needs_final_render_ = false;
  active_brush_auto_mask_anchor_valid_ = false;
  display_preview_native_rendered_cache_key_.clear();
  preview_source_ = fallback_thumbnail_source_;
  display_preview_source_ = fallback_thumbnail_source_;
  preview_failure_stage_.clear();
  preview_failure_detail_.clear();
  preview_failure_layer_ids_.clear();
  preview_failure_mask_set_ids_.clear();
  last_successful_preview_file_path_.clear();
  reference_preview_source_.clear();
  display_reference_preview_source_.clear();
  display_preview_overlay_source_.clear();
  display_reference_preview_overlay_source_.clear();
  display_preview_overlay_rect_ = QRectF();
  pixel_inspector_preview_image_ = QImage();
  pixel_inspector_reference_image_ = QImage();
  clearDiagnosticOverlayImages();
  color_tool_mask_preview_cache_key_.clear();
  color_tool_mask_preview_cache_source_.clear();
  clearPixelInspector();
  if (display_preview_texture_ != nullptr) {
    display_preview_texture_->clear();
    ++display_preview_native_revision_;
  }
  if (image_provider_ != nullptr) {
    image_provider_->clearImage(QString::fromLatin1(kEditedPreviewImageId));
    image_provider_->clearImage(QString::fromLatin1(kReferencePreviewImageId));
    image_provider_->clearImage(QString::fromLatin1(kEditedPreviewOverlayImageId));
    image_provider_->clearImage(QString::fromLatin1(kReferencePreviewOverlayImageId));
  }
  resetSmartSelectInstanceMap();
  restoreStateForAsset(asset_id_, recipe_json);
  refreshRawAsShotWhiteBalanceMetadata();
  setWhiteBalanceSampling(false);
  observability::logInfo(
      photoEditorPreviewLog(),
      QStringLiteral("preview.asset_loaded"),
      {
          {QStringLiteral("asset_id"), asset_id_},
          {QStringLiteral("file_path"), file_path_},
          {QStringLiteral("thumbnail"), fallback_thumbnail_source_},
      });
  refreshDebugInfo();
  emit cameraDefaultsChanged();
  emit assetChanged();
  emit previewChanged();
  renderPreview(true, QStringLiteral("asset_select"));
}

void EditorPreviewController::undo() {
  if (!canUndo()) {
    return;
  }

  auto& undo_stack = undoStackForAsset(asset_id_);
  auto& undo_labels = undoLabelStackForAsset(asset_id_);
  const auto previous_state = undo_stack.takeLast();
  const auto action_label = undo_labels.isEmpty() ? QString{} : undo_labels.takeLast();
  auto& redo_stack = redoStackForAsset(asset_id_);
  auto& redo_labels = redoLabelStackForAsset(asset_id_);
  const auto current_state = currentState();
  if (redo_stack.isEmpty() || !edit_states_equal(redo_stack.back(), current_state)) {
    redo_stack.push_back(current_state);
    redo_labels.push_back(action_label);
    if (redo_stack.size() > kMaxEditHistoryDepth) {
      redo_stack.removeFirst();
      if (!redo_labels.isEmpty()) {
        redo_labels.removeFirst();
      }
    }
  } else if (!redo_labels.isEmpty()) {
    redo_labels.last() = action_label;
  }
  applyHistoryState(previous_state);
}

void EditorPreviewController::redo() {
  if (!canRedo()) {
    return;
  }

  auto& redo_stack = redoStackForAsset(asset_id_);
  auto& redo_labels = redoLabelStackForAsset(asset_id_);
  const auto next_state = redo_stack.takeLast();
  const auto action_label = redo_labels.isEmpty() ? QString{} : redo_labels.takeLast();
  pushUndoState(currentState(), action_label);
  applyHistoryState(next_state);
}

