QString EditorPreviewController::pickObjectSelectionMask(
    const SegmentationResult& result,
    const QString& operation,
    bool create_new,
    const QImage& source_image,
    const QString& runtime_label_override,
    const QVariantList& prompts,
    QVariantMap* published_mask) {
  if (!result.success || !valid_segmentation_payload(result.mask_data, result.width, result.height)) {
    setStatus(QStringLiteral("Smart selection could not isolate that target."));
    return QStringLiteral("error");
  }

  auto next_stack = mask_stack_;
  const auto normalized_operation = normalized_mask_operation(operation);
  const auto can_extend_active =
      !create_new && hasActiveMask() && activeMaskKind() == QStringLiteral("object") &&
      activeMaskToolRole() == QStringLiteral("selection") &&
      activeMaskOperation() == normalized_operation;

  if (can_extend_active) {
    auto mask_def = activeMaskDefinition();
    mask_def.insert(
        QStringLiteral("segmentationData"),
        union_segmentation_masks(
            mask_def.value(QStringLiteral("segmentationData")).toByteArray(),
            mask_def.value(QStringLiteral("segmentationWidth")).toInt(),
            mask_def.value(QStringLiteral("segmentationHeight")).toInt(),
            result.mask_data,
            result.width,
            result.height));
    mask_def.insert(QStringLiteral("segmentationWidth"), result.width);
    mask_def.insert(QStringLiteral("segmentationHeight"), result.height);
    mask_def.remove(QStringLiteral("generatedMaskCleanupSourceData"));
    mask_def.remove(QStringLiteral("generatedMaskCleanupSourceWidth"));
    mask_def.remove(QStringLiteral("generatedMaskCleanupSourceHeight"));
    if (mask_def.value(QStringLiteral("name")).toString().trimmed().isEmpty()) {
      mask_def.insert(
          QStringLiteral("name"),
          normalized_operation == QStringLiteral("subtract")
              ? QStringLiteral("Subtract Selection")
              : QStringLiteral("Smart Selection"));
    }
    const auto runtime_label = runtime_label_override.trimmed().isEmpty()
                                   ? smartSelectionRuntimeLabel()
                                   : runtime_label_override.trimmed();
    stampGeneratedMaskMetadata(&mask_def, runtime_label);
    clear_generated_confidence_map(&mask_def);
    apply_object_aware_refinement_defaults(&mask_def, runtime_label, false);
    apply_color_aware_hard_edge_refinement_defaults(
        &mask_def,
        runtime_label,
        source_image,
        result,
        false);
    applyGeneratedMaskCleanup(&mask_def);
    merge_smart_select_prompt_metadata(&mask_def, prompts);
    if (published_mask != nullptr) {
      *published_mask = normalized_mask_definition(mask_def, active_mask_index_ + 1);
    }
    updateActiveMaskDefinition(mask_def);
    setStatus(
        normalized_operation == QStringLiteral("subtract")
            ? QStringLiteral("%1 area subtracted from the current selection.").arg(runtime_label)
            : QStringLiteral("%1 area added to the current selection.").arg(runtime_label));
    return QStringLiteral("selection-ai");
  }

  auto mask_def = default_mask_definition(QStringLiteral("object"), static_cast<int>(next_stack.size()) + 1);
  mask_def.insert(
      QStringLiteral("name"),
      normalized_operation == QStringLiteral("subtract")
          ? QStringLiteral("Subtract Selection %1").arg(next_stack.size() + 1)
          : QStringLiteral("Smart Selection %1").arg(next_stack.size() + 1));
  mask_def.insert(QStringLiteral("toolRole"), QStringLiteral("selection"));
  mask_def.insert(QStringLiteral("operation"), normalized_operation);
  mask_def.insert(QStringLiteral("committed"), true);
  if (!create_new && hasActiveMask()) {
    const auto active_mask = activeMaskDefinition();
    if (is_selection_mask(active_mask)) {
      inherit_selection_mask_set(&mask_def, active_mask);
    }
  }
  mask_def.insert(QStringLiteral("feather"), 0.35);
  mask_def.insert(QStringLiteral("segmentationData"), result.mask_data);
  mask_def.insert(QStringLiteral("segmentationWidth"), result.width);
  mask_def.insert(QStringLiteral("segmentationHeight"), result.height);
  const auto runtime_label = runtime_label_override.trimmed().isEmpty()
                                  ? smartSelectionRuntimeLabel()
                                  : runtime_label_override.trimmed();
  stampGeneratedMaskMetadata(&mask_def, runtime_label);
  apply_generated_confidence_map(&mask_def, result);
  apply_object_aware_refinement_defaults(&mask_def, runtime_label, true);
  apply_color_aware_hard_edge_refinement_defaults(
      &mask_def,
      runtime_label,
      source_image,
      result,
      true);
  applyGeneratedMaskCleanup(&mask_def);
  merge_smart_select_prompt_metadata(&mask_def, prompts);
  next_stack.append(mask_def);

  applyMaskStackChange(
      next_stack,
      static_cast<int>(next_stack.size()) - 1,
      true,
      {},
      true);
  if (published_mask != nullptr) {
    *published_mask = activeMaskDefinition();
  }
  setStatus(
      normalized_operation == QStringLiteral("subtract")
          ? QStringLiteral("%1 area subtracted from the current selection.").arg(runtime_label)
          : QStringLiteral("%1 selection created.").arg(runtime_label));
  return QStringLiteral("selection-ai");
}

QString EditorPreviewController::pickObjectRemoveMask(
    const SegmentationResult& result,
    bool create_new,
    const QImage& source_image,
    const QString& runtime_label_override,
    const QVariantList& prompts,
    QVariantMap* published_mask) {
  if (!result.success || !valid_segmentation_payload(result.mask_data, result.width, result.height)) {
    setStatus(QStringLiteral("Smart selection could not isolate that target."));
    return QStringLiteral("error");
  }

  auto next_stack = mask_stack_;
  auto target_index = -1;
  if (!create_new) {
    if (hasActiveMask()) {
      const auto active_mask = activeMaskDefinition();
      if (active_mask.value(QStringLiteral("kind")).toString() == QStringLiteral("object") &&
          active_mask.value(QStringLiteral("toolRole")).toString() == QStringLiteral("retouch") &&
          active_mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower() ==
              QStringLiteral("remove") &&
          !active_mask.value(QStringLiteral("committed")).toBool()) {
        target_index = active_mask_index_;
      }
    }
    if (target_index < 0) {
      target_index = findPendingRetouchMaskIndex(
          QStringLiteral("remove"),
          QStringLiteral("object"));
    }
  }

  if (target_index >= 0) {
    auto mask_def = next_stack.at(target_index).toMap();
    QVariantMap incoming_mask;
    incoming_mask.insert(QStringLiteral("kind"), QStringLiteral("object"));
    incoming_mask.insert(QStringLiteral("segmentationData"), result.mask_data);
    incoming_mask.insert(QStringLiteral("segmentationWidth"), result.width);
    incoming_mask.insert(QStringLiteral("segmentationHeight"), result.height);
    const auto runtime_label = runtime_label_override.trimmed().isEmpty()
                                   ? smartSelectionRuntimeLabel()
                                   : runtime_label_override.trimmed();
    stampGeneratedMaskMetadata(&incoming_mask, runtime_label);
    merge_smart_select_prompt_metadata(&incoming_mask, prompts);
    apply_object_remove_assisted_expansion(&incoming_mask, source_image, runtime_label, prompts);
    mask_def.insert(
        QStringLiteral("segmentationData"),
        union_segmentation_masks(
            mask_def.value(QStringLiteral("segmentationData")).toByteArray(),
            mask_def.value(QStringLiteral("segmentationWidth")).toInt(),
            mask_def.value(QStringLiteral("segmentationHeight")).toInt(),
            incoming_mask.value(QStringLiteral("segmentationData")).toByteArray(),
            incoming_mask.value(QStringLiteral("segmentationWidth")).toInt(),
            incoming_mask.value(QStringLiteral("segmentationHeight")).toInt()));
    mask_def.insert(QStringLiteral("segmentationWidth"), result.width);
    mask_def.insert(QStringLiteral("segmentationHeight"), result.height);
    stampGeneratedMaskMetadata(&mask_def, runtime_label);
    merge_smart_select_prompt_metadata(&mask_def, prompts);
    auto metadata = mask_def.value(QStringLiteral("generatedMaskMetadata")).toMap();
    const auto incoming_metadata = incoming_mask.value(QStringLiteral("generatedMaskMetadata")).toMap();
    const auto current_expansion_pixels =
        mask_def.value(QStringLiteral("objectRemoveExpansionPixels")).toInt();
    const auto incoming_expansion_pixels =
        incoming_mask.value(QStringLiteral("objectRemoveExpansionPixels")).toInt();
    metadata.insert(QStringLiteral("objectRemoveAssisted"), true);
    metadata.insert(QStringLiteral("objectRemoveAssistSchemaVersion"), 1);
    metadata.insert(QStringLiteral("objectRemoveAssistMode"), QStringLiteral("object-plus-shadow-reflection"));
    metadata.insert(QStringLiteral("objectRemoveRuntime"), runtime_label);
    metadata.insert(
        QStringLiteral("objectRemoveExpansionPixels"),
        current_expansion_pixels + incoming_expansion_pixels);
    metadata.insert(
        QStringLiteral("objectRemoveShadowReflectionPixels"),
        mask_def.value(QStringLiteral("objectRemoveShadowReflectionPixels")).toInt() +
            incoming_mask.value(QStringLiteral("objectRemoveShadowReflectionPixels")).toInt());
    metadata.insert(
        QStringLiteral("objectRemoveLastExpansionPixels"),
        incoming_metadata.value(QStringLiteral("objectRemoveExpansionPixels")).toInt());
    mask_def.insert(QStringLiteral("generatedMaskMetadata"), metadata);
    mask_def.insert(QStringLiteral("objectRemoveAssisted"), true);
    mask_def.insert(QStringLiteral("objectRemoveAssistSchemaVersion"), 1);
    mask_def.insert(QStringLiteral("objectRemoveAssistMode"), QStringLiteral("object-plus-shadow-reflection"));
    mask_def.insert(QStringLiteral("objectRemoveRuntime"), runtime_label);
    mask_def.insert(
        QStringLiteral("objectRemoveExpansionPixels"),
        current_expansion_pixels + incoming_expansion_pixels);
    mask_def.insert(
        QStringLiteral("objectRemoveShadowReflectionPixels"),
        mask_def.value(QStringLiteral("objectRemoveShadowReflectionPixels")).toInt() +
            incoming_mask.value(QStringLiteral("objectRemoveShadowReflectionPixels")).toInt());
    if (mask_def.value(QStringLiteral("name")).toString().trimmed().isEmpty()) {
      mask_def.insert(QStringLiteral("name"), QStringLiteral("Object Remove"));
    }
    next_stack[target_index] = normalized_mask_definition(mask_def, target_index + 1);
    applyMaskStackChange(next_stack, target_index, false);
    if (published_mask != nullptr) {
      *published_mask = activeMaskDefinition();
    }
    setStatus(QStringLiteral("Object remove expanded to include likely edge, shadow, or reflection pixels. Apply when ready."));
    return QStringLiteral("remove-ai");
  }

  auto mask_def = default_mask_definition(QStringLiteral("object"), static_cast<int>(next_stack.size()) + 1);
  mask_def.insert(
      QStringLiteral("name"),
      QStringLiteral("Remove Target %1").arg(next_stack.size() + 1));
  mask_def.insert(QStringLiteral("toolRole"), QStringLiteral("retouch"));
  mask_def.insert(QStringLiteral("retouchMode"), QStringLiteral("remove"));
  mask_def.insert(QStringLiteral("committed"), false);
  mask_def.insert(QStringLiteral("removeStrength"), 100.0);
  mask_def.insert(QStringLiteral("feather"), 0.35);
  mask_def.insert(QStringLiteral("segmentationData"), result.mask_data);
  mask_def.insert(QStringLiteral("segmentationWidth"), result.width);
  mask_def.insert(QStringLiteral("segmentationHeight"), result.height);
  const auto runtime_label = runtime_label_override.trimmed().isEmpty()
                                 ? smartSelectionRuntimeLabel()
                                 : runtime_label_override.trimmed();
  stampGeneratedMaskMetadata(&mask_def, runtime_label);
  merge_smart_select_prompt_metadata(&mask_def, prompts);
  apply_object_remove_assisted_expansion(&mask_def, source_image, runtime_label, prompts);
  next_stack.append(mask_def);

  applyMaskStackChange(next_stack, static_cast<int>(next_stack.size()) - 1, false);
  if (published_mask != nullptr) {
    *published_mask = activeMaskDefinition();
  }
  setStatus(QStringLiteral("Object remove staged with assisted edge, shadow, and reflection expansion. Paint to refine, then apply."));
  return QStringLiteral("remove-ai");
}

void EditorPreviewController::startSelectionBrush(bool subtract) {
  auto next_stack = mask_stack_;
  const auto insert_index =
      hasActiveMask() ? qBound(0, active_mask_index_ + 1, static_cast<int>(next_stack.size())) : static_cast<int>(next_stack.size());

  auto mask_def = buildBrushMask(
      subtract ? QStringLiteral("Erase Brush %1").arg(insert_index + 1)
               : QStringLiteral("Select Brush %1").arg(insert_index + 1),
      subtract ? QStringLiteral("subtract") : QStringLiteral("add"),
      QStringLiteral("selection"),
      QString(),
      true,
      insert_index + 1);
  if (hasActiveMask()) {
    const auto active_mask = activeMaskDefinition();
    if (is_selection_mask(active_mask)) {
      inherit_selection_mask_set(&mask_def, active_mask);
    }
  }
  mask_def.insert(QStringLiteral("brushPreset"), QStringLiteral("Selection Brush"));
  mask_def.insert(QStringLiteral("brushSize"), 0.06);
  mask_def.insert(QStringLiteral("brushFlow"), 1.0);
  mask_def.insert(QStringLiteral("brushHardness"), 0.45);
  mask_def.insert(QStringLiteral("brushSpacing"), 0.75);
  mask_def.insert(QStringLiteral("brushSmoothing"), 0.18);
  mask_def.insert(QStringLiteral("brushBuildup"), true);
  mask_def.insert(QStringLiteral("brushEraseMode"), false);
  mask_def.insert(QStringLiteral("brushAutoMask"), false);
  mask_def.insert(QStringLiteral("brushAutoMaskTolerance"), 0.18);
  mask_def.insert(QStringLiteral("brushAutoMaskContinuousSampling"), false);
  mask_def.insert(QStringLiteral("brushProtectEdges"), false);
  mask_def.insert(QStringLiteral("feather"), 0.55);
  next_stack.insert(insert_index, mask_def);
  applyMaskStackChange(
      next_stack,
      insert_index,
      true,
      QStringLiteral("selection_brush_start"),
      true);
  setStatus(
      subtract ? QStringLiteral("Erase Brush ready. Paint directly on the image to remove areas from the selection.")
                : QStringLiteral("Select Brush ready. Paint directly on the image to add areas to the selection."));
}

void EditorPreviewController::startAIMaskRefineBrush(bool subtract) {
  if (!hasActiveMask() || !is_ai_segmentation_mask_kind(activeMaskKind())) {
    setStatus(QStringLiteral("Select a generated mask before refining with the edge brush."));
    return;
  }
  startSelectionEdgeBrush(subtract);
}

void EditorPreviewController::startSelectionEdgeBrush(bool subtract) {
  if (!hasActiveMask() || activeMaskToolRole() == QStringLiteral("retouch")) {
    setStatus(QStringLiteral("Select an adjustment selection before using Brush Refine."));
    return;
  }

  const auto refine_target = activeMaskDefinition();
  if (!is_selection_mask(refine_target)) {
    setStatus(QStringLiteral("Select an adjustment selection before using Brush Refine."));
    return;
  }

  auto next_stack = mask_stack_;
  const auto insert_index =
      hasActiveMask() ? qBound(0, active_mask_index_ + 1, static_cast<int>(next_stack.size())) : static_cast<int>(next_stack.size());

  auto mask_def = buildBrushMask(
      subtract ? QStringLiteral("Brush Refine Erase %1").arg(insert_index + 1)
               : QStringLiteral("Brush Refine Add %1").arg(insert_index + 1),
      subtract ? QStringLiteral("subtract") : QStringLiteral("add"),
      QStringLiteral("selection"),
      QString(),
      true,
      insert_index + 1);
  inherit_selection_mask_set(&mask_def, refine_target);
  mask_def.insert(QStringLiteral("parentId"), refine_target.value(QStringLiteral("id")).toString());
  mask_def.insert(QStringLiteral("brushRefineMode"), true);
  mask_def.insert(QStringLiteral("refineBrushRecalculate"), true);
  mask_def.insert(QStringLiteral("brushRefineTargetId"), refine_target.value(QStringLiteral("id")).toString());
  mask_def.insert(QStringLiteral("brushRefineTargetName"), refine_target.value(QStringLiteral("name")).toString());
  mask_def.insert(QStringLiteral("brushRefineTargetKind"), refine_target.value(QStringLiteral("kind")).toString());
  mask_def.insert(QStringLiteral("brushPreset"), QStringLiteral("Edge Aware"));
  mask_def.insert(QStringLiteral("brushSize"), 0.026);
  mask_def.insert(QStringLiteral("brushFlow"), 1.0);
  mask_def.insert(QStringLiteral("brushHardness"), 0.66);
  mask_def.insert(QStringLiteral("brushSpacing"), 0.42);
  mask_def.insert(QStringLiteral("brushSmoothing"), 0.34);
  mask_def.insert(QStringLiteral("brushBuildup"), true);
  mask_def.insert(QStringLiteral("brushEraseMode"), false);
  mask_def.insert(QStringLiteral("brushAutoMask"), true);
  mask_def.insert(QStringLiteral("brushAutoMaskTolerance"), 0.14);
  mask_def.insert(QStringLiteral("brushAutoMaskContinuousSampling"), false);
  mask_def.insert(QStringLiteral("brushProtectEdges"), true);
  mask_def.insert(QStringLiteral("selectionFineEdge"), 62.0);
  mask_def.insert(QStringLiteral("selectionEdgeContrast"), 18.0);
  mask_def.insert(QStringLiteral("selectionFeather"), 10.0);
  mask_def.insert(QStringLiteral("refineEdgeConfidenceMin"), 0.08);
  mask_def.insert(QStringLiteral("feather"), 0.34);
  next_stack.insert(insert_index, mask_def);
  applyMaskStackChange(next_stack, insert_index, true, {}, true);
  setStatus(
      subtract ? QStringLiteral("Brush Refine Erase ready. Paint along %1 to recalculate and trim the edge.")
                      .arg(refine_target.value(QStringLiteral("name")).toString())
               : QStringLiteral("Brush Refine Add ready. Paint along %1 to recalculate and recover missed edges.")
                      .arg(refine_target.value(QStringLiteral("name")).toString()));
}

