void EditorPreviewController::applyActiveRetouch() {
  if (!hasActiveMask()) {
    return;
  }

  const auto active_mask = mask_stack_.at(active_mask_index_).toMap();
  const auto active_retouch_mode =
      active_mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower();
  if (active_mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
      active_mask.value(QStringLiteral("committed")).toBool() ||
      active_retouch_mode.isEmpty()) {
    return;
  }

  const auto uses_inpaint_apply = active_retouch_mode == QStringLiteral("remove") ||
                                  active_retouch_mode == QStringLiteral("heal") ||
                                  active_retouch_mode == QStringLiteral("patch");
  if (uses_inpaint_apply && inpaint_apply_watcher_.isRunning()) {
    setStatus(QStringLiteral("Another inpaint job is already running. Wait for it to finish before applying again."));
    return;
  }

  const auto inpaint_job_generation = ++inpaint_job_generation_;
  const auto inpaint_state_revision = mask_work_state_revision_;
  const auto inpaint_state = currentState();
  latest_inpaint_job_ = make_async_mask_job(
      QStringLiteral("inpaint"),
      QStringLiteral("apply"),
      asset_id_,
      file_path_,
      inpaint_state,
      inpaint_job_generation,
      inpaint_state_revision);
  const auto inpaint_job = latest_inpaint_job_;
  const auto inpaint_active_mask_id = active_mask.value(QStringLiteral("id")).toString();

  if (uses_inpaint_apply) {
    const auto report_inpaint_progress = inpaint_quality_mode_ == QStringLiteral("final");
    if (report_inpaint_progress) {
      setInpaintProgress(true, 0.05, QStringLiteral("Preparing final-resolution inpaint"));
      setStatus(QStringLiteral("Preparing final-resolution inpaint"));
    } else {
      setInpaintProgress(true, 0.10, QStringLiteral("Preparing inpaint"));
      setStatus(QStringLiteral("Preparing inpaint"));
    }
    inpaint_apply_watcher_.setFuture(QtConcurrent::run(
        run_inpaint_apply_work,
        InpaintApplyRequest{
            .job = inpaint_job,
            .file_path = file_path_,
            .asset_id = asset_id_,
            .state = inpaint_state,
            .mask_stack = mask_stack_,
            .active_mask = active_mask,
            .active_mask_index = active_mask_index_,
            .active_mask_id = inpaint_active_mask_id,
            .retouch_mode = active_retouch_mode,
            .prompt = inpaint_prompt_,
            .quality_mode = inpaint_quality_mode_,
            .seed = inpaint_seed_,
            .blend_amount = inpaint_blend_amount_,
            .generation = inpaint_job_generation,
            .state_revision = inpaint_state_revision,
        }));
    updateProcessingState();
    return;
  }

  auto next_stack = mask_stack_;
  auto changed = false;
  for (int index = 0; index < next_stack.size(); ++index) {
    auto mask = next_stack.at(index).toMap();
    if (mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
        mask.value(QStringLiteral("committed")).toBool() ||
        mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower() != active_retouch_mode) {
      continue;
    }
    mask.insert(QStringLiteral("committed"), true);
    next_stack[index] = mask;
    changed = true;
  }
  if (!changed) {
    return;
  }

  applyMaskStackChange(next_stack, active_mask_index_, true);
  auto status =
      QStringLiteral("%1 retouch applied.")
          .arg(active_retouch_mode.left(1).toUpper() + active_retouch_mode.mid(1));
  setStatus(status);
}

void EditorPreviewController::handleInpaintApplyFinished() {
  publishInpaintApplyResult(inpaint_apply_watcher_.result());
}

void EditorPreviewController::publishInpaintApplyResult(const InpaintApplyResult& result) {
  const auto& request = result.request;
  const auto current_active_mask = activeMaskDefinition();
  const auto stale_result = request.job.job_id != latest_inpaint_job_.job_id ||
                            request.generation != inpaint_job_generation_ ||
                            request.state_revision != mask_work_state_revision_ ||
                            request.asset_id != asset_id_ ||
                            request.file_path != file_path_ ||
                            request.job.state_signature != edit_state_signature(currentState()) ||
                            current_active_mask.value(QStringLiteral("id")).toString() !=
                                request.active_mask_id;
  if (stale_result) {
    ++inpaint_cancelled_count_;
    recordCancelledMaskWork(
        QStringLiteral("inpaint"),
        request.generation,
        inpaint_job_generation_,
        request.state_revision,
        QStringLiteral("stale_result"),
        QStringLiteral("apply_publish"),
        current_active_mask,
        {},
        {},
        request.job);
    setInpaintProgress(false, 1.0, QStringLiteral("Inpaint canceled"));
    setStatus(QStringLiteral("Inpaint canceled because the image or retouch selection changed."));
    return;
  }

  const auto final_quality = request.quality_mode == QStringLiteral("final");
  if (!result.changed) {
    auto telemetry = result.telemetry;
    if (telemetry.isEmpty()) {
      telemetry = QVariantMap{
          {QStringLiteral("operation"), QStringLiteral("inpaint")},
          {QStringLiteral("retouch_mode"), request.retouch_mode},
          {QStringLiteral("runtime_label"), inpaintRuntimeLabel()},
          {QStringLiteral("quality_mode"), request.quality_mode},
          {QStringLiteral("seed"), request.seed},
          {QStringLiteral("success"), false},
          {QStringLiteral("cancelled"), false},
          {QStringLiteral("job_generation"), request.generation},
          {QStringLiteral("state_revision"), request.state_revision},
          {QStringLiteral("inpaint_worker_thread"), result.worker_thread},
          {QStringLiteral("inpaint_worker_elapsed_ms"), result.elapsed_ms},
          {QStringLiteral("inpaint_execution_mode"), QStringLiteral("async_worker")},
          {QStringLiteral("fallback_reason"), result.error_message},
      };
      insert_async_mask_job_fields(&telemetry, request.job);
    }
    telemetry.insert(QStringLiteral("success"), false);
    telemetry.insert(QStringLiteral("cancelled"), false);
    telemetry.insert(QStringLiteral("memory_policy_signature"), maskMemoryPolicySignature());
    telemetry.insert(QStringLiteral("progress_active"), false);
    telemetry.insert(QStringLiteral("progress_value"), 1.0);
    telemetry.insert(
        QStringLiteral("progress_label"),
        final_quality ? QStringLiteral("Final inpaint failed") : QStringLiteral("Inpaint failed"));
    recordMaskWorkTelemetry(telemetry);
    setInpaintProgress(
        false,
        1.0,
        final_quality ? QStringLiteral("Final inpaint failed") : QStringLiteral("Inpaint failed"));
    const auto detail = result.error_message.isEmpty()
                            ? QStringLiteral("Inpaint did not return a usable patch.")
                            : result.error_message;
    rememberInpaintRetry(request.retouch_mode, detail);
    setStatus(QStringLiteral("Inpaint failed. %1").arg(detail));
    return;
  }

  if (final_quality) {
    setInpaintProgress(true, 0.92, QStringLiteral("Writing inpaint patch"));
  }

  auto next_active_index = request.active_mask_index;
  for (int index = 0; index < result.next_stack.size(); ++index) {
    if (result.next_stack.at(index).toMap().value(QStringLiteral("id")).toString() ==
        request.active_mask_id) {
      next_active_index = index;
      break;
    }
  }
  applyMaskStackChange(result.next_stack, next_active_index, true);

  auto status =
      QStringLiteral("%1 retouch applied.")
          .arg(request.retouch_mode.left(1).toUpper() + request.retouch_mode.mid(1));
  status += result.status_suffix;
  post_render_status_override_ = status;
  if (result.has_inpaint_patch) {
    clearMaskActionRetry();
    if (final_quality) {
      setInpaintProgress(false, 1.0, QStringLiteral("Final inpaint complete"));
    } else {
      setInpaintProgress(false, 0.0, {});
    }
  } else {
    const auto detail = result.error_message.isEmpty()
                            ? QStringLiteral("Inpaint did not return a usable patch.")
                            : result.error_message;
    rememberInpaintRetry(request.retouch_mode, detail);
    setInpaintProgress(
        false,
        1.0,
        final_quality ? QStringLiteral("Final inpaint failed") : QStringLiteral("Inpaint failed"));
  }

  auto telemetry = result.telemetry;
  telemetry.insert(QStringLiteral("success"), result.has_inpaint_patch);
  telemetry.insert(QStringLiteral("cancelled"), false);
  telemetry.insert(QStringLiteral("memory_policy_signature"), maskMemoryPolicySignature());
  telemetry.insert(QStringLiteral("progress_active"), inpaintProgressActive());
  telemetry.insert(QStringLiteral("progress_value"), inpaintProgressValue());
  telemetry.insert(QStringLiteral("progress_label"), inpaintProgressLabel());
  recordMaskWorkTelemetry(telemetry);
  setStatus(status);
}

void EditorPreviewController::handleInpaintRegenerateFinished() {
  publishInpaintRegenerateResult(inpaint_regenerate_watcher_.result());
}

void EditorPreviewController::publishInpaintRegenerateResult(
    const InpaintRegenerateResult& result) {
  const auto& request = result.request;
  const auto current_active_mask = activeMaskDefinition();
  const auto stale_result = request.job.job_id != latest_inpaint_job_.job_id ||
                            request.generation != inpaint_job_generation_ ||
                            request.state_revision != mask_work_state_revision_ ||
                            request.asset_id != asset_id_ ||
                            request.file_path != file_path_ ||
                            request.job.state_signature != edit_state_signature(currentState()) ||
                            current_active_mask.value(QStringLiteral("id")).toString() !=
                                request.mask_id;
  if (stale_result) {
    ++inpaint_cancelled_count_;
    recordCancelledMaskWork(
        QStringLiteral("inpaint_regenerate"),
        request.generation,
        inpaint_job_generation_,
        request.state_revision,
        QStringLiteral("stale_result"),
        QStringLiteral("regenerate_publish"),
        current_active_mask,
        {},
        {},
        request.job);
    setInpaintProgress(false, 1.0, QStringLiteral("Inpaint canceled"));
    setStatus(QStringLiteral("Inpaint regeneration canceled because the image or retouch patch changed."));
    return;
  }

  const auto final_quality = request.quality_mode == QStringLiteral("final");
  auto telemetry = result.telemetry;
  if (telemetry.isEmpty()) {
    telemetry = QVariantMap{
        {QStringLiteral("operation"), QStringLiteral("inpaint_regenerate")},
        {QStringLiteral("retouch_mode"), request.retouch_mode},
        {QStringLiteral("runtime_label"), inpaintRuntimeLabel()},
        {QStringLiteral("quality_mode"), request.quality_mode},
        {QStringLiteral("seed"), result.next_seed},
        {QStringLiteral("target_candidate_index"), request.target_candidate_index},
        {QStringLiteral("selected_candidate_index"), request.target_candidate_index},
        {QStringLiteral("variation_specific_regenerate"), request.target_candidate_index > 0},
        {QStringLiteral("success"), false},
        {QStringLiteral("cancelled"), false},
        {QStringLiteral("job_generation"), request.generation},
        {QStringLiteral("state_revision"), request.state_revision},
        {QStringLiteral("inpaint_worker_thread"), result.worker_thread},
        {QStringLiteral("inpaint_worker_elapsed_ms"), result.elapsed_ms},
        {QStringLiteral("inpaint_execution_mode"), QStringLiteral("async_worker")},
        {QStringLiteral("fallback_reason"), result.error_message},
    };
    insert_async_mask_job_fields(&telemetry, request.job);
  }
  telemetry.insert(QStringLiteral("memory_policy_signature"), maskMemoryPolicySignature());

  if (!result.success) {
    telemetry.insert(QStringLiteral("success"), false);
    telemetry.insert(QStringLiteral("cancelled"), false);
    telemetry.insert(QStringLiteral("progress_active"), false);
    telemetry.insert(QStringLiteral("progress_value"), 1.0);
    telemetry.insert(
        QStringLiteral("progress_label"),
        final_quality ? QStringLiteral("Final inpaint failed") : QStringLiteral("Inpaint failed"));
    recordMaskWorkTelemetry(telemetry);
    setInpaintProgress(
        false,
        1.0,
        final_quality ? QStringLiteral("Final inpaint failed") : QStringLiteral("Inpaint failed"));
    const auto detail = result.error_message.isEmpty()
                            ? QStringLiteral("Inpaint did not return a usable patch.")
                            : result.error_message;
    setStatus(QStringLiteral("Regenerate failed. %1").arg(detail));
    rememberInpaintRetry(request.retouch_mode, detail);
    return;
  }

  inpaint_seed_ = std::max(1, result.mask.value(QStringLiteral("inpaintSeed"), result.next_seed).toInt());
  if (final_quality) {
    setInpaintProgress(true, 0.92, QStringLiteral("Updating retouch patch"));
  }
  if (!updateActiveMaskDefinition(result.mask, true, false, QStringLiteral("inpaint_regenerate"))) {
    telemetry.insert(QStringLiteral("success"), false);
    telemetry.insert(QStringLiteral("cancelled"), false);
    telemetry.insert(QStringLiteral("progress_active"), false);
    telemetry.insert(QStringLiteral("progress_value"), 1.0);
    telemetry.insert(
        QStringLiteral("progress_label"),
        final_quality ? QStringLiteral("Final inpaint failed") : QStringLiteral("Inpaint failed"));
    recordMaskWorkTelemetry(telemetry);
    setInpaintProgress(
        false,
        1.0,
        final_quality ? QStringLiteral("Final inpaint failed") : QStringLiteral("Inpaint failed"));
    setStatus(QStringLiteral("Regenerate failed. The active patch could not be updated."));
    rememberInpaintRetry(request.retouch_mode, QStringLiteral("The active patch could not be updated."));
    return;
  }

  clearMaskActionRetry();
  const auto status_template = request.success_status_template.isEmpty()
                                   ? QStringLiteral("Regenerated %1 retouch patch with seed %2.")
                                   : request.success_status_template;
  auto status = status_template.arg(request.retouch_mode, QString::number(inpaint_seed_));
  if (request.success_status_template.isEmpty() && request.target_candidate_index > 0) {
    status = QStringLiteral("Regenerated %1 retouch variation %2 with seed %3.")
                 .arg(
                     request.retouch_mode,
                     QString::number(request.target_candidate_index + 1),
                     QString::number(inpaint_seed_));
  }
  post_render_status_override_ = status;
  if (!final_quality) {
    setInpaintProgress(false, 0.0, {});
  }
  telemetry.insert(QStringLiteral("success"), true);
  telemetry.insert(QStringLiteral("cancelled"), false);
  telemetry.insert(QStringLiteral("progress_active"), inpaintProgressActive());
  telemetry.insert(QStringLiteral("progress_value"), inpaintProgressValue());
  telemetry.insert(QStringLiteral("progress_label"), inpaintProgressLabel());
  recordMaskWorkTelemetry(telemetry);
  if (final_quality) {
    setInpaintProgress(false, 1.0, QStringLiteral("Final inpaint complete"));
  }
  setStatus(status);
}

void EditorPreviewController::regenerateInpaintSeed() {
  setInpaintSeed(inpaint_seed_ + 1);
  setStatus(QStringLiteral("Inpaint seed advanced to %1.").arg(inpaint_seed_));
}

bool EditorPreviewController::regenerateActiveInpaintPatch() {
  return regenerateActiveInpaintPatchWithQuality({}, {});
}

bool EditorPreviewController::queueActiveFinalInpaintPatch() {
  if (!activeInpaintFinalizationAvailable()) {
    setStatus(QStringLiteral("No preview-quality retouch patch is waiting for final-resolution inpaint."));
    return false;
  }

  return regenerateActiveInpaintPatchWithQuality(
      QStringLiteral("final"),
      QStringLiteral("Queued final-resolution inpaint and baked %1 retouch with seed %2."));
}

bool EditorPreviewController::regenerateActiveInpaintPatchWithQuality(
    const QString& requested_quality_mode,
    const QString& success_status_template) {
  if (!hasActiveMask()) {
    setStatus(QStringLiteral("No active retouch patch is available to regenerate."));
    return false;
  }

  auto mask = activeMaskDefinition();
  const auto retouch_mode = mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower();
  if (mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
      !mask.value(QStringLiteral("committed")).toBool() ||
      (retouch_mode != QStringLiteral("remove") && retouch_mode != QStringLiteral("heal") &&
       retouch_mode != QStringLiteral("patch"))) {
    regenerateInpaintSeed();
    return false;
  }

  if (inpaint_apply_watcher_.isRunning() || inpaint_regenerate_watcher_.isRunning()) {
    setStatus(QStringLiteral("Another inpaint job is already running. Wait for it to finish before regenerating."));
    return false;
  }

  auto source_mask_data = mask.value(QStringLiteral("inpaintSourceMaskData")).toByteArray();
  auto source_mask_width = mask.value(QStringLiteral("inpaintSourceMaskWidth")).toInt();
  auto source_mask_height = mask.value(QStringLiteral("inpaintSourceMaskHeight")).toInt();
  if (!valid_segmentation_payload(source_mask_data, source_mask_width, source_mask_height) ||
      selected_pixel_count_for_mask_data(source_mask_data) <= 0) {
    setStatus(QStringLiteral("This retouch patch does not have a reusable inpaint source mask."));
    return false;
  }

  const auto stored_quality_mode =
      mask.value(QStringLiteral("inpaintQualityMode")).toString().trimmed().toLower() ==
              QStringLiteral("final")
          ? QStringLiteral("final")
          : QStringLiteral("preview");
  const auto quality_mode =
      requested_quality_mode.trimmed().toLower() == QStringLiteral("final")
          ? QStringLiteral("final")
          : stored_quality_mode;
  const auto target_candidate_index = activeInpaintCandidateIndex();
  const auto target_variation_label =
      target_candidate_index > 0
          ? QStringLiteral(" variation %1").arg(target_candidate_index + 1)
          : QString();
  const auto report_inpaint_progress = quality_mode == QStringLiteral("final");
  if (report_inpaint_progress) {
    setInpaintProgress(
        true,
        0.05,
        QStringLiteral("Preparing final-resolution inpaint%1").arg(target_variation_label));
    setStatus(
        QStringLiteral("Preparing final-resolution inpaint%1").arg(target_variation_label));
  } else {
    setStatus(QStringLiteral("Preparing inpaint regeneration%1").arg(target_variation_label));
  }
  const auto inpaint_job_generation = ++inpaint_job_generation_;
  const auto inpaint_state_revision = mask_work_state_revision_;
  const auto inpaint_state = currentState();
  latest_inpaint_job_ = make_async_mask_job(
      QStringLiteral("inpaint_regenerate"),
      QStringLiteral("regenerate"),
      asset_id_,
      file_path_,
      inpaint_state,
      inpaint_job_generation,
      inpaint_state_revision);
  const auto inpaint_job = latest_inpaint_job_;
  inpaint_regenerate_watcher_.setFuture(QtConcurrent::run(
      run_inpaint_regenerate_work,
      InpaintRegenerateRequest{
          .job = inpaint_job,
          .file_path = file_path_,
          .asset_id = asset_id_,
          .state = inpaint_state,
          .mask = mask,
          .mask_index = active_mask_index_,
          .mask_id = mask.value(QStringLiteral("id")).toString(),
          .retouch_mode = retouch_mode,
          .prompt = inpaint_prompt_,
          .quality_mode = quality_mode,
          .success_status_template = success_status_template,
          .fallback_seed = inpaint_seed_,
          .fallback_blend_amount = inpaint_blend_amount_,
          .target_candidate_index = target_candidate_index,
          .generation = inpaint_job_generation,
          .state_revision = inpaint_state_revision,
      }));
  updateProcessingState();
  return true;
}

bool EditorPreviewController::retryLastMaskAction() {
  if (mask_retry_action_ == QStringLiteral("smart-selection")) {
    const auto points = mask_retry_points_;
    const auto intent = mask_retry_intent_.isEmpty() ? QStringLiteral("selection") : mask_retry_intent_;
    const auto create_new = mask_retry_create_new_;
    const auto result = pickMaskPath(points, intent, create_new);
    return result != QStringLiteral("error") &&
           result != QStringLiteral("selection-missed") &&
           result != QStringLiteral("remove-missed");
  }
  if (mask_retry_action_ == QStringLiteral("inpaint")) {
    return retryInpaintForMode(mask_retry_retouch_mode_);
  }
  setStatus(QStringLiteral("No failed mask action is available to retry."));
  return false;
}

void EditorPreviewController::cancelActiveRetouch() {
  if (!hasActiveMask()) {
    return;
  }

  const auto active_mask = mask_stack_.at(active_mask_index_).toMap();
  const auto active_retouch_mode =
      active_mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower();
  if (active_mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
      active_mask.value(QStringLiteral("committed")).toBool() ||
      active_retouch_mode.isEmpty()) {
    return;
  }

  auto next_stack = mask_stack_;
  auto changed = false;
  for (qsizetype index = next_stack.size(); index > 0; --index) {
    const auto mask_index = index - 1;
    const auto mask = next_stack.at(mask_index).toMap();
    if (mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
        mask.value(QStringLiteral("committed")).toBool() ||
        mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower() != active_retouch_mode) {
      continue;
    }
    next_stack.removeAt(mask_index);
    changed = true;
  }
  if (!changed) {
    return;
  }

  const auto next_index =
      next_stack.isEmpty()
          ? -1
          : qBound(0, active_mask_index_, static_cast<int>(next_stack.size()) - 1);
  applyMaskStackChange(next_stack, next_index, false);
  setStatus(
      QStringLiteral("%1 retouch cleared.")
          .arg(active_retouch_mode.left(1).toUpper() + active_retouch_mode.mid(1)));
}

bool EditorPreviewController::resetActiveRetouchSelection() {
  if (!hasActiveMask() || activeMaskLocked()) {
    return false;
  }

  auto mask = activeMaskDefinition();
  const auto active_retouch_mode =
      mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower();
  if (mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
      mask.value(QStringLiteral("committed")).toBool() ||
      active_retouch_mode.isEmpty()) {
    return false;
  }

  clear_retouch_selection_payload(&mask);
  remove_inpaint_patch_payload(&mask);
  mask.insert(QStringLiteral("committed"), false);
  if (!updateActiveMaskDefinition(mask, false, false, QStringLiteral("retouch_reset_selection"))) {
    return false;
  }
  clearActiveBrushLivePreview();
  emit activeBrushStrokeChanged();
  setStatus(
      QStringLiteral("%1 retouch selection reset. Paint or select a new target before applying.")
          .arg(active_retouch_mode.left(1).toUpper() + active_retouch_mode.mid(1)));
  return true;
}

bool EditorPreviewController::deleteActiveRetouchPatch() {
  if (!hasActiveMask() || activeMaskLocked()) {
    return false;
  }

  const auto active_mask = activeMaskDefinition();
  const auto active_retouch_mode =
      active_mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower();
  if (active_mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
      active_retouch_mode.isEmpty()) {
    return false;
  }

  auto next_stack = mask_stack_;
  next_stack.removeAt(active_mask_index_);
  const auto next_index =
      next_stack.isEmpty()
          ? -1
          : qBound(0, active_mask_index_, static_cast<int>(next_stack.size()) - 1);
  if (!applyMaskStackChange(next_stack, next_index, true, QStringLiteral("retouch_delete_patch"))) {
    return false;
  }
  setStatus(
      QStringLiteral("%1 retouch patch deleted from the recipe.")
          .arg(active_retouch_mode.left(1).toUpper() + active_retouch_mode.mid(1)));
  return true;
}

bool EditorPreviewController::reopenActiveRetouchSelection() {
  if (!hasActiveMask() || activeMaskLocked()) {
    return false;
  }

  auto mask = activeMaskDefinition();
  const auto active_retouch_mode =
      mask.value(QStringLiteral("retouchMode")).toString().trimmed().toLower();
  if (mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
      !mask.value(QStringLiteral("committed")).toBool() ||
      active_retouch_mode.isEmpty()) {
    return false;
  }

  const auto source_mask_data = mask.value(QStringLiteral("inpaintSourceMaskData")).toByteArray();
  const auto source_mask_width = mask.value(QStringLiteral("inpaintSourceMaskWidth")).toInt();
  const auto source_mask_height = mask.value(QStringLiteral("inpaintSourceMaskHeight")).toInt();
  if (valid_segmentation_payload(source_mask_data, source_mask_width, source_mask_height)) {
    mask.insert(QStringLiteral("segmentationData"), source_mask_data);
    mask.insert(QStringLiteral("segmentationWidth"), source_mask_width);
    mask.insert(QStringLiteral("segmentationHeight"), source_mask_height);
  }

  const auto prompt = mask.value(QStringLiteral("inpaintPrompt")).toString();
  const auto quality_mode = mask.value(QStringLiteral("inpaintQualityMode")).toString();
  const auto seed = mask.value(QStringLiteral("inpaintSeed")).toInt();
  const auto blend_amount = mask.value(QStringLiteral("inpaintBlendAmount")).toDouble();
  remove_inpaint_patch_payload(&mask);
  mask.insert(QStringLiteral("committed"), false);
  if (!updateActiveMaskDefinition(mask, false, false, QStringLiteral("retouch_reopen_selection"))) {
    return false;
  }
  if (!prompt.isEmpty()) {
    inpaint_prompt_ = prompt;
  }
  if (quality_mode == QStringLiteral("final") || quality_mode == QStringLiteral("preview")) {
    inpaint_quality_mode_ = quality_mode;
  }
  if (seed > 0) {
    inpaint_seed_ = seed;
  }
  if (blend_amount >= 0.0 && blend_amount <= 1.0) {
    inpaint_blend_amount_ = blend_amount;
  }
  emit controlsChanged();
  setStatus(
      QStringLiteral("%1 retouch selection reopened. Refine the selection, then apply again.")
          .arg(active_retouch_mode.left(1).toUpper() + active_retouch_mode.mid(1)));
  return true;
}

void EditorPreviewController::startPolygonSelection(bool subtract) {
  auto next_stack = mask_stack_;
  const auto insert_index =
      hasActiveMask() ? qBound(0, active_mask_index_ + 1, static_cast<int>(next_stack.size()))
                      : static_cast<int>(next_stack.size());

  auto mask_def = default_mask_definition(QStringLiteral("polygon"), insert_index + 1);
  mask_def.insert(
      QStringLiteral("name"),
      subtract ? QStringLiteral("Polygon Subtract %1").arg(insert_index + 1)
               : QStringLiteral("Polygon Select %1").arg(insert_index + 1));
  mask_def.insert(QStringLiteral("operation"), subtract ? QStringLiteral("subtract")
                                                        : QStringLiteral("add"));
  if (hasActiveMask()) {
    const auto active_mask = activeMaskDefinition();
    if (is_selection_mask(active_mask)) {
      inherit_selection_mask_set(&mask_def, active_mask);
    }
  }
  mask_def.insert(QStringLiteral("feather"), 0.04);
  next_stack.insert(insert_index, mask_def);
  applyMaskStackChange(next_stack, insert_index, true, {}, true);
  setStatus(
      subtract ? QStringLiteral("Polygon subtract started. Click to remove areas from the selection.")
                : QStringLiteral("Polygon selection started. Click to place points."));
}

void EditorPreviewController::startLassoSelection(bool subtract) {
  auto next_stack = mask_stack_;
  const auto insert_index =
      hasActiveMask() ? qBound(0, active_mask_index_ + 1, static_cast<int>(next_stack.size()))
                      : static_cast<int>(next_stack.size());

  auto mask_def = default_mask_definition(QStringLiteral("lasso"), insert_index + 1);
  mask_def.insert(
      QStringLiteral("name"),
      subtract ? QStringLiteral("Lasso Subtract %1").arg(insert_index + 1)
               : QStringLiteral("Lasso Select %1").arg(insert_index + 1));
  mask_def.insert(QStringLiteral("operation"), subtract ? QStringLiteral("subtract")
                                                        : QStringLiteral("add"));
  if (hasActiveMask()) {
    const auto active_mask = activeMaskDefinition();
    if (is_selection_mask(active_mask)) {
      inherit_selection_mask_set(&mask_def, active_mask);
    }
  }
  mask_def.insert(QStringLiteral("feather"), 0.04);
  mask_def.insert(QStringLiteral("lassoClosed"), false);
  mask_def.insert(QStringLiteral("lassoFreehandPath"), true);
  mask_def.insert(QStringLiteral("lassoRawPointCount"), 0);
  next_stack.insert(insert_index, mask_def);
  applyMaskStackChange(next_stack, insert_index, true, {}, true);
  setStatus(
      subtract ? QStringLiteral("Lasso subtract started. Drag to remove areas from the selection.")
               : QStringLiteral("Lasso selection started. Drag to define the selection."));
}

void EditorPreviewController::appendActivePolygonPoint(double normalized_x, double normalized_y) {
  auto mask = activeMaskDefinition();
  const auto kind = activeMaskKind();
  if (mask.isEmpty() || (kind != QStringLiteral("polygon") && kind != QStringLiteral("lasso"))) {
    return;
  }

  QVariantMap point;
  point.insert(QStringLiteral("x"), qBound(0.0, normalized_x, 1.0));
  point.insert(QStringLiteral("y"), qBound(0.0, normalized_y, 1.0));

  auto points = mask.value(QStringLiteral("polygonPoints")).toList();
  if (!points.isEmpty()) {
    const auto last = points.constLast().toMap();
    const auto dx = point.value(QStringLiteral("x")).toDouble() - last.value(QStringLiteral("x")).toDouble();
    const auto dy = point.value(QStringLiteral("y")).toDouble() - last.value(QStringLiteral("y")).toDouble();
    if (std::hypot(dx, dy) < 0.004) {
      return;
    }
  }
  points.append(point);
  mask.insert(QStringLiteral("polygonPoints"), points);
  if (kind == QStringLiteral("lasso")) {
    auto raw_points = mask.value(QStringLiteral("lassoRawPoints")).toList();
    raw_points.append(point);
    mask.insert(QStringLiteral("lassoRawPoints"), raw_points);
    mask.insert(QStringLiteral("lassoRawPointCount"), raw_points.size());
    mask.insert(QStringLiteral("lassoClosed"), false);
    mask.insert(QStringLiteral("lassoFreehandPath"), true);
  }
  updateActiveMaskDefinition(mask);
}

bool EditorPreviewController::moveActivePolygonPoint(
    int point_index,
    double normalized_x,
    double normalized_y) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("polygon")) {
    return false;
  }

  auto points = mask.value(QStringLiteral("polygonPoints")).toList();
  if (point_index < 0 || point_index >= points.size()) {
    return false;
  }

  QVariantMap point;
  point.insert(QStringLiteral("x"), qBound(0.0, normalized_x, 1.0));
  point.insert(QStringLiteral("y"), qBound(0.0, normalized_y, 1.0));
  if (points.at(point_index).toMap() == point) {
    return false;
  }

  points[point_index] = point;
  mask.insert(QStringLiteral("polygonPoints"), points);
  updateActiveMaskDefinition(mask);
  setStatus(QStringLiteral("Polygon point moved."));
  return true;
}

bool EditorPreviewController::insertActivePolygonPointAfter(
    int point_index,
    double normalized_x,
    double normalized_y) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("polygon")) {
    return false;
  }

  auto points = mask.value(QStringLiteral("polygonPoints")).toList();
  if (points.size() < 3 || point_index < 0 || point_index >= points.size()) {
    return false;
  }

  QVariantMap point;
  point.insert(QStringLiteral("x"), qBound(0.0, normalized_x, 1.0));
  point.insert(QStringLiteral("y"), qBound(0.0, normalized_y, 1.0));
  points.insert(point_index + 1, point);
  mask.insert(QStringLiteral("polygonPoints"), points);
  updateActiveMaskDefinition(mask);
  setStatus(QStringLiteral("Polygon point inserted."));
  return true;
}

void EditorPreviewController::removeLastActivePolygonPoint() {
  auto mask = activeMaskDefinition();
  const auto kind = activeMaskKind();
  if (mask.isEmpty() || (kind != QStringLiteral("polygon") && kind != QStringLiteral("lasso"))) {
    return;
  }
  auto points = mask.value(QStringLiteral("polygonPoints")).toList();
  if (points.isEmpty()) {
    return;
  }
  points.removeLast();
  mask.insert(QStringLiteral("polygonPoints"), points);
  if (kind == QStringLiteral("lasso")) {
    auto raw_points = mask.value(QStringLiteral("lassoRawPoints")).toList();
    if (!raw_points.isEmpty()) {
      raw_points.removeLast();
    }
    mask.insert(QStringLiteral("lassoRawPoints"), raw_points);
    mask.insert(QStringLiteral("lassoRawPointCount"), raw_points.size());
    mask.insert(QStringLiteral("lassoClosed"), false);
  }
  updateActiveMaskDefinition(mask);
}

void EditorPreviewController::clearActivePolygonPoints() {
  auto mask = activeMaskDefinition();
  const auto kind = activeMaskKind();
  if (mask.isEmpty() || (kind != QStringLiteral("polygon") && kind != QStringLiteral("lasso"))) {
    return;
  }
  mask.insert(QStringLiteral("polygonPoints"), QVariantList{});
  if (kind == QStringLiteral("lasso")) {
    mask.insert(QStringLiteral("lassoRawPoints"), QVariantList{});
    mask.insert(QStringLiteral("lassoRawPointCount"), 0);
    mask.insert(QStringLiteral("lassoSimplifiedPointCount"), 0);
    mask.insert(QStringLiteral("lassoClosed"), false);
  }
  updateActiveMaskDefinition(mask);
}

bool EditorPreviewController::simplifyActivePolygon(double tolerance) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("polygon")) {
    return false;
  }

  const auto original_points = normalized_polygon_points(mask.value(QStringLiteral("polygonPoints")).toList());
  if (original_points.size() <= 3) {
    return false;
  }
  const auto simplified_points = simplified_closed_polygon_points(original_points, tolerance);
  if (simplified_points.size() == original_points.size()) {
    return false;
  }

  mask.insert(QStringLiteral("polygonPoints"), variant_list_from_polygon_points(simplified_points));
  updateActiveMaskDefinition(mask);
  setStatus(QStringLiteral("Polygon simplified."));
  return true;
}

bool EditorPreviewController::smoothActivePolygon() {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("polygon")) {
    return false;
  }

  const auto original_points = normalized_polygon_points(mask.value(QStringLiteral("polygonPoints")).toList());
  if (original_points.size() < 3) {
    return false;
  }

  mask.insert(
      QStringLiteral("polygonPoints"),
      variant_list_from_polygon_points(smoothed_closed_polygon_points(original_points)));
  updateActiveMaskDefinition(mask);
  setStatus(QStringLiteral("Polygon smoothed."));
  return true;
}

bool EditorPreviewController::closeActiveLassoPath(double tolerance) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("lasso")) {
    return false;
  }

  const auto raw_point_values = mask.value(QStringLiteral("lassoRawPoints")).toList();
  auto raw_points = normalized_polygon_points(
      raw_point_values.isEmpty() ? mask.value(QStringLiteral("polygonPoints")).toList()
                                 : raw_point_values);
  if (raw_points.size() < 3) {
    return false;
  }

  auto simplified_points =
      simplified_closed_polygon_points(raw_points, std::clamp(tolerance, 0.002, 0.04));
  if (simplified_points.size() < 3) {
    simplified_points = raw_points;
  }
  auto smoothed_points = smoothed_closed_polygon_points(simplified_points);
  smoothed_points = simplified_closed_polygon_points(smoothed_points, 0.003);
  if (smoothed_points.size() < 3) {
    smoothed_points = simplified_points;
  }

  mask.insert(QStringLiteral("polygonPoints"), variant_list_from_polygon_points(smoothed_points));
  mask.insert(QStringLiteral("lassoRawPoints"), variant_list_from_polygon_points(raw_points));
  mask.insert(QStringLiteral("lassoRawPointCount"), raw_points.size());
  mask.insert(QStringLiteral("lassoSimplifiedPointCount"), smoothed_points.size());
  mask.insert(QStringLiteral("lassoClosed"), true);
  mask.insert(QStringLiteral("lassoSimplified"), true);
  mask.insert(QStringLiteral("lassoSmoothed"), true);
  mask.insert(QStringLiteral("lassoFreehandPath"), true);
  updateActiveMaskDefinition(mask);
  setStatus(QStringLiteral("Lasso selection closed."));
  return true;
}

void EditorPreviewController::duplicateActiveMask() {
  const auto mask = activeMaskDefinition();
  if (mask.isEmpty()) {
    return;
  }

  auto next_stack = mask_stack_;
  auto duplicate = mask;
  duplicate.insert(
      QStringLiteral("id"),
      unique_mask_copy_id(next_stack, mask.value(QStringLiteral("id")).toString()));
  duplicate.insert(
      QStringLiteral("name"),
      unique_mask_copy_name(next_stack, mask.value(QStringLiteral("name")).toString()));
  next_stack.insert(active_mask_index_ + 1, duplicate);
  applyMaskStackChange(next_stack, active_mask_index_ + 1);
}

void EditorPreviewController::duplicateActiveMaskInverted() {
  const auto mask = activeMaskDefinition();
  if (mask.isEmpty() || !is_selection_mask(mask)) {
    return;
  }

  auto next_stack = mask_stack_;
  auto duplicate = mask;
  duplicate.insert(
      QStringLiteral("id"),
      unique_mask_copy_id(next_stack, mask.value(QStringLiteral("id")).toString()));
  duplicate.insert(
      QStringLiteral("name"),
      unique_mask_copy_name(next_stack, mask.value(QStringLiteral("name")).toString()));
  duplicate.insert(QStringLiteral("invert"), true);
  duplicate.insert(QStringLiteral("selectionInvert"), true);
  next_stack.insert(active_mask_index_ + 1, duplicate);
  applyMaskStackChange(next_stack, active_mask_index_ + 1);
}

bool EditorPreviewController::duplicateActiveMaskSet() {
  const auto active_mask = activeMaskDefinition();
  if (active_mask.isEmpty() || !is_selection_mask(active_mask)) {
    return false;
  }

  const auto source_set_id = active_mask.value(QStringLiteral("maskSetId")).toString().simplified();
  if (source_set_id.isEmpty()) {
    return false;
  }

  auto insert_after = -1;
  QVariantList copied_sources;
  QHash<QString, QString> copied_ids_by_original;
  auto identity_stack = mask_stack_;
  const auto copied_set_id = unique_mask_set_copy_id(mask_stack_, source_set_id);
  const auto copied_set_name = unique_mask_set_copy_name(
      mask_stack_,
      active_mask.value(QStringLiteral("maskSetName")).toString());

  for (auto index = 0; index < mask_stack_.size(); ++index) {
    auto source = normalized_mask_definition(mask_stack_.at(index).toMap(), index + 1);
    if (!is_selection_mask(source) ||
        source.value(QStringLiteral("maskSetId")).toString() != source_set_id) {
      continue;
    }

    insert_after = index;
    const auto original_id = source.value(QStringLiteral("id")).toString();
    const auto copied_id = unique_mask_copy_id(identity_stack, original_id);
    copied_ids_by_original.insert(original_id, copied_id);
    source.insert(QStringLiteral("id"), copied_id);
    source.insert(
        QStringLiteral("name"),
        unique_mask_copy_name(identity_stack, source.value(QStringLiteral("name")).toString()));
    source.insert(QStringLiteral("maskSetId"), copied_set_id);
    source.insert(QStringLiteral("maskSetName"), copied_set_name);
    source.insert(QStringLiteral("solo"), false);
    identity_stack.append(source);
    copied_sources.append(source);
  }

  if (insert_after < 0 || copied_sources.isEmpty()) {
    return false;
  }

  for (auto index = 0; index < copied_sources.size(); ++index) {
    auto source = copied_sources.at(index).toMap();
    const auto parent_id = source.value(QStringLiteral("parentId")).toString();
    if (copied_ids_by_original.contains(parent_id)) {
      source.insert(QStringLiteral("parentId"), copied_ids_by_original.value(parent_id));
    }
    const auto output_id = source.value(QStringLiteral("outputId")).toString();
    if (copied_ids_by_original.contains(output_id)) {
      source.insert(QStringLiteral("outputId"), copied_ids_by_original.value(output_id));
    } else if (source.value(QStringLiteral("reusableOutput")).toBool() && output_id.isEmpty()) {
      source.insert(QStringLiteral("outputId"), source.value(QStringLiteral("id")).toString());
    }
    copied_sources[index] = source;
  }

  auto next_stack = mask_stack_;
  for (auto offset = 0; offset < copied_sources.size(); ++offset) {
    next_stack.insert(insert_after + 1 + offset, copied_sources.at(offset));
  }
  return applyMaskStackChange(
      next_stack,
      insert_after + 1,
      true,
      QStringLiteral("mask_set_duplicate"),
      true);
}

bool EditorPreviewController::setMaskSetEnabled(const QString& set_id, bool enabled) {
  const auto normalized_set_id = set_id.simplified();
  if (normalized_set_id.isEmpty()) {
    return false;
  }

  auto next_stack = mask_stack_;
  auto changed = false;
  auto matched = false;
  for (auto index = 0; index < next_stack.size(); ++index) {
    auto mask = normalized_mask_definition(next_stack.at(index).toMap(), index + 1);
    if (!is_selection_mask(mask) ||
        mask.value(QStringLiteral("maskSetId")).toString() != normalized_set_id) {
      continue;
    }
    matched = true;
    if (map_bool_value(mask, QStringLiteral("locked"), false)) {
      return false;
    }
    if (map_bool_value(mask, QStringLiteral("enabled"), true) == enabled) {
      continue;
    }
    mask.insert(QStringLiteral("enabled"), enabled);
    next_stack[index] = mask;
    changed = true;
  }

  if (!matched || !changed) {
    return false;
  }
  return applyMaskStackChange(
      next_stack,
      active_mask_index_,
      true,
      QStringLiteral("mask_set_visibility"));
}

bool EditorPreviewController::setMaskSetPreviewBypassed(const QString& set_id, bool bypassed) {
  const auto normalized_set_id = set_id.simplified();
  if (normalized_set_id.isEmpty()) {
    return false;
  }

  auto next_stack = mask_stack_;
  auto changed = false;
  auto matched = false;
  QString set_name;
  for (auto index = 0; index < next_stack.size(); ++index) {
    auto mask = normalized_mask_definition(next_stack.at(index).toMap(), index + 1);
    if (!is_selection_mask(mask) ||
        mask.value(QStringLiteral("maskSetId")).toString() != normalized_set_id) {
      continue;
    }
    matched = true;
    if (set_name.isEmpty()) {
      set_name = mask.value(QStringLiteral("maskSetName")).toString().simplified();
    }
    if (mask.value(QStringLiteral("maskSetPreviewBypassed")).toBool() == bypassed) {
      continue;
    }
    mask.insert(QStringLiteral("maskSetPreviewBypassed"), bypassed);
    next_stack[index] = mask;
    changed = true;
  }

  if (!matched || !changed) {
    return false;
  }
  if (!applyMaskStackChange(
          next_stack,
          active_mask_index_,
          true,
          QStringLiteral("mask_set_before_after_preview"))) {
    return false;
  }
  setStatus(
      bypassed
          ? QStringLiteral("Showing preview before mask attachment%1.")
                .arg(set_name.isEmpty() ? QString() : QStringLiteral(" %1").arg(set_name))
          : QStringLiteral("Showing preview with mask attachment%1.")
                .arg(set_name.isEmpty() ? QString() : QStringLiteral(" %1").arg(set_name)));
  return true;
}

bool EditorPreviewController::setMaskSetSolo(const QString& set_id, bool solo) {
  const auto normalized_set_id = set_id.simplified();
  if (normalized_set_id.isEmpty()) {
    return false;
  }

  auto next_stack = mask_stack_;
  auto changed = false;
  auto matched = false;
  for (auto index = 0; index < next_stack.size(); ++index) {
    auto mask = normalized_mask_definition(next_stack.at(index).toMap(), index + 1);
    if (!is_selection_mask(mask)) {
      continue;
    }
    const auto in_target_set =
        mask.value(QStringLiteral("maskSetId")).toString() == normalized_set_id;
    if (in_target_set) {
      matched = true;
    }
    const auto next_solo = solo && in_target_set;
    if (map_bool_value(mask, QStringLiteral("locked"), false) &&
        map_bool_value(mask, QStringLiteral("solo"), false) != next_solo) {
      return false;
    }
    if (map_bool_value(mask, QStringLiteral("solo"), false) == next_solo) {
      continue;
    }
    mask.insert(QStringLiteral("solo"), next_solo);
    next_stack[index] = mask;
    changed = true;
  }

  if (!matched || !changed) {
    return false;
  }
  return applyMaskStackChange(next_stack, active_mask_index_, true, QStringLiteral("mask_set_solo"));
}

bool EditorPreviewController::setMaskSourceEnabled(int index, bool enabled) {
  if (index < 0 || index >= mask_stack_.size()) {
    return false;
  }
  auto mask = normalized_mask_definition(mask_stack_.at(index).toMap(), index + 1);
  if (!is_selection_mask(mask) || map_bool_value(mask, QStringLiteral("locked"), false) ||
      map_bool_value(mask, QStringLiteral("enabled"), true) == enabled) {
    return false;
  }
  mask.insert(QStringLiteral("enabled"), enabled);
  auto next_stack = mask_stack_;
  next_stack[index] = mask;
  return applyMaskStackChange(
      next_stack,
      active_mask_index_,
      true,
      QStringLiteral("mask_source_visibility"));
}

bool EditorPreviewController::setMaskSourceSolo(int index, bool solo) {
  if (index < 0 || index >= mask_stack_.size()) {
    return false;
  }
  const auto target_mask = normalized_mask_definition(mask_stack_.at(index).toMap(), index + 1);
  if (!is_selection_mask(target_mask)) {
    return false;
  }

  auto next_stack = mask_stack_;
  auto changed = false;
  for (auto source_index = 0; source_index < next_stack.size(); ++source_index) {
    auto mask = normalized_mask_definition(next_stack.at(source_index).toMap(), source_index + 1);
    if (!is_selection_mask(mask)) {
      continue;
    }
    const auto next_solo = solo && source_index == index;
    if (map_bool_value(mask, QStringLiteral("locked"), false) &&
        map_bool_value(mask, QStringLiteral("solo"), false) != next_solo) {
      return false;
    }
    if (map_bool_value(mask, QStringLiteral("solo"), false) == next_solo) {
      continue;
    }
    mask.insert(QStringLiteral("solo"), next_solo);
    next_stack[source_index] = mask;
    changed = true;
  }
  if (!changed) {
    return false;
  }
  return applyMaskStackChange(next_stack, index, true, QStringLiteral("mask_source_solo"));
}

bool EditorPreviewController::moveMaskSource(
    int index,
    const QString& target_set_id,
    int target_source_index) {
  if (index < 0 || index >= mask_stack_.size()) {
    return false;
  }
  auto source_mask = normalized_mask_definition(mask_stack_.at(index).toMap(), index + 1);
  if (!is_selection_mask(source_mask) ||
      map_bool_value(source_mask, QStringLiteral("locked"), false)) {
    return false;
  }

  const auto normalized_target_set_id = target_set_id.simplified();
  if (normalized_target_set_id.isEmpty()) {
    return false;
  }

  QVariantMap target_set_reference;
  for (auto source_index = 0; source_index < mask_stack_.size(); ++source_index) {
    const auto mask = normalized_mask_definition(mask_stack_.at(source_index).toMap(), source_index + 1);
    if (!is_selection_mask(mask) ||
        mask.value(QStringLiteral("maskSetId")).toString() != normalized_target_set_id) {
      continue;
    }
    if (target_set_reference.isEmpty()) {
      target_set_reference = mask;
    }
  }
  if (target_set_reference.isEmpty()) {
    return false;
  }

  const auto source_set_id = source_mask.value(QStringLiteral("maskSetId")).toString();
  const auto same_set = source_set_id == normalized_target_set_id;
  if (!same_set) {
    source_mask.insert(QStringLiteral("maskSetId"), normalized_target_set_id);
    source_mask.insert(
        QStringLiteral("maskSetName"),
        target_set_reference.value(QStringLiteral("maskSetName")).toString());
    copy_selection_adjustments_to_mask(&source_mask, target_set_reference);
  }

  auto next_stack = mask_stack_;
  next_stack.removeAt(index);

  QVariantList target_indices_after_remove;
  for (auto source_index = 0; source_index < next_stack.size(); ++source_index) {
    const auto mask = normalized_mask_definition(next_stack.at(source_index).toMap(), source_index + 1);
    if (is_selection_mask(mask) &&
        mask.value(QStringLiteral("maskSetId")).toString() == normalized_target_set_id) {
      target_indices_after_remove.append(source_index);
    }
  }
  if (target_indices_after_remove.isEmpty()) {
    return false;
  }

  const auto target_count_after_remove = target_indices_after_remove.size();
  const auto normalized_target_source_index =
      qBound(0, target_source_index, target_count_after_remove);
  auto insert_index = next_stack.size();
  if (normalized_target_source_index < target_count_after_remove) {
    insert_index = target_indices_after_remove.at(normalized_target_source_index).toInt();
  } else {
    insert_index = target_indices_after_remove.constLast().toInt() + 1;
  }

  if (insert_index < 0 || insert_index > next_stack.size()) {
    return false;
  }
  const auto inserted_active_index = static_cast<int>(insert_index);

  next_stack.insert(insert_index, source_mask);
  if (next_stack == mask_stack_) {
    return false;
  }
  return applyMaskStackChange(
      next_stack,
      inserted_active_index,
      true,
      same_set ? QStringLiteral("mask_source_reorder")
               : QStringLiteral("mask_source_move_set"));
}

bool EditorPreviewController::moveMaskSetInPhotoLayer(
    int layer_index,
    const QString& set_id,
    int target_mask_index) {
  if (layer_index < 0 || layer_index >= photo_layers_.size()) {
    return false;
  }
  auto layer = photo_layers_.at(layer_index).toMap();
  if (layer.value(QStringLiteral("kind")).toString().trimmed().toLower() !=
          QStringLiteral("adjustment") ||
      !layer.value(QStringLiteral("selectionScoped")).toBool() ||
      layer.value(QStringLiteral("locked")).toBool()) {
    return false;
  }

  const auto normalized_set_id = set_id.simplified();
  if (normalized_set_id.isEmpty()) {
    return false;
  }
  auto ids = selection_mask_set_ids_for_layer(layer);
  auto names = selection_mask_set_names_for_layer(layer);
  const auto source_index = static_cast<int>(ids.indexOf(normalized_set_id));
  const auto id_count = static_cast<int>(ids.size());
  if (source_index < 0 || id_count < 2) {
    return false;
  }

  const auto normalized_target_index = qBound(0, target_mask_index, id_count - 1);
  if (source_index == normalized_target_index) {
    return false;
  }

  const auto moved_id = ids.takeAt(source_index);
  ids.insert(normalized_target_index, moved_id);
  if (names.size() == ids.size()) {
    const auto moved_name = names.takeAt(source_index);
    names.insert(normalized_target_index, moved_name);
  } else {
    names.clear();
    for (const auto& ordered_id : ids) {
      QString ordered_name;
      for (const auto& value : mask_stack_) {
        const auto mask = value.toMap();
        if (mask.value(QStringLiteral("maskSetId")).toString().simplified() == ordered_id) {
          ordered_name = mask.value(QStringLiteral("maskSetName")).toString().simplified();
          break;
        }
      }
      names.push_back(ordered_name);
    }
  }

  layer.insert(QStringLiteral("selectionMaskSetIds"), string_list_to_variant_list(ids));
  layer.insert(QStringLiteral("selectionMaskSetNames"), string_list_to_variant_list(names));
  if (!ids.isEmpty()) {
    layer.insert(QStringLiteral("selectionMaskSetId"), ids.constFirst());
  }
  if (!names.isEmpty()) {
    layer.insert(QStringLiteral("selectionMaskSetName"), names.constFirst());
  }

  auto next_layers = photo_layers_;
  next_layers[layer_index] = layer;
  return applyPhotoLayerStackChange(
      next_layers,
      QStringLiteral("photo_layer_mask_set_reorder"),
      false,
      QStringLiteral("Reorder layer masks"));
}

void EditorPreviewController::removeActiveMask() {
  if (!hasActiveMask() || activeMaskLocked()) {
    return;
  }

  auto next_stack = mask_stack_;
  next_stack.removeAt(active_mask_index_);
  const auto next_index =
      next_stack.isEmpty()
          ? -1
          : qBound(0, active_mask_index_, static_cast<int>(next_stack.size()) - 1);
  applyMaskStackChange(next_stack, next_index);
}

void EditorPreviewController::moveActiveMask(int offset) {
  if (!hasActiveMask() || activeMaskLocked() || offset == 0) {
    return;
  }

  const auto target_index = qBound(
      0, active_mask_index_ + offset, static_cast<int>(mask_stack_.size()) - 1);
  if (target_index == active_mask_index_) {
    return;
  }

  auto next_stack = mask_stack_;
  next_stack.move(active_mask_index_, target_index);
  applyMaskStackChange(next_stack, target_index);
}

void EditorPreviewController::beginActiveBrushStroke() {
  if (brush_stroke_active_ || !hasActiveMask() || activeMaskKind() != QStringLiteral("brush")) {
    return;
  }

  brush_stroke_undo_state_valid_ = !asset_id_.isEmpty() && !applying_history_state_;
  if (brush_stroke_undo_state_valid_) {
    brush_stroke_undo_state_ = currentState();
  }
  brush_stroke_active_ = true;
  brush_stroke_suspends_side_effects_ = true;
  brush_stroke_needs_final_render_ = false;
  active_brush_auto_mask_anchor_valid_ = false;
  active_brush_auto_mask_anchor_x_ = 0.5;
  active_brush_auto_mask_anchor_y_ = 0.5;
  pending_brush_commit_preview_points_.clear();
  pending_brush_commit_preview_mask_id_.clear();
  active_brush_live_points_.clear();
  clearActiveBrushLivePreview();
  emit activeBrushStrokeChanged();
}

void EditorPreviewController::schedulePendingBrushCommit(PendingBrushCommit commit) {
  if (commit.live_points.isEmpty()) {
    return;
  }
  if (brush_raster_commit_watcher_.isRunning() &&
      active_brush_raster_commit_request_valid_ &&
      !active_brush_raster_commit_requeued_) {
    const auto& active_request = active_brush_raster_commit_request_;
    constexpr auto kSettingTolerance = 1e-9;
    const auto can_supersede_active =
        active_request.mask_index == commit.mask_index &&
        active_request.mask_id == commit.mask_id &&
        std::abs(active_request.brush_spacing - commit.brush_spacing) <= kSettingTolerance &&
        std::abs(active_request.feather - commit.feather) <= kSettingTolerance &&
        std::abs(active_request.auto_mask_tolerance - commit.auto_mask_tolerance) <=
            kSettingTolerance &&
        active_request.auto_mask == commit.auto_mask &&
        active_request.protect_edges == commit.protect_edges;
    if (can_supersede_active) {
      PendingBrushCommit replay_commit;
      replay_commit.mask_index = active_request.mask_index;
      replay_commit.mask_id = active_request.mask_id;
      replay_commit.mask = active_request.mask;
      replay_commit.live_points = active_request.live_points;
      replay_commit.live_strokes = active_request.live_strokes;
      if (replay_commit.live_strokes.isEmpty() && !replay_commit.live_points.isEmpty()) {
        replay_commit.live_strokes.append(replay_commit.live_points);
      }
      replay_commit.undo_state = active_request.undo_state;
      replay_commit.undo_state_valid = active_request.undo_state_valid;
      replay_commit.undo_label = active_request.undo_label;
      replay_commit.brush_spacing = active_request.brush_spacing;
      replay_commit.feather = active_request.feather;
      replay_commit.auto_mask_tolerance = active_request.auto_mask_tolerance;
      replay_commit.auto_mask = active_request.auto_mask;
      replay_commit.protect_edges = active_request.protect_edges;
      replay_commit.live_preview_elapsed_ms = active_request.live_preview_elapsed_ms;
      replay_commit.live_preview_within_latency_budget =
          active_request.live_preview_within_latency_budget;
      pending_brush_commits_.prepend(std::move(replay_commit));
      active_brush_raster_commit_requeued_ = true;
      latest_brush_raster_generation_->store(
          ++brush_raster_job_generation_,
          std::memory_order_relaxed);
    }
  }
  pending_brush_commits_.append(std::move(commit));
  if (pending_brush_commit_scheduled_) {
    return;
  }
  pending_brush_commit_scheduled_ = true;
  QTimer::singleShot(0, this, [this]() { processNextPendingBrushCommit(); });
  updateProcessingState();
}

void EditorPreviewController::processNextPendingBrushCommit() {
  pending_brush_commit_scheduled_ = false;
  if (pending_brush_commits_.isEmpty() || brush_raster_commit_watcher_.isRunning()) {
    return;
  }

  auto commit = pending_brush_commits_.takeFirst();
  QVector<QVector<BrushPreviewPoint>> live_strokes;
  if (commit.live_strokes.isEmpty()) {
    live_strokes.append(commit.live_points);
  } else {
    live_strokes = commit.live_strokes;
  }
  const auto can_merge_commit = [](const PendingBrushCommit& base, const PendingBrushCommit& candidate) {
    constexpr auto kSettingTolerance = 1e-9;
    return base.mask_index == candidate.mask_index &&
           base.mask_id == candidate.mask_id &&
           std::abs(base.brush_spacing - candidate.brush_spacing) <= kSettingTolerance &&
           std::abs(base.feather - candidate.feather) <= kSettingTolerance &&
           std::abs(base.auto_mask_tolerance - candidate.auto_mask_tolerance) <= kSettingTolerance &&
           base.auto_mask == candidate.auto_mask &&
           base.protect_edges == candidate.protect_edges;
  };
  while (!pending_brush_commits_.isEmpty() &&
         can_merge_commit(commit, pending_brush_commits_.constFirst())) {
    auto next_commit = pending_brush_commits_.takeFirst();
    if (next_commit.live_strokes.isEmpty()) {
      live_strokes.append(next_commit.live_points);
    } else {
      for (const auto& stroke_points : next_commit.live_strokes) {
        live_strokes.append(stroke_points);
      }
    }
    commit.live_preview_elapsed_ms =
        std::max(commit.live_preview_elapsed_ms, next_commit.live_preview_elapsed_ms);
    commit.live_preview_within_latency_budget =
        commit.live_preview_within_latency_budget &&
        next_commit.live_preview_within_latency_budget;
    if (pending_brush_commit_preview_mask_id_ == commit.mask_id) {
      for (const auto& point : next_commit.live_points) {
        pending_brush_commit_preview_points_.append(point);
      }
    }
  }
  commit.live_points.clear();
  for (const auto& stroke_points : live_strokes) {
    commit.live_points.reserve(commit.live_points.size() + stroke_points.size());
    for (const auto& point : stroke_points) {
      commit.live_points.append(point);
    }
  }
  if (pending_brush_commit_preview_mask_id_ == commit.mask_id) {
    pending_brush_commit_preview_points_ = commit.live_points;
    emit activeBrushStrokeChanged();
  }
  auto mask = QVariantMap{};
  if (commit.mask_index >= 0 && commit.mask_index < mask_stack_.size() &&
      !commit.live_points.isEmpty()) {
    mask = maskDefinitionAt(commit.mask_index);
    if (mask.isEmpty() ||
        normalized_mask_kind(mask.value(QStringLiteral("kind")).toString()) !=
            QStringLiteral("brush") ||
        mask.value(QStringLiteral("id")).toString() != commit.mask_id) {
      mask = {};
    }
  }

  if (mask.isEmpty()) {
    if (pending_brush_commit_preview_mask_id_ == commit.mask_id) {
      pending_brush_commit_preview_points_.clear();
      pending_brush_commit_preview_mask_id_.clear();
      emit activeBrushStrokeChanged();
    }
    if (!pending_brush_commits_.isEmpty()) {
      pending_brush_commit_scheduled_ = true;
      QTimer::singleShot(0, this, [this]() { processNextPendingBrushCommit(); });
    }
    return;
  }

  const auto state = currentState();
  const auto generation = ++brush_raster_job_generation_;
  const auto state_revision = mask_work_state_revision_;
  latest_brush_raster_job_ = make_async_mask_job(
      QStringLiteral("brush_rasterization"),
      QStringLiteral("interactive"),
      asset_id_,
      file_path_,
      state,
      generation,
      state_revision);
  const auto request = BrushRasterCommitRequest{
      .job = latest_brush_raster_job_,
      .file_path = file_path_,
      .asset_id = asset_id_,
      .state = state,
      .mask_index = commit.mask_index,
      .mask_id = commit.mask_id,
      .mask = mask,
      .live_points = commit.live_points,
      .live_strokes = live_strokes,
      .latest_generation = latest_brush_raster_generation_,
      .generation = generation,
      .undo_state = commit.undo_state,
      .undo_state_valid = commit.undo_state_valid,
      .undo_label = commit.undo_label,
      .brush_spacing = commit.brush_spacing,
      .feather = commit.feather,
      .auto_mask_tolerance = commit.auto_mask_tolerance,
      .auto_mask = commit.auto_mask,
      .protect_edges = commit.protect_edges,
      .live_preview_elapsed_ms = commit.live_preview_elapsed_ms,
      .live_preview_within_latency_budget = commit.live_preview_within_latency_budget,
      .coalesced_stroke_count = static_cast<int>(live_strokes.size()),
      .state_revision = state_revision,
  };
  latest_brush_raster_generation_->store(request.generation, std::memory_order_relaxed);
  active_brush_raster_commit_request_ = request;
  active_brush_raster_commit_request_valid_ = true;
  active_brush_raster_commit_requeued_ = false;
  brush_raster_commit_active_ = true;
  brush_raster_commit_watcher_.setFuture(
      QtConcurrent::run([request]() { return compute_brush_raster_commit_result(request); }));
  updateProcessingState();
}

void EditorPreviewController::handleBrushRasterCommitFinished() {
  const auto result = brush_raster_commit_watcher_.result();
  publishBrushRasterCommitResult(result);
  brush_raster_commit_active_ = false;
  active_brush_raster_commit_request_valid_ = false;
  active_brush_raster_commit_requeued_ = false;
  if (!pending_brush_commits_.isEmpty()) {
    pending_brush_commit_scheduled_ = true;
    QTimer::singleShot(0, this, [this]() { processNextPendingBrushCommit(); });
  } else if (mask_thumbnail_cache_dirty_) {
    emit controlsChanged();
  }
  updateProcessingState();
  if (thumbnail_refresh_queue_pending_) {
    QTimer::singleShot(0, this, &EditorPreviewController::runQueuedThumbnailRefresh);
  }
}

void EditorPreviewController::publishBrushRasterCommitResult(
    const BrushRasterCommitResult& result) {
  const auto& request = result.request;
  const auto has_pending_replacement_for_mask = [&]() {
    for (const auto& pending_commit : pending_brush_commits_) {
      if (pending_commit.mask_id == request.mask_id) {
        return true;
      }
    }
    return false;
  };
  if (result.cancelled) {
    ++brush_raster_cancelled_count_;
    if (!has_pending_replacement_for_mask() &&
        pending_brush_commit_preview_mask_id_ == request.mask_id) {
      pending_brush_commit_preview_points_.clear();
      pending_brush_commit_preview_mask_id_.clear();
      emit activeBrushStrokeChanged();
    }
    recordCancelledMaskWork(
        QStringLiteral("brush_rasterization"),
        request.generation,
        request.latest_generation != nullptr
            ? request.latest_generation->load(std::memory_order_relaxed)
            : request.generation,
        request.state_revision,
        QStringLiteral("superseded_brush_raster_commit"),
        QStringLiteral("interactive"),
        request.mask,
        mask_tile_source_revision(
            request.file_path,
            request.state,
            raster_size_for_mask_trace(request.mask)),
        raster_size_for_mask_trace(request.mask),
        request.job);
    return;
  }
  const auto latest_generation = request.latest_generation != nullptr
      ? request.latest_generation->load(std::memory_order_relaxed)
      : request.generation;
  const auto current_state_signature = edit_state_signature(currentState());
  const auto stale =
      request.job.job_id.isEmpty() ||
      request.job.job_id != latest_brush_raster_job_.job_id ||
      request.job.generation != request.generation ||
      request.job.generation != latest_generation ||
      request.job.state_revision != request.state_revision ||
      request.job.state_signature != current_state_signature ||
      request.job.asset_id != asset_id_ ||
      request.job.file_path != file_path_ ||
      request.asset_id != asset_id_ ||
      request.file_path != file_path_ ||
      request.state_revision != mask_work_state_revision_ ||
      request.mask_index < 0 ||
      request.mask_index >= mask_stack_.size() ||
      maskDefinitionAt(request.mask_index).value(QStringLiteral("id")).toString() !=
          request.mask_id;
  if (stale || !result.success || result.mask.isEmpty()) {
    if (pending_brush_commit_preview_mask_id_ == request.mask_id) {
      pending_brush_commit_preview_points_.clear();
      pending_brush_commit_preview_mask_id_.clear();
      emit activeBrushStrokeChanged();
    }
    recordCancelledMaskWork(
        QStringLiteral("brush_rasterization"),
        request.generation,
        latest_generation,
        request.state_revision,
        stale ? QStringLiteral("stale_brush_raster_commit")
              : QStringLiteral("brush_raster_commit_failed"),
        QStringLiteral("interactive"),
        request.mask,
        mask_tile_source_revision(
            request.file_path,
            request.state,
            raster_size_for_mask_trace(request.mask)),
        raster_size_for_mask_trace(request.mask),
        request.job);
    return;
  }

  const auto previous_brush_side_effect_suspension = brush_stroke_suspends_side_effects_;
  brush_stroke_suspends_side_effects_ = true;
  const auto mask_updated = updateMaskAt(request.mask_index, result.mask, false);
  brush_stroke_suspends_side_effects_ = previous_brush_side_effect_suspension;
  const auto should_rerender = mask_updated && result.should_rerender;
  auto telemetry = QVariantMap{
      {QStringLiteral("operation"), QStringLiteral("brush_rasterization")},
      {QStringLiteral("commit_deferred"), true},
      {QStringLiteral("async_worker"), true},
      {QStringLiteral("coalesced_stroke_count"), request.coalesced_stroke_count},
      {QStringLiteral("coalesced_point_count"), request.live_points.size()},
      {QStringLiteral("raster_worker_thread"), result.worker_thread},
      {QStringLiteral("mask_raster_ms"), result.elapsed_ms},
      {QStringLiteral("cursor_budget_ms"), kMaskCursorLatencyBudgetMs},
      {QStringLiteral("cursor_elapsed_ms"), request.live_preview_elapsed_ms},
      {QStringLiteral("cursor_within_latency_budget"),
       request.live_preview_elapsed_ms <= kMaskCursorLatencyBudgetMs},
      {QStringLiteral("live_stroke_budget_ms"), kBrushLivePreviewLatencyBudgetMs},
      {QStringLiteral("live_stroke_elapsed_ms"), request.live_preview_elapsed_ms},
      {QStringLiteral("live_stroke_within_latency_budget"),
       request.live_preview_within_latency_budget},
      {QStringLiteral("preview_matte_budget_ms"), kMaskPreviewMatteLatencyBudgetMs},
      {QStringLiteral("preview_matte_elapsed_ms"), result.elapsed_ms},
      {QStringLiteral("preview_matte_within_latency_budget"),
       result.elapsed_ms <= kMaskPreviewMatteLatencyBudgetMs},
      {QStringLiteral("dirty_region_valid"), result.dirty_region.isValid()},
      {QStringLiteral("dirty_region_x"), result.dirty_region.x()},
      {QStringLiteral("dirty_region_y"), result.dirty_region.y()},
      {QStringLiteral("dirty_region_width"), result.dirty_region.width()},
      {QStringLiteral("dirty_region_height"), result.dirty_region.height()},
      {QStringLiteral("dirty_region_area"),
       result.dirty_region.isValid()
           ? result.dirty_region.width() * result.dirty_region.height()
           : 0.0},
      {QStringLiteral("raster_dirty_x"), result.changed_raster_rect.x()},
      {QStringLiteral("raster_dirty_y"), result.changed_raster_rect.y()},
      {QStringLiteral("raster_dirty_width"), result.changed_raster_rect.width()},
      {QStringLiteral("raster_dirty_height"), result.changed_raster_rect.height()},
      {QStringLiteral("incremental"), result.can_incrementally_update},
      {QStringLiteral("mask_tile_cache_entries"), maskTileCacheEntryCountForTesting()},
      {QStringLiteral("mask_tile_cache_bytes"), maskTileCacheBytesForTesting()},
      {QStringLiteral("fallback_reason"),
       result.can_incrementally_update ? QString() : QStringLiteral("full_rebuild")},
      {QStringLiteral("source_decoded"), result.source_decoded},
      {QStringLiteral("source_decode_edge"), result.source_decode_edge},
      {QStringLiteral("source_decode_width"), result.source_decode_width},
      {QStringLiteral("source_decode_height"), result.source_decode_height},
      {QStringLiteral("source_decode_bounded"), result.source_decode_bounded},
      {QStringLiteral("auto_mask_candidate_pixels"),
       QVariant::fromValue(result.auto_mask_candidate_pixels)},
      {QStringLiteral("auto_mask_edge_evaluation_pixels"),
       QVariant::fromValue(result.auto_mask_edge_evaluation_pixels)},
      {QStringLiteral("state_revision"), request.state_revision},
  };
  insert_mask_alpha_trace_fields(
      &telemetry,
      result.mask,
      mask_tile_source_revision(
          request.file_path,
          request.state,
          raster_size_for_mask_trace(result.mask)),
      raster_size_for_mask_trace(result.mask));
  insert_brush_alpha_source_fields(&telemetry, result.mask, result.changed_raster_rect);
  insert_async_mask_job_fields(&telemetry, request.job);
  recordMaskWorkTelemetry(telemetry);

  if (request.undo_state_valid && !edit_states_equal(request.undo_state, currentState())) {
    pushUndoState(request.undo_state, request.undo_label);
    redoStackForAsset(asset_id_).clear();
    redoLabelStackForAsset(asset_id_).clear();
    emit historyChanged();
  }
  persistCurrentState();
  if (pending_brush_commit_preview_mask_id_ == request.mask_id) {
    pending_brush_commit_preview_points_.clear();
    pending_brush_commit_preview_mask_id_.clear();
    emit activeBrushStrokeChanged();
  }
  if (should_rerender) {
    submitMaskRasterizationEditIntent(
        QStringLiteral("brush_stroke"),
        true,
        QStringLiteral("mask_preview_change"),
        result.dirty_region);
  }
}

void EditorPreviewController::endActiveBrushStroke() {
  if (!brush_stroke_active_) {
    return;
  }

  PendingBrushCommit commit;
  commit.mask_index = active_mask_index_;
  commit.mask = activeMaskDefinition();
  commit.mask_id = commit.mask.value(QStringLiteral("id")).toString();
  commit.live_points = active_brush_live_points_;
  commit.live_strokes.append(commit.live_points);
  commit.undo_state = brush_stroke_undo_state_;
  commit.undo_state_valid = brush_stroke_undo_state_valid_;
  auto brush_label_name = commit.mask.value(QStringLiteral("name")).toString().trimmed();
  if (brush_label_name.isEmpty()) {
    brush_label_name = QStringLiteral("Brush Mask %1").arg(qMax(1, commit.mask_index + 1));
  }
  commit.undo_label = QStringLiteral("%1 stroke").arg(brush_label_name);
  commit.brush_spacing = activeMaskBrushSpacing();
  commit.feather = activeMaskFeather();
  commit.auto_mask = activeMaskBrushAutoMask();
  commit.auto_mask_tolerance = activeMaskBrushAutoMaskTolerance();
  commit.protect_edges = activeMaskBrushProtectEdges();
  commit.live_preview_elapsed_ms = active_brush_live_preview_elapsed_ms_;
  commit.live_preview_within_latency_budget = active_brush_live_preview_within_latency_budget_;
  pending_brush_commit_preview_points_ = commit.live_points;
  pending_brush_commit_preview_mask_id_ = commit.mask_id;

  brush_stroke_active_ = false;
  brush_stroke_suspends_side_effects_ = false;
  brush_stroke_needs_final_render_ = false;
  brush_stroke_undo_state_valid_ = false;
  active_brush_auto_mask_anchor_valid_ = false;
  active_brush_live_points_.clear();
  clearActiveBrushLivePreview();
  emit activeBrushStrokeChanged();
  schedulePendingBrushCommit(std::move(commit));
}

void EditorPreviewController::addBrushPoint(double normalized_x, double normalized_y) {
  addBrushPointWithPressure(normalized_x, normalized_y, 1.0);
}

void EditorPreviewController::addBrushPointWithPressure(
    double normalized_x,
    double normalized_y,
    double pressure) {
  addBrushPointWithTablet(normalized_x, normalized_y, pressure, 0.0, 0.0);
}

void EditorPreviewController::addBrushPointWithTablet(
    double normalized_x,
    double normalized_y,
    double pressure,
    double tilt_x,
    double tilt_y) {
  addBrushPointWithTabletEraser(normalized_x, normalized_y, pressure, tilt_x, tilt_y, false);
}

void EditorPreviewController::addBrushPointWithTabletEraser(
    double normalized_x,
    double normalized_y,
    double pressure,
    double tilt_x,
    double tilt_y,
    bool eraser) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("brush")) {
    return;
  }

  const auto brush_size = activeMaskBrushSize();
  const auto brush_flow = activeMaskBrushFlow();
  const auto brush_pressure_size = activeMaskBrushPressureSize();
  const auto brush_pressure_flow = activeMaskBrushPressureFlow();
  const auto brush_pressure_opacity = activeMaskBrushPressureOpacity();
  const auto brush_spacing = activeMaskBrushSpacing();
  const auto brush_smoothing = activeMaskBrushSmoothing();
  const auto brush_erase = eraser || activeMaskBrushEraseMode();
  const auto brush_pressure = clamp_unit(pressure);
  const auto brush_tilt_x = std::clamp(tilt_x, -1.0, 1.0);
  const auto brush_tilt_y = std::clamp(tilt_y, -1.0, 1.0);
  const auto retouch_mode = activeMaskRetouchMode();
  auto points = mask.value(QStringLiteral("brushPoints")).toList();
  BrushPreviewPoint last_point;
  const BrushPreviewPoint* last_point_ptr = nullptr;
  if (brush_stroke_active_) {
    if (!active_brush_live_points_.isEmpty()) {
      last_point = active_brush_live_points_.constLast();
      last_point_ptr = &last_point;
    }
  } else if (!points.isEmpty()) {
    last_point = brush_preview_point_from_variant(
        points.constLast(),
        normalized_x,
        normalized_y,
        brush_size,
        brush_flow);
    last_point_ptr = &last_point;
  }
  auto sampled_points =
      sampled_brush_points_for_segment(
          last_point_ptr,
          normalized_x,
          normalized_y,
          brush_size,
          brush_flow,
          brush_pressure_size,
          brush_pressure_flow,
          brush_pressure_opacity,
          brush_spacing,
          brush_smoothing,
          brush_erase,
          brush_pressure,
          brush_tilt_x,
          brush_tilt_y);
  if (sampled_points.isEmpty()) {
    return;
  }
  if (activeMaskBrushAutoMask()) {
    const auto continuous_sampling = activeMaskBrushAutoMaskContinuousSampling();
    if (continuous_sampling) {
      for (auto& point : sampled_points) {
        point.auto_mask_anchor_x = point.x;
        point.auto_mask_anchor_y = point.y;
      }
    } else {
      if (brush_stroke_active_) {
        if (!active_brush_auto_mask_anchor_valid_) {
          active_brush_auto_mask_anchor_x_ = sampled_points.constFirst().x;
          active_brush_auto_mask_anchor_y_ = sampled_points.constFirst().y;
          active_brush_auto_mask_anchor_valid_ = true;
        }
        for (auto& point : sampled_points) {
          point.auto_mask_anchor_x = active_brush_auto_mask_anchor_x_;
          point.auto_mask_anchor_y = active_brush_auto_mask_anchor_y_;
        }
      } else {
        const auto anchor_x = sampled_points.constFirst().x;
        const auto anchor_y = sampled_points.constFirst().y;
        for (auto& point : sampled_points) {
          point.auto_mask_anchor_x = anchor_x;
          point.auto_mask_anchor_y = anchor_y;
        }
      }
    }
  }

  if (brush_stroke_active_) {
    for (const auto& point : sampled_points) {
      active_brush_live_points_.append(point);
    }
    updateActiveBrushLivePreview(sampled_points);
    emit activeBrushStrokeChanged();
    return;
  }

  if (retouch_mode == QStringLiteral("clone") &&
      map_bool_value(mask, QStringLiteral("cloneSourceSet"), false) &&
      (points.isEmpty() ||
       !map_bool_value(mask, QStringLiteral("cloneAligned"), true))) {
    const auto& first_point = sampled_points.constFirst();
    mask.insert(
        QStringLiteral("cloneOffsetX"),
        map_double_value(mask, QStringLiteral("cloneSourceX"), 0.5) -
            first_point.x);
    mask.insert(
        QStringLiteral("cloneOffsetY"),
        map_double_value(mask, QStringLiteral("cloneSourceY"), 0.5) -
            first_point.y);
  }

  for (const auto& point : sampled_points) {
    points.append(brush_point_variant(point));
  }
  mask.insert(QStringLiteral("brushPoints"), points);
  auto strokes = mask.value(QStringLiteral("brushStrokes")).toList();
  strokes.append(brush_stroke_variant(mask, sampled_points, static_cast<int>(strokes.size()) + 1));
  mask.insert(QStringLiteral("brushStrokes"), strokes);
  QImage source_image;
  const auto preview_edge = brush_stroke_active_ ? 640 : 1024;
  const auto has_preview_source = decodeSourceImage(&source_image, preview_edge);
  if (has_preview_source &&
      ensure_brush_raster_mask(&mask, source_image.size())) {
    if (mask.value(QStringLiteral("segmentationWidth")).toInt() != source_image.width() ||
        mask.value(QStringLiteral("segmentationHeight")).toInt() != source_image.height()) {
      mask.insert(
          QStringLiteral("segmentationData"),
          QByteArray(source_image.width() * source_image.height(), '\0'));
      mask.insert(QStringLiteral("segmentationWidth"), source_image.width());
      mask.insert(QStringLiteral("segmentationHeight"), source_image.height());
    }
    QRect changed_raster_rect;
    for (const auto& point : sampled_points) {
      const auto point_changed_rect = rasterize_brush_point_into_mask(
          &mask,
          &source_image,
          point.x,
          point.y,
          point.size,
          point.flow,
          point.opacity,
          activeMaskFeather(),
          point.erase,
          activeMaskBrushAutoMask(),
          activeMaskBrushAutoMaskTolerance(),
          point.auto_mask_anchor_x,
          point.auto_mask_anchor_y,
          activeMaskBrushProtectEdges());
      if (!point_changed_rect.isEmpty()) {
        changed_raster_rect = changed_raster_rect.isNull()
                                  ? point_changed_rect
                                  : changed_raster_rect.united(point_changed_rect);
      }
    }
    cache_mask_tiles_for_dirty_rect(mask, file_path_, currentState(), changed_raster_rect);
  }
  const auto rerender =
      mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
      mask.value(QStringLiteral("committed")).toBool();
  const auto mask_updated = updateActiveMaskDefinition(mask, false);
  if (mask_updated && rerender) {
    submitMaskRasterizationEditIntent(
        QStringLiteral("brush_point"),
        true,
        QStringLiteral("mask_preview_change"),
        dirty_region_for_brush_points(sampled_points));
  }
}

void EditorPreviewController::clearActiveBrushPoints() {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("brush")) {
    return;
  }
  pending_brush_commit_preview_points_.clear();
  pending_brush_commit_preview_mask_id_.clear();
  active_brush_live_points_.clear();
  active_brush_auto_mask_anchor_valid_ = false;
  clearActiveBrushLivePreview();
  mask.insert(QStringLiteral("brushPoints"), QVariantList{});
  mask.insert(QStringLiteral("brushStrokes"), QVariantList{});
  if (activeMaskKind() == QStringLiteral("brush")) {
    mask.insert(QStringLiteral("segmentationData"), QByteArray{});
    mask.insert(QStringLiteral("segmentationWidth"), 0);
    mask.insert(QStringLiteral("segmentationHeight"), 0);
  }
  const auto rerender =
      mask.value(QStringLiteral("toolRole")).toString() != QStringLiteral("retouch") ||
      mask.value(QStringLiteral("committed")).toBool();
  updateActiveMaskDefinition(mask, rerender);
  emit activeBrushStrokeChanged();
}

void EditorPreviewController::setActiveMaskCloneSource(double normalized_x, double normalized_y) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("brush") ||
      activeMaskRetouchMode() != QStringLiteral("clone")) {
    return;
  }
  mask.insert(QStringLiteral("cloneSourceSet"), true);
  mask.insert(QStringLiteral("cloneSourceX"), qBound(0.0, normalized_x, 1.0));
  mask.insert(QStringLiteral("cloneSourceY"), qBound(0.0, normalized_y, 1.0));
  mask.insert(QStringLiteral("cloneOffsetX"), 0.0);
  mask.insert(QStringLiteral("cloneOffsetY"), 0.0);
  mask.insert(QStringLiteral("cloneSourceIndex"), -1);
  pending_brush_commit_preview_points_.clear();
  pending_brush_commit_preview_mask_id_.clear();
  active_brush_live_points_.clear();
  clearActiveBrushLivePreview();
  mask.insert(QStringLiteral("brushPoints"), QVariantList{});
  updateActiveMaskDefinition(mask, false);
  emit activeBrushStrokeChanged();
  setStatus(QStringLiteral("Clone source picked. Paint to stamp from that area."));
}

bool EditorPreviewController::rebuildActiveBrushSegmentation(int max_edge) {
  auto mask = activeMaskDefinition();
  if (mask.isEmpty() || activeMaskKind() != QStringLiteral("brush")) {
    return false;
  }

  const auto points = mask.value(QStringLiteral("brushPoints")).toList();
  if (points.isEmpty()) {
    mask.insert(QStringLiteral("segmentationData"), QByteArray{});
    mask.insert(QStringLiteral("segmentationWidth"), 0);
    mask.insert(QStringLiteral("segmentationHeight"), 0);
    updateActiveMaskDefinition(mask, false);
    return false;
  }

  QImage source_image;
  if (!decodeSourceImage(&source_image, max_edge)) {
    return false;
  }

  if (!ensure_brush_raster_mask(&mask, source_image.size())) {
    return false;
  }
  mask.insert(
      QStringLiteral("segmentationData"),
      QByteArray(source_image.width() * source_image.height(), '\0'));
  mask.insert(QStringLiteral("segmentationWidth"), source_image.width());
  mask.insert(QStringLiteral("segmentationHeight"), source_image.height());
  for (const auto& point_value : points) {
    const auto point = point_value.toMap();
    (void)rasterize_brush_point_into_mask(
        &mask,
        &source_image,
        map_double_value(point, QStringLiteral("x"), 0.5),
        map_double_value(point, QStringLiteral("y"), 0.5),
        map_double_value(point, QStringLiteral("size"), activeMaskBrushSize()),
        map_double_value(point, QStringLiteral("flow"), activeMaskBrushFlow()),
        map_double_value(point, QStringLiteral("opacity"), 1.0),
        activeMaskFeather(),
        map_bool_value(point, QStringLiteral("erase"), false),
        activeMaskBrushAutoMask(),
        activeMaskBrushAutoMaskTolerance(),
        map_double_value(
            point,
            QStringLiteral("autoMaskAnchorX"),
            map_double_value(point, QStringLiteral("x"), 0.5)),
        map_double_value(
            point,
            QStringLiteral("autoMaskAnchorY"),
            map_double_value(point, QStringLiteral("y"), 0.5)),
        activeMaskBrushProtectEdges());
  }
  updateActiveMaskDefinition(mask, false);
  return true;
}

void EditorPreviewController::setWhiteBalanceSampling(bool enabled) {
  if (white_balance_sampling_ == enabled) {
    return;
  }
  if (enabled && crop_editing_) {
    crop_editing_ = false;
    emit controlsChanged();
  }
  if (enabled && !color_tool_sampling_target_.isEmpty()) {
    setColorToolSamplingTarget(QString());
  }
  white_balance_sampling_ = enabled;
  emit whiteBalanceSamplingChanged();
}

void EditorPreviewController::sampleWhiteBalanceAt(double normalized_x, double normalized_y) {
  if (!white_balance_sampling_) {
    return;
  }

  QImage image;
  if (!decodeSourceImage(&image, 0)) {
    setStatus(QStringLiteral("Unable to decode source for white balance sampling."));
    setWhiteBalanceSampling(false);
    return;
  }

  image = applyCrop(image);

  const auto sample_x = qBound(0, static_cast<int>(qRound(normalized_x * (image.width() - 1))), image.width() - 1);
  const auto sample_y = qBound(0, static_cast<int>(qRound(normalized_y * (image.height() - 1))), image.height() - 1);
  const auto patch_radius = qBound(
      1,
      static_cast<int>(qRound(static_cast<double>(std::min(image.width(), image.height())) * 0.015)),
      12);
  const auto patch_sample = sample_white_balance_patch(image, sample_x, sample_y, patch_radius);
  if (!patch_sample.valid) {
    setStatus(QStringLiteral("Unable to measure white balance from the selected patch."));
    setWhiteBalanceSampling(false);
    return;
  }

  const auto red = patch_sample.red;
  const auto green = patch_sample.green;
  const auto blue = patch_sample.blue;
  const auto average_rb = qMax(1e-6, (red + blue) * 0.5);
  const auto red_blue_balance = std::log2((blue + 1e-6) / (red + 1e-6));
  const auto green_balance = std::log2((green + 1e-6) / average_rb);

  beginEditTransaction();
  if (rawControlsAvailable()) {
    setRawWhiteBalanceOverride(true);
    setRawWhiteBalanceTemperature(raw_white_balance_temperature_ + red_blue_balance * 1800.0);
    setRawWhiteBalanceTint(raw_white_balance_tint_ + green_balance * 100.0);
  } else {
    setTemperature(temperature_ + red_blue_balance * 55.0);
    setTint(tint_ + green_balance * 60.0);
  }
  setWhiteBalanceSampling(false);
  endEditTransaction();
  setStatus(
      QStringLiteral("White balance sampled from a %1 px patch.")
          .arg(patch_radius * 2 + 1));
}

void EditorPreviewController::setColorToolSamplingTarget(const QString& target) {
  const auto normalized = target.trimmed().toLower();
  QString next_target;
  if (normalized == QStringLiteral("color-replace-source") ||
      normalized == QStringLiteral("color-replace-target") ||
      normalized == QStringLiteral("skin-protection")) {
    next_target = normalized;
  }
  if (color_tool_sampling_target_ == next_target) {
    return;
  }
  if (!next_target.isEmpty()) {
    setWhiteBalanceSampling(false);
    if (crop_editing_) {
      crop_editing_ = false;
      emit controlsChanged();
    }
  }
  color_tool_sampling_target_ = next_target;
  emit colorToolSamplingTargetChanged();
}

void EditorPreviewController::sampleColorToolAt(double normalized_x, double normalized_y) {
  if (color_tool_sampling_target_.isEmpty()) {
    return;
  }

  QImage image;
  if (!decodeSourceImage(&image, 0)) {
    setStatus(QStringLiteral("Unable to decode source for color sampling."));
    setColorToolSamplingTarget(QString());
    return;
  }

  image = applyCrop(image);

  const auto sample_x = qBound(0, static_cast<int>(qRound(normalized_x * (image.width() - 1))), image.width() - 1);
  const auto sample_y = qBound(0, static_cast<int>(qRound(normalized_y * (image.height() - 1))), image.height() - 1);
  const auto patch_radius = qBound(
      1,
      static_cast<int>(qRound(static_cast<double>(std::min(image.width(), image.height())) * 0.015)),
      12);
  const auto patch_sample = sample_hue_patch(image, sample_x, sample_y, patch_radius);
  if (!patch_sample.valid) {
    setStatus(QStringLiteral("Unable to measure a usable hue from the selected patch."));
    setColorToolSamplingTarget(QString());
    return;
  }

  const auto target = color_tool_sampling_target_;
  beginEditTransaction();
  if (target == QStringLiteral("color-replace-source")) {
    setColorReplacementSourceHue(patch_sample.hue);
    setColorReplacementEnabled(true);
    if (color_replacement_strength_ <= 1.0) {
      setColorReplacementStrength(70.0);
    }
  } else if (target == QStringLiteral("color-replace-target")) {
    setColorReplacementTargetHue(patch_sample.hue);
    setColorReplacementEnabled(true);
    if (color_replacement_strength_ <= 1.0) {
      setColorReplacementStrength(70.0);
    }
  } else if (target == QStringLiteral("skin-protection")) {
    setSkinToneProtectionEnabled(true);
    setSkinToneLineHue(patch_sample.hue);
    if (skin_tone_protection_strength_ <= 1.0) {
      setSkinToneProtectionStrength(75.0);
    }
  }
  setColorToolSamplingTarget(QString());
  endEditTransaction();

  setStatus(
      QStringLiteral("Hue sampled from a %1 px patch.")
          .arg(patch_radius * 2 + 1));
}

bool EditorPreviewController::autoDetectSkinProtection() {
  QImage image;
  if (!decodeSourceImage(&image, 512)) {
    setStatus(QStringLiteral("Unable to decode source for skin detection."));
    return false;
  }
  image = applyCrop(image).convertToFormat(QImage::Format_ARGB32);
  if (image.isNull() || image.width() <= 0 || image.height() <= 0) {
    setStatus(QStringLiteral("Unable to inspect source for skin detection."));
    return false;
  }

  const auto state = currentState();
  const auto exposure_gain = std::pow(2.0, state.exposure);
  const auto white_balance = preview_white_balance_multipliers(state.temperature, state.tint);
  auto sin_sum = 0.0;
  auto cos_sum = 0.0;
  auto weight_sum = 0.0;
  auto candidate_count = 0;

  for (int y = 0; y < image.height(); ++y) {
    const auto* scanline = reinterpret_cast<const QRgb*>(image.constScanLine(y));
    for (int x = 0; x < image.width(); ++x) {
      const QColor color(scanline[x]);
      photo_editor::pipeline::ColorPixel pixel{
          .red = static_cast<float>(std::max(
              0.0,
              photo_editor::pipeline::srgb_to_linear(color.redF()) * exposure_gain *
                  white_balance[0])),
          .green = static_cast<float>(std::max(
              0.0,
              photo_editor::pipeline::srgb_to_linear(color.greenF()) * exposure_gain *
                  white_balance[1])),
          .blue = static_cast<float>(std::max(
              0.0,
              photo_editor::pipeline::srgb_to_linear(color.blueF()) * exposure_gain *
                  white_balance[2])),
          .alpha = color.alphaF(),
      };
      auto hue = 0.0;
      auto saturation = 0.0;
      auto value = 0.0;
      hue_saturation_value_for_preview_pixel(pixel, &hue, &saturation, &value);
      const auto weight = skin_candidate_weight(hue, saturation, value);
      if (weight <= 0.08) {
        continue;
      }
      const auto angle = hue * 2.0 * M_PI;
      sin_sum += std::sin(angle) * weight;
      cos_sum += std::cos(angle) * weight;
      weight_sum += weight;
      ++candidate_count;
    }
  }

  const auto total_pixels = image.width() * image.height();
  if (weight_sum <= 1e-6 || candidate_count < std::max(8, total_pixels / 150)) {
    setStatus(QStringLiteral("No reliable skin-tone range found."));
    return false;
  }

  auto detected_hue = std::atan2(sin_sum, cos_sum) / (2.0 * M_PI);
  detected_hue = wrap_unit(detected_hue);

  auto weighted_spread = 0.0;
  auto spread_weight = 0.0;
  for (int y = 0; y < image.height(); ++y) {
    const auto* scanline = reinterpret_cast<const QRgb*>(image.constScanLine(y));
    for (int x = 0; x < image.width(); ++x) {
      const QColor color(scanline[x]);
      photo_editor::pipeline::ColorPixel pixel{
          .red = static_cast<float>(std::max(
              0.0,
              photo_editor::pipeline::srgb_to_linear(color.redF()) * exposure_gain *
                  white_balance[0])),
          .green = static_cast<float>(std::max(
              0.0,
              photo_editor::pipeline::srgb_to_linear(color.greenF()) * exposure_gain *
                  white_balance[1])),
          .blue = static_cast<float>(std::max(
              0.0,
              photo_editor::pipeline::srgb_to_linear(color.blueF()) * exposure_gain *
                  white_balance[2])),
          .alpha = color.alphaF(),
      };
      auto hue = 0.0;
      auto saturation = 0.0;
      auto value = 0.0;
      hue_saturation_value_for_preview_pixel(pixel, &hue, &saturation, &value);
      const auto weight = skin_candidate_weight(hue, saturation, value);
      if (weight <= 0.08) {
        continue;
      }
      weighted_spread += circular_distance_unit(hue, detected_hue) * weight;
      spread_weight += weight;
    }
  }

  const auto spread = spread_weight > 1e-6 ? weighted_spread / spread_weight : 0.05;
  const auto detected_range = qBound(18.0, (spread * 720.0) + 24.0, 62.0);
  const auto seed_strength = skin_tone_protection_strength_ <= 1.0;

  beginEditTransaction();
  setSkinToneProtectionEnabled(true);
  setSkinToneLineHue(detected_hue);
  setSkinToneProtectionRange(detected_range);
  if (seed_strength) {
    setSkinToneProtectionStrength(70.0);
  }
  setColorToolMaskPreviewEnabled(true);
  endEditTransaction();

  setStatus(
      QStringLiteral("Skin protection estimated from %1 pixels.").arg(candidate_count));
  return true;
}

void EditorPreviewController::updatePixelInspector(double normalized_x, double normalized_y) {
  normalized_x = std::clamp(normalized_x, 0.0, 1.0);
  normalized_y = std::clamp(normalized_y, 0.0, 1.0);

  QVariantMap inspector;
  inspector.insert(QStringLiteral("active"), false);
  inspector.insert(QStringLiteral("normalizedX"), normalized_x);
  inspector.insert(QStringLiteral("normalizedY"), normalized_y);

  const auto after = pixel_sample_map(pixel_inspector_preview_image_, normalized_x, normalized_y);
  const auto before = pixel_sample_map(pixel_inspector_reference_image_, normalized_x, normalized_y);
  inspector.insert(QStringLiteral("after"), after);
  inspector.insert(QStringLiteral("before"), before);
  inspector.insert(QStringLiteral("hasAfter"), after.value(QStringLiteral("valid")).toBool());
  inspector.insert(QStringLiteral("hasBefore"), before.value(QStringLiteral("valid")).toBool());

  if (after.value(QStringLiteral("valid")).toBool()) {
    inspector.insert(QStringLiteral("active"), true);
    inspector.insert(QStringLiteral("pixelX"), after.value(QStringLiteral("pixelX")).toInt());
    inspector.insert(QStringLiteral("pixelY"), after.value(QStringLiteral("pixelY")).toInt());
  }

  if (after.value(QStringLiteral("valid")).toBool() && before.value(QStringLiteral("valid")).toBool()) {
    inspector.insert(
        QStringLiteral("deltaRed"),
        after.value(QStringLiteral("red")).toInt() - before.value(QStringLiteral("red")).toInt());
    inspector.insert(
        QStringLiteral("deltaGreen"),
        after.value(QStringLiteral("green")).toInt() - before.value(QStringLiteral("green")).toInt());
    inspector.insert(
        QStringLiteral("deltaBlue"),
        after.value(QStringLiteral("blue")).toInt() - before.value(QStringLiteral("blue")).toInt());
    inspector.insert(
        QStringLiteral("deltaLuminance"),
        after.value(QStringLiteral("luminance")).toDouble() -
            before.value(QStringLiteral("luminance")).toDouble());
  }

  if (pixel_inspector_ == inspector) {
    return;
  }
  pixel_inspector_ = inspector;
  emit pixelInspectorChanged();
}

void EditorPreviewController::clearPixelInspector() {
  if (pixel_inspector_.isEmpty()) {
    return;
  }
  pixel_inspector_.clear();
  emit pixelInspectorChanged();
}

void EditorPreviewController::resolveDirtyGraphForIntent(const EditIntent& intent) {
  const auto next_resolution =
      resolve_render_graph_for_domain(intent.dirty_domain, intent.normalized_region);
  const auto should_merge_with_pending =
      interactive_render_timer_.isActive() ||
      interactive_request_pending_ ||
      full_request_pending_;
  last_render_graph_resolution_ =
      should_merge_with_pending
          ? merge_render_graph_resolutions(last_render_graph_resolution_, next_resolution)
          : next_resolution;
  render_graph_resolution_from_intent_ = true;

  QVariantMap fields{
      {QStringLiteral("asset_id"), asset_id_},
      {QStringLiteral("file_path"), file_path_},
      {QStringLiteral("operation"), intent.operation},
      {QStringLiteral("phase"), intent.phase},
      {QStringLiteral("dirty_domain"), last_render_graph_resolution_.dirty_domain},
      {QStringLiteral("dirty_stages"), last_render_graph_resolution_.dirty_stages},
      {QStringLiteral("dirty_stage_count"), last_render_graph_resolution_.dirty_stages.size()},
      {QStringLiteral("full_invalidation"), last_render_graph_resolution_.full_invalidation},
      {QStringLiteral("dirty_region_contract"),
       QStringLiteral("normalized-image-region|dependent-stage-propagation:v1")},
      {QStringLiteral("dirty_region_valid"), last_render_graph_resolution_.dirty_region.isValid()},
  };
  if (last_render_graph_resolution_.dirty_region.isValid()) {
    const auto dirty_region_area =
        last_render_graph_resolution_.dirty_region.width() *
        last_render_graph_resolution_.dirty_region.height();
    fields.insert(QStringLiteral("region_x"), last_render_graph_resolution_.dirty_region.x());
    fields.insert(QStringLiteral("region_y"), last_render_graph_resolution_.dirty_region.y());
    fields.insert(QStringLiteral("region_width"), last_render_graph_resolution_.dirty_region.width());
    fields.insert(QStringLiteral("region_height"), last_render_graph_resolution_.dirty_region.height());
    fields.insert(QStringLiteral("dirty_region_x"), last_render_graph_resolution_.dirty_region.x());
    fields.insert(QStringLiteral("dirty_region_y"), last_render_graph_resolution_.dirty_region.y());
    fields.insert(
        QStringLiteral("dirty_region_width"),
        last_render_graph_resolution_.dirty_region.width());
    fields.insert(
        QStringLiteral("dirty_region_height"),
        last_render_graph_resolution_.dirty_region.height());
    fields.insert(QStringLiteral("dirty_region_area"), dirty_region_area);
  }
  observability::logInfo(
      photoEditorPreviewLog(),
      QStringLiteral("preview.graph.resolved"),
      fields);
}

void EditorPreviewController::resolveDirtyGraphForRenderReason(const QString& reason) {
  const auto next_resolution =
      resolve_render_graph_for_domain(dirty_domain_for_render_reason(reason));
  const auto should_merge_with_pending =
      interactive_render_timer_.isActive() ||
      interactive_request_pending_ ||
      full_request_pending_;
  last_render_graph_resolution_ =
      should_merge_with_pending
          ? merge_render_graph_resolutions(last_render_graph_resolution_, next_resolution)
          : next_resolution;
  render_graph_resolution_from_intent_ = false;

  observability::logInfo(
      photoEditorPreviewLog(),
      QStringLiteral("preview.graph.resolved"),
      {
          {QStringLiteral("asset_id"), asset_id_},
          {QStringLiteral("file_path"), file_path_},
          {QStringLiteral("render_reason"), reason},
          {QStringLiteral("dirty_domain"), last_render_graph_resolution_.dirty_domain},
          {QStringLiteral("dirty_stages"), last_render_graph_resolution_.dirty_stages},
          {QStringLiteral("dirty_stage_count"), last_render_graph_resolution_.dirty_stages.size()},
          {QStringLiteral("full_invalidation"), last_render_graph_resolution_.full_invalidation},
      });
}

void EditorPreviewController::submitEditIntent(const EditIntent& intent) {
  ++edit_intent_count_;
  last_edit_intent_ = intent;

  QVariantMap fields{
      {QStringLiteral("asset_id"), asset_id_},
      {QStringLiteral("file_path"), file_path_},
      {QStringLiteral("operation"), intent.operation},
      {QStringLiteral("phase"), intent.phase},
      {QStringLiteral("dirty_domain"), intent.dirty_domain},
      {QStringLiteral("render_reason"), intent.render_reason},
      {QStringLiteral("schedule_full_resolution"), intent.schedule_full_resolution},
      {QStringLiteral("approximate_ok"), intent.approximate_ok},
  };
  if (intent.normalized_region.isValid()) {
    fields.insert(QStringLiteral("region_x"), intent.normalized_region.x());
    fields.insert(QStringLiteral("region_y"), intent.normalized_region.y());
    fields.insert(QStringLiteral("region_width"), intent.normalized_region.width());
    fields.insert(QStringLiteral("region_height"), intent.normalized_region.height());
  }
  observability::logInfo(
      photoEditorPreviewLog(),
      QStringLiteral("preview.intent.received"),
      fields);

  resolveDirtyGraphForIntent(intent);
  renderPreview(intent.schedule_full_resolution, intent.render_reason);
}

void EditorPreviewController::submitFullPipelineEditIntent(
    const QString& operation,
    bool schedule_full_resolution,
    const QString& render_reason) {
  submitEditIntent(EditIntent{
      .operation = operation,
      .dirty_domain = QStringLiteral("full_pipeline"),
      .render_reason = render_reason.isEmpty()
                           ? normalized_render_reason(QString(), schedule_full_resolution)
                           : render_reason,
      .schedule_full_resolution = schedule_full_resolution,
  });
}

